window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0002", [{"word":"accommodate","ipa_uk":"/əˈkɒmədeɪt/","ipa_us":"/əˈkɑːmədeɪt/","definition_zh":"容纳；提供住处；适应；顾及","definition_en":"to provide room for, fit, or adjust to something","core_image":"把两样东西量到同一个尺寸，让它们彼此合身","scene":"酒店前台翻着登记簿说：We can accommodate another twenty guests tonight.","sceneCN":"这里 accommodate 是「容纳、提供住处」（第 1、2 个义项：为客人安排住处、空间装得下人数）；句意：今晚我们还能再接待二十位客人。图中可辨识物件：前台、登记簿、行李箱、客房钥匙。","pos":[{"tag":"vt.","zh":"容纳；为……提供住处"},{"tag":"vt.","zh":"适应；顾及；通融"},{"tag":"vi.","zh":"适应（常与 to 连用）"}],"collocations":[{"phrase":"accommodate guests","zh":"接待客人；安排客人住宿"},{"phrase":"accommodate the needs of","zh":"满足……的需求"},{"phrase":"accommodate a request","zh":"答应请求"},{"phrase":"accommodate to change","zh":"适应变化"},{"phrase":"accommodate differences","zh":"调和分歧"}],"forms":[{"label":"三单","form":"accommodates"},{"label":"过去式","form":"accommodated"},{"label":"过去分词","form":"accommodated"},{"label":"现在分词","form":"accommodating"}],"derivatives":[{"word":"accommodation","pos":"n.","zh":"住处；住宿；调节"},{"word":"accommodating","pos":"adj.","zh":"乐于助人的；随和的"},{"word":"accommodative","pos":"adj.","zh":"适应的；调节的"},{"word":"accommodator","pos":"n.","zh":"调解者；调节装置"},{"word":"unaccommodating","pos":"adj.","zh":"不随和的；不肯通融的"}],"senses":[{"no":"01","title":"Lodging: give someone a place to stay","titleCN":"提供住处：让人住下","definition":"to provide someone with a room or place to stay","definitionCN":"为某人提供房间或住处","example":"The family accommodated two exchange students for the summer.","exampleCN":"这家人整个夏天为两名交换生提供了住处。","why":"The Latin verb meant to fit one thing to another. A guest must fit into a room, so giving lodging is measuring a bed and a roof to a person.","whyCN":"这个拉丁动词本义是“把一物调到另一物上”。客人要装进一个房间，所以提供住处就是把床铺和屋顶按人的尺寸量好。"},{"no":"02","title":"Capacity: have room for a number of people","titleCN":"容纳：空间装得下多少人或物","definition":"to have enough space for a particular number of people or things","definitionCN":"有足够空间容纳一定数量的人或物","example":"The new hall accommodates up to six hundred guests.","exampleCN":"新大厅最多可容纳六百位客人。","why":"When the thing fitted is a crowd, the question becomes how many bodies a space can measure out. The same act of fitting turns into capacity.","whyCN":"当被装进去的是一群人时，问题就变成空间能量出多少个人的位置。同一个“合身”动作就变成了容量。"},{"no":"03","title":"Adjust: change so that something fits","titleCN":"适应：调整自己或安排以配合","definition":"to change your plans or behaviour so that they fit a new situation","definitionCN":"改变计划或行为，使之适应新情况","example":"The timetable was changed to accommodate students with part-time jobs.","exampleCN":"时间表被调整，以照顾有兼职工作的学生。","why":"Here the schedule is stretched or bent so that an outside condition fits inside it. Adaptation is fitting in time rather than in space.","whyCN":"这里是把时间表拉长或弯折，让外部条件能装进去。适应就是把“合身”从空间搬到时间与条件上。"},{"no":"04","title":"Take into account: make allowances for a need","titleCN":"顾及：把某种需求考虑在内","definition":"to consider something and make allowances for it","definitionCN":"考虑到某事并为之留出余地","example":"The playground was designed to accommodate children in wheelchairs.","exampleCN":"这个游乐场在设计上照顾到了坐轮椅的孩子。","why":"If you truly make room for a need, you must notice it first. Taking something into account is the mental half of fitting.","whyCN":"若真要为一个需求腾出位置，必须先看见它。把某事物考虑在内，就是“合身”在头脑里的那一半。"},{"no":"05","title":"Oblige: help someone by bending the rules","titleCN":"通融：破例帮某人一把","definition":"to help someone by doing what they ask, especially as a favour","definitionCN":"应某人之请给予帮助，尤指作为一种人情","example":"The bank accommodated him with a short-term loan.","exampleCN":"银行通融给他了一笔短期贷款。","why":"Fitting can be done as a favour: you bend your rules to the shape of another person's need. The financial sense is simply make convenient for someone.","whyCN":"“合身”也可以是一种人情：把自己的规则弯向对方需求的形状。金融用法就是“让某人方便”。"},{"no":"06","title":"Reconcile: make two claims fit together","titleCN":"调和：让两种主张彼此相容","definition":"to reconcile two different views or demands so that both can be accepted","definitionCN":"调和两种不同观点或要求，使双方都能被接受","example":"The chair tried to accommodate both sides' demands in one proposal.","exampleCN":"主席试图在一份提案里同时照顾双方的诉求。","why":"Two claims that do not fit must be re-measured until they can share one frame. Accommodation here is reconciliation, not surrender.","whyCN":"两个原本不合的需求要被重新量过，直到能放进同一个框架。这一义的 accommodate 是“调和”，不是让步。"},{"no":"07","title":"Focus: the eye adjusts to distance","titleCN":"调节：眼睛对焦以看清远近","definition":"of the eye, to adjust the focus of the lens for seeing at different distances","definitionCN":"（眼睛）调节晶状体焦距，以便看清不同距离的物体","example":"After a few seconds, the eye accommodates and the print becomes sharp.","exampleCN":"几秒钟后，眼睛完成调节，字迹变得清晰。","why":"The lens changes its shape to fit the distance of the object. Biology borrowed the same word for the body's own measuring.","whyCN":"晶状体改变形状去“合上”物体的距离。生物学借用了同一个词，指身体自己的度量。"},{"no":"08","title":"Accommodating: a person who keeps fitting in","titleCN":"随和的：总愿意迁就别人的人","definition":"the adjective accommodating describes someone willing to help or adjust to others","definitionCN":"形容词 accommodating 指乐于助人、愿意迁就他人的","example":"The staff were accommodating and found us an extra chair.","exampleCN":"工作人员很随和，还给我们多找了一把椅子。","why":"A person who keeps adjusting to others is described by the present participle: the repeated act of fitting becomes a permanent trait.","whyCN":"一个不断迁就别人的人，用现在分词来描述：反复发生的“合身”动作变成了固定的性格。"},{"no":"09","title":"Accommodate oneself to: reshape yourself","titleCN":"使自己适应：被重塑的是自己","definition":"in the reflexive phrase accommodate oneself to, to adapt oneself to a new environment","definitionCN":"用于反身短语 accommodate oneself to，表示使自己适应新环境","example":"New employees must accommodate themselves to the team's rhythm.","exampleCN":"新员工必须让自己适应团队的节奏。","why":"The reflexive form turns the action inward: the person, not the room, is the thing being measured and reshaped.","whyCN":"反身形式把动作转向自身：被量、被重塑的是人，而不是房间。"}],"etymology":{"intro":{"en":"Accommodate comes straight from Latin accommodare, a verb about fitting one thing to another. Its modern senses branch out from that single act of measuring.","cn":"accommodate 直接来自拉丁语 accommodare，本义是把一物调到另一物上。它今天的各个义项都是从这一个“量合身”的动作分出来的。"},"items":[{"era":"LATIN (1C BC)","en":"Accommodare meant 'to make fit, adapt, apply'. It was built from ad- 'to' plus commodare 'to make fit', itself from commodus 'proper, fit, convenient'.","cn":"accommodare 意为“使适合、调整、应用”，由 ad-“朝向”加 commodare“使适合”构成，而 commodare 又来自 commodus“合宜的、方便的”。"},{"era":"LATIN ROOT","en":"Commodus is com- (here an intensive prefix) plus modus 'measure, manner'. The root idea is measuring something until it matches another thing.","cn":"commodus 由 com-（此处为加强语气前缀）加 modus“尺度、方式”构成。词根意念是量一物，直到它与另一物吻合。"},{"era":"1530s ENGLISH","en":"English borrowed the word in the 1530s with the sense 'fit one thing to another'. From the late 16c. it also meant 'make suitable' and 'furnish someone with what is wanted'.","cn":"英语在 16 世纪 30 年代借入，意为“把一物调到另一物上”。从 16 世纪后期起，又表示“使适合”和“向某人提供所需之物”。"},{"era":"1712 ENGLISH","en":"The lodging sense, 'furnish with suitable room and comfort', is recorded in 1712. The sense 'hold, contain' is a later extension of making room.","cn":"“提供合适的房间与舒适条件”这一住宿义记录于 1712 年；“容纳、装得下”是“腾出空间”的后来引申。"},{"era":"1771–MODERN ENGLISH","en":"Accommodating 'obliging, willing to yield' is recorded in 1771. Modern English also uses accommodate for the eye's focusing, a biological extension of adjusting to distance.","cn":"accommodating“乐于助人、愿意迁就”记录于 1771 年。现代英语还用 accommodate 指眼睛对焦，这是“按距离调节”在生理学上的延伸。"},{"era":"PROTO-INDO-EUROPEAN","en":"Modus is traced to PIE *med- 'to take appropriate measures', the root also seen in moderate, modest and modify. The reconstructed form is not attested in writing, so the deepest step is source uncertain.","cn":"modus 被追溯到原始印欧语 *med-“采取恰当措施”，moderate、modest、modify 也出自这个词根。重构形式没有书面记录，故最深层来源不确定。"}]},"similar":{"note":{"en":"The first group is chosen for spelling, the second for meaning, so that form and sense stay separate.","cn":"第一组按拼写挑选，第二组按词义挑选，这样词形和词义不会混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"accommodation","ipa":"/əˌkɒməˈdeɪʃn/","tag":"derived noun","definition":"a place to stay or live; also the act of adjusting. It is the noun built directly on accommodate.","definitionCN":"住处；住宿；也有“调节、适应”之意。它是直接由 accommodate 构成的名词。"},{"word":"accumulate","ipa":"/əˈkjuːmjəleɪt/","tag":"near spelling","definition":"to collect or increase gradually. It shares the ac- opening and a similar length but means piling up, not fitting in.","definitionCN":"积累；逐渐增加。它同样以 ac- 开头、长度相近，但意思是“堆起来”，不是“装得下”。"},{"word":"accustom","ipa":"/əˈkʌstəm/","tag":"near spelling","definition":"to make someone familiar with something by practice. It also means adapting, but the adaptation is by habit.","definitionCN":"使习惯。它也有“适应”之意，但这里的适应靠的是习惯。"},{"word":"accompany","ipa":"/əˈkʌmpəni/","tag":"near spelling","definition":"to go together with someone. It shares the ac- + double consonant pattern but has nothing to do with space.","definitionCN":"陪伴；伴随。它也有 ac- 加双辅音的结构，但与空间、容纳无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hold","ipa":"/həʊld/","tag":"capacity","definition":"to have enough space for a number of people or things. It is the plain everyday word for accommodate in its capacity sense.","definitionCN":"容纳；装得下。它是 accommodate 表“容量”时最日常的说法。"},{"word":"house","ipa":"/haʊz/","tag":"lodging","definition":"to provide a place for someone to live. It matches the lodging sense but is usually about longer stays.","definitionCN":"给……提供住所。它对应“提供住处”一义，但通常指较长时间的居住。"},{"word":"adapt","ipa":"/əˈdæpt/","tag":"adjustment","definition":"to change to suit new conditions. It focuses on the change itself rather than on making room.","definitionCN":"适应；改编。它强调“改变”本身，而不是“腾出空间”。"},{"word":"oblige","ipa":"/əˈblaɪdʒ/","tag":"favour","definition":"to do something for someone because they have asked. It matches the 'help as a favour' sense.","definitionCN":"应请求帮忙；施恩于。它对应“作为人情帮忙”的那一义。"},{"word":"reconcile","ipa":"/ˈrekənsaɪl/","tag":"harmonize","definition":"to make two different ideas or demands exist together. It is the explicit word for the 'fit together' sense.","definitionCN":"调和；使相容。它是“让两者合在一起”这一义最明确的说法。"},{"word":"fit","ipa":"/fɪt/","tag":"core idea","definition":"to be the right size or shape for something. It states the core image behind every sense of accommodate.","definitionCN":"合身；适合。它直接说出 accommodate 所有义项背后的核心意象。"}]}]},"mnemonics":{"normalIntro":{"en":"These links are real: the Latin pieces ad- and modus, the commodus family, and the derived forms that English actually uses.","cn":"这些联想都是真实的：拉丁成分 ad- 与 modus、commodus 词族，以及英语里实际使用的派生形式。"},"normal":[{"en":"accommodate = ad- 'to' + commodus 'convenient': to make a thing convenient for someone, which means making it fit.","cn":"accommodate = ad-“朝向”+ commodus“方便”：把某物弄得对某人方便，也就是让它合身。"},{"en":"com- + modus 'measure' also gives mode, model, moderate and modify, all built on the idea of a measure.","cn":"com- + modus“尺度”还给出 mode、model、moderate、modify，它们都建立在“尺度”这个概念上。"},{"en":"accommodation is 'lodging' because a room has to be measured to the guest; the same noun also names the eye's focusing.","cn":"accommodation 指“住宿”，因为房间要按客人的尺寸安排；同一个名词也指眼睛的对焦。"},{"en":"accommodating describes a person who keeps making room, as if the body itself were bending to fit others.","cn":"accommodating 形容一个不断给别人腾位置的人，仿佛身体本身在弯下来配合别人。"},{"en":"The hotel line 'We can accommodate you' means the staff will fit your need into the rooms they still have.","cn":"酒店那句“We can accommodate you”意思是：工作人员会把你的需求塞进他们现有的房间里。"}],"abstract":[{"en":"The core operation is measuring two different shapes until one can contain the other.","cn":"核心动作是把两个不同形状的东西量到一起，直到一个能装下另一个。"},{"en":"The thing being fitted moves outward: a person into a room, a need into a schedule, a claim into a proposal, a lens onto a distance.","cn":"被“装进去”的对象逐步外扩：人装进房间，需求装进日程，主张装进提案，晶状体对准距离。"},{"en":"So 'hold, lodge, adapt, allow for, oblige, reconcile' are not unrelated meanings; they are one act of fitting applied to different objects.","cn":"所以“容纳、住宿、适应、顾及、通融、调和”并非互不相干，而是同一个“量到合身”的动作落在不同对象上。"}]},"examples":[{"en":"The hotel can accommodate up to five hundred guests.","cn":"这家酒店最多可容纳五百位客人。"},{"en":"We rearranged the room to accommodate the new piano.","cn":"我们重新布置了房间，好放下那架新钢琴。"},{"en":"The manager agreed to accommodate our request for a later start.","cn":"经理同意通融我们晚一点开工的请求。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿康摸date”——阿康摸准了日期，把客人的行程安排得刚刚好 → accommodate 容纳、安排","word":"accommodate"},"root":"源自拉丁语 accommodare“使适合”，由 ad-“朝向”+ commodus“合宜的”（com- 一起 + modus 尺度）构成，核心是“量到合身”。","sensesIntro":{"en":"Nine senses of accommodate, all traced to one act: measuring two things together so that one fits the other. Space, time, needs, money, claims and even the eye are fitted in turn.","cn":"accommodate 的九个义项都追溯到同一个动作：把两样东西一起量，使之一方合上另一方。空间、时间、需求、金钱、主张，甚至眼睛，都依次被“量合身”。"},"semanticMap":{"core":{"en":"CORE IMAGE: two different measures brought together until they fit.","cn":"核心意象：两个不同的尺寸被量到一起，直到彼此合身。"},"chain":["MEASURE TOGETHER","FIT ONE TO ANOTHER","MAKE ROOM","HOLD AND HOUSE","OBLIGE AND RECONCILE","FOCUS THE EYE"],"branches":[{"senses":"S1 · S2","en":"SPACE FITS PEOPLE: a room is measured to a guest, and a hall is measured to a crowd.","cn":"空间合上人：房间按客人量，大厅按人群量。"},{"senses":"S3 · S4","en":"ARRANGEMENT FITS NEED: the schedule bends to time, and the design notices a need before making room.","cn":"安排合上需求：日程向时间弯折，设计先看见需求再腾位置。"},{"senses":"S5 · S8","en":"RULES BEND FOR PEOPLE: a favour fits the rule to one person, and the habit of doing so becomes the trait accommodating.","cn":"规则为人弯折：人情把规则调到某个人身上，反复这样做就成了一种随和的性格。"},{"senses":"S6 · S9","en":"TWO SIDES MEET: conflicting claims are re-measured into one frame, and the reflexive form reshapes the person instead of the room.","cn":"两边相遇：冲突的主张被重新量进同一个框架；反身形式则重塑人，而不是房间。"},{"senses":"S7","en":"THE BODY MEASURES TOO: the lens changes shape to fit distance, the biological version of the same verb.","cn":"身体也在度量：晶状体改变形状去合上距离，这是同一个动词的生理版本。"}]},"affixes":{"intro":{"en":"Accommodate is built from Latin pieces that are still visible in English: ad-, com-, modus 'measure', and the verb suffix -ate. Its derivatives add -ation, -ing, -ive and -or.","cn":"accommodate 由在英语里仍然看得见的拉丁成分构成：ad-、com-、modus“尺度”以及动词后缀 -ate。它的派生词再加上 -ation、-ing、-ive、-or。"},"latinIntro":{"en":"The Latin family rests on modus 'measure': commodus 'suitable', commoditas 'convenience', and the English borrowings commodity, commodious and modify.","cn":"这一拉丁词族建立在 modus“尺度”上：commodus“合宜的”、commoditas“便利”，以及英语借词 commodity、commodious、modify。"},"items":[{"word":"accommodate","structure":"ad- (to) + commodus (suitable) + -ate (verb)","meaning":"to make suitable, fit, or provide for","meaningCN":"使适合；容纳；提供（ad- 表朝向，-ate 构成动词）","example":"The room can accommodate four people.","exampleCN":"这个房间能容纳四个人。"},{"word":"accommodation","structure":"accommodate + -ation (noun of action)","meaning":"a place to stay; the act of adjusting","meaningCN":"住处；住宿；调节（-ation 构成动作或结果名词）","example":"The price includes flights and accommodation.","exampleCN":"这个价格包含机票和住宿。"},{"word":"accommodating","structure":"accommodate + -ing (present participle or adjective)","meaning":"willing to help or adjust to others","meaningCN":"乐于助人的；随和的（-ing 构成现在分词或形容词）","example":"The staff were very accommodating.","exampleCN":"工作人员非常随和。"},{"word":"accommodative","structure":"accommodate + -ive (adjective)","meaning":"able or tending to adapt","meaningCN":"有适应力的；调节性的（-ive 构成形容词）","example":"The eye has an accommodative mechanism.","exampleCN":"眼睛有一套调节机制。"},{"word":"accommodator","structure":"accommodate + -or (person or thing)","meaning":"one who adjusts or reconciles; a device that adjusts","meaningCN":"调解者；调节装置（-or 表示做动作的人或物）","example":"He acted as an accommodator between the two teams.","exampleCN":"他充当两个团队之间的调解人。"},{"word":"unaccommodating","structure":"un- (not) + accommodating","meaning":"not willing to help or adjust","meaningCN":"不随和的；不肯通融的（un- 表否定）","example":"The clerk was unaccommodating and refused to help.","exampleCN":"那名职员很不通融，拒绝帮忙。"},{"word":"commodious","structure":"commodus (suitable) + -ious (full of)","meaning":"roomy and convenient","meaningCN":"宽敞便利的（同一拉丁词根 commodus + -ious）","example":"The flat has a commodious kitchen.","exampleCN":"这套公寓有个宽敞的厨房。"},{"word":"commodity","structure":"com- (together) + modus (measure) + -ity","meaning":"a raw material or product that can be traded","meaningCN":"商品；大宗物资（由“量、便利”引申为可交易之物）","example":"Coffee is a major commodity in Brazil.","exampleCN":"咖啡是巴西的重要商品。"},{"word":"mode","structure":"modus (measure, manner)","meaning":"a way of doing something","meaningCN":"方式；模式（直接来自拉丁语 modus“尺度、方式”）","example":"The phone has a silent mode.","exampleCN":"这部手机有静音模式。"}],"latinEntries":[{"word":"commodity","structure":"com- + modus + -ity","meaning":"a thing of convenience or value that can be traded","meaningCN":"商品；可交易的有用之物"},{"word":"commodious","structure":"commodus + -ious","meaning":"roomy and convenient","meaningCN":"宽敞便利的"},{"word":"modify","structure":"modus (measure) + facere (make)","meaning":"to change something slightly","meaningCN":"修改；调整"},{"word":"mode","structure":"modus (measure, manner)","meaning":"a manner or way of doing something","meaningCN":"方式；模式"}]}},{"word":"accompany","ipa_uk":"/əˈkʌmpəni/","ipa_us":"/əˈkʌmpəni/","definition_zh":"陪伴；伴随；伴奏；附有","definition_en":"to go with someone, or to happen or be present together with something","core_image":"同吃一块面包的人，跟着你一起走","scene":"医院走廊里，女儿扶着母亲说：I'll accompany you to the examination room.","sceneCN":"这里 accompany 是「陪同、陪伴」（第 1 个义项：跟着某人一起去某处）；句意：我陪您去检查室。图中可辨识物件：医院走廊、轮椅、检查室门牌、母女。","pos":[{"tag":"vt.","zh":"陪同；伴随；护送"},{"tag":"vt.","zh":"为……伴奏"},{"tag":"vt.","zh":"附有；与……同时发生"}],"collocations":[{"phrase":"accompany somebody to","zh":"陪某人去……"},{"phrase":"be accompanied by","zh":"由……陪同；附有……"},{"phrase":"accompany somebody on the piano","zh":"用钢琴为某人伴奏"},{"phrase":"accompany a request with a letter","zh":"随请求附上一封信"},{"phrase":"accompanying circumstances","zh":"伴随情况；相关情形"}],"forms":[{"label":"三单","form":"accompanies"},{"label":"过去式","form":"accompanied"},{"label":"过去分词","form":"accompanied"},{"label":"现在分词","form":"accompanying"}],"derivatives":[{"word":"accompaniment","pos":"n.","zh":"伴奏；伴随物"},{"word":"accompanist","pos":"n.","zh":"伴奏者"},{"word":"companion","pos":"n.","zh":"同伴；伴侣"},{"word":"companionship","pos":"n.","zh":"陪伴；友谊"},{"word":"unaccompanied","pos":"adj.","zh":"无人陪伴的；无伴奏的"},{"word":"accompanying","pos":"adj.","zh":"伴随的；随行的"}],"senses":[{"no":"01","title":"Go with a person","titleCN":"陪同：跟某人一起去","definition":"to go with someone to a place or on a journey","definitionCN":"陪某人去某地或一起旅行","example":"Her brother accompanied her to the airport.","exampleCN":"她哥哥陪她去了机场。","why":"The word began with the image of a companion, one who shares bread and therefore walks beside you. Going together is the core sense.","whyCN":"这个词最初是“同伴”的形象：分吃同一块面包的人，自然会走在你身边。因此“一起去”是核心义。"},{"no":"02","title":"Escort: travel with for protection or courtesy","titleCN":"护送：出于保护或礼节随行","definition":"to travel with someone, especially to protect or guide them","definitionCN":"（为保护或引导而）随行、护送","example":"The minister was accompanied by two bodyguards.","exampleCN":"部长由两名保镖随行护卫。","why":"A companion who walks beside you can also stand between you and danger. The same 'go with' gains the colour of protection or ceremony.","whyCN":"走在你身边的同伴，也可以站在你与危险之间。同一个“跟着走”就带上了保护或礼仪的色彩。"},{"no":"03","title":"Happen together","titleCN":"伴随发生：同时出现","definition":"to happen at the same time as something else, or to be present with it","definitionCN":"与另一事物同时发生，或与之同时存在","example":"Thunder usually accompanies lightning.","exampleCN":"雷声通常伴随着闪电。","why":"Two events can walk side by side in time just as two people walk side by side in space. The companion image moves from space to time.","whyCN":"两个事件在时间上可以并肩而行，就像两个人在空间里并肩而行。同伴的形象从空间搬到了时间上。"},{"no":"04","title":"Play or sing in support","titleCN":"伴奏：用乐器跟着主旋律","definition":"to play music or sing while someone else is the main performer","definitionCN":"在他人主唱或主奏时为其伴奏","example":"He accompanied the singer on the piano.","exampleCN":"他用钢琴为那位歌手伴奏。","why":"In music, the supporting part follows the main melody as a companion follows a walker. The word names the follower, not the leader.","whyCN":"在音乐里，伴奏声部跟着主旋律走，如同同伴跟着走路的人。这个词命名的是跟随者，不是领路人。"},{"no":"05","title":"Be attached to a document","titleCN":"附有：文件、款项随主件而来","definition":"to be sent or supplied together with something else","definitionCN":"与另一物一起送出或提供；附有","example":"The application must be accompanied by two photographs.","exampleCN":"申请表必须附上两张照片。","why":"A letter can travel with a photograph just as a person travels with a companion. The passive phrase accompanied by extends the walking image to things.","whyCN":"一封信可以和一张照片一起走，就像一个人和同伴一起走。被动短语 accompanied by 把“同行”的形象扩展到了物件。"},{"no":"06","title":"Accompanied by: escorted or marked by","titleCN":"由……陪同；伴随着（正式短语）","definition":"in the phrase be accompanied by, to have someone or something with you","definitionCN":"用于 be accompanied by，表示身边有某人或某物","example":"She was accompanied by her lawyer at the meeting.","exampleCN":"开会时她由律师陪同。","why":"This fixed passive turns the companion into a condition around the main person. What is with you can be a protector, a document, or even a symptom.","whyCN":"这个固定被动结构把“同伴”变成主角周围的一种条件。跟着你的可以是护卫、文件，甚至一种症状。"},{"no":"07","title":"Accompaniment: the thing that comes along","titleCN":"伴随物；伴奏（名词形式）","definition":"the noun accompaniment names music that supports a performer, or something that goes with another thing","definitionCN":"名词 accompaniment 指为表演者伴奏的音乐，或与另一物相伴出现的东西","example":"The violin solo came with a simple piano accompaniment.","exampleCN":"那首小提琴独奏配有一段简单的钢琴伴奏。","why":"The -ment noun turns the follower into a thing: whatever walks beside the main event. In music it is the supporting part; elsewhere it is a side dish or a side effect.","whyCN":"-ment 名词把“跟随者”变成一件东西：任何走主要事件旁边的事物。在音乐里是伴奏声部，在别处就是配菜或副作用。"},{"no":"08","title":"Accompanying: the adjective of going along","titleCN":"伴随的：作为形容词的“随行”","definition":"the present participle accompanying describes something that goes with or supports the main thing","definitionCN":"现在分词 accompanying 作形容词，指伴随或辅助主要事物的","example":"Please read the accompanying notes before you sign.","exampleCN":"签字前请先阅读随附说明。","why":"The participle freezes the action into a description: the notes are not a person, but they still walk beside the contract.","whyCN":"分词把动作凝固成一种描述：说明并不是人，却仍然“走”在合同旁边。"},{"no":"09","title":"Unaccompanied: without a companion or support","titleCN":"无人陪伴的；无伴奏的","definition":"the adjective unaccompanied means travelling or performing alone, with no companion or musical support","definitionCN":"形容词 unaccompanied 指独自出行或独自表演，无人陪伴、也无伴奏","example":"She travelled unaccompanied for the first time at sixteen.","exampleCN":"她十六岁时第一次独自出行。","why":"Un- removes the companion. The word then measures the same walk with nobody beside it, which is why it can mean alone on a journey or alone on a stage.","whyCN":"un- 把同伴拿掉。这个词于是描述同一条路却无人并肩的情形，所以既能指独自旅行，也能指舞台上无伴奏。"}],"etymology":{"intro":{"en":"Accompany reached English through Old French, but its oldest image is Latin: a companion is literally one who shares bread with you.","cn":"accompany 经由古法语进入英语，但它最古老的意象来自拉丁语：companion 字面就是“与你分吃面包的人”。"},"items":[{"era":"LATE LATIN (4C–6C)","en":"Companionem meant 'bread fellow, messmate', from com- 'together' plus panis 'bread'. The word is first found in the 6c. Frankish Lex Salica.","cn":"companionem 意为“同吃面包的人、饭伴”，由 com-“一起”加 panis“面包”构成。该词最早见于 6 世纪法兰克人的《萨利克法典》。"},{"era":"OLD FRENCH (12C)","en":"Acompaignier meant 'take as a companion', from à 'to' plus compaign 'companion'. It named a shared journey, not merely being nearby.","cn":"acompaignier 意为“把……当作同伴”，由 à“向”加 compaign“同伴”构成。它指的是共同上路，而不只是待在附近。"},{"era":"EARLY 15C ENGLISH","en":"English recorded accompany in the early 15c. with the sense 'be in company with'. The spelling settled as accompany afterwards.","cn":"英语在 15 世纪初记录 accompany，意为“与……同行”。此后拼写固定为 accompany。"},{"era":"1570s ENGLISH","en":"The musical sense, 'play or sing along with', is recorded by the 1570s. It applies the old idea of walking beside someone to a supporting instrument.","cn":"“为……伴奏、伴唱”的音乐义记录于 16 世纪 70 年代。它把“走在某人旁边”的旧意象用到伴奏乐器上。"},{"era":"MODERN ENGLISH","en":"The passive be accompanied by widened from people to documents, symptoms and circumstances, so that a letter, a cough or a storm can all 'come with' something.","cn":"被动式 be accompanied by 从人扩展到文件、症状和天气，于是信件、咳嗽或暴风雨都可以“伴随”某物而来。"},{"era":"PROTO-INDO-EUROPEAN","en":"Panis 'bread' is peculiar to Latin and is thought to be borrowed from a non-Indo-European language. A link to PIE *pa- 'to feed' is often suggested but not secure, so the deepest origin is source uncertain.","cn":"panis“面包”是拉丁语特有的词，一般认为借自某种非印欧语言。常有人把它联系到原始印欧语 *pa-“喂养”，但并不可靠，故最深层来源不确定。"}]},"similar":{"note":{"en":"Spelling neighbours come first; true near-synonyms follow. The two groups are kept apart on purpose.","cn":"先列拼写相近词，再列真正的近义词。两组刻意分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"companion","ipa":"/kəmˈpænjən/","tag":"same root","definition":"a person who spends time with you or travels with you. It is the noun behind accompany, not a verb.","definitionCN":"同伴；旅伴。它是 accompany 背后的名词，不是动词。"},{"word":"accomplish","ipa":"/əˈkɒmplɪʃ/","tag":"near spelling","definition":"to succeed in completing something. It shares the ac- + double consonant opening but has a completely different root.","definitionCN":"完成；实现。它同样以 ac- 加双辅音开头，但词根完全不同。"},{"word":"accommodate","ipa":"/əˈkɒmədeɪt/","tag":"near spelling","definition":"to provide room for or adjust to something. It looks close but is about fitting, not following.","definitionCN":"容纳；适应。拼写接近，但讲的是“装得下”，不是“跟着走”。"},{"word":"accomplice","ipa":"/əˈkʌmplɪs/","tag":"near spelling","definition":"a person who helps another commit a crime. It shares the ac- + compl- shape but means a partner in wrongdoing.","definitionCN":"共犯；帮凶。它也有 ac- + compl- 的形状，但指犯罪中的同伙。"}]},{"heading":"NEAR MEANING","entries":[{"word":"escort","ipa":"/ɪˈskɔːt/","tag":"protection","definition":"to go with someone to protect or guide them. It is stronger and more formal than accompany.","definitionCN":"护送；陪同。它比 accompany 更强、更正式，带有保护或引导意味。"},{"word":"attend","ipa":"/əˈtend/","tag":"formal service","definition":"to go with or look after someone in an official or servant role. It often implies duty.","definitionCN":"随侍；照料。它通常带职务或服侍的意味。"},{"word":"convoy","ipa":"/kənˈvɔɪ/","tag":"group escort","definition":"to travel with a group of vehicles or ships for protection. It is used for moving groups, not one person.","definitionCN":"护送（车队或船队）。它用于成群的移动对象，而不是单个人。"},{"word":"join","ipa":"/dʒɔɪn/","tag":"come together","definition":"to come together with someone or something. It stresses the moment of meeting rather than the whole journey.","definitionCN":"加入；会合。它强调会合的那一刻，而不是整段同行。"},{"word":"chaperone","ipa":"/ˌʃæpəˈrəʊn/","tag":"supervision","definition":"to accompany young people in order to supervise them. The purpose is control, not company.","definitionCN":"陪同监护（年轻人）。其目的是监管，而不是作伴。"},{"word":"trail","ipa":"/treɪl/","tag":"follow behind","definition":"to follow behind someone or something. It can be unwanted or secret, unlike neutral accompany.","definitionCN":"尾随；跟随。它可能带有不被欢迎或秘密的意味，而 accompany 是中性的。"}]}]},"mnemonics":{"normalIntro":{"en":"The links below use the real Latin parts com- and panis, the real noun companion, and the musical and passive uses that English actually developed.","cn":"下面的联想使用真实的拉丁成分 com- 与 panis、真实名词 companion，以及英语实际发展出的音乐用法和被动用法。"},"normal":[{"en":"accompany = ad- 'to' + company: to join a person's company, that is, to go along with them.","cn":"accompany = ad-“朝向”+ company“同伴群体”：加入某人的队伍，也就是跟着他走。"},{"en":"companion and company share com- 'together' + panis 'bread': a companion is someone you break bread with.","cn":"companion 和 company 共享 com-“一起”+ panis“面包”：companion 就是和你分面包的人。"},{"en":"In music the accompany part walks beside the melody, which is why the verb means 'to play support'.","cn":"音乐里的伴奏声部走在旋律旁边，所以这个动词也指“伴奏”。"},{"en":"Be accompanied by began with people and then let letters, symptoms and storms 'come along', because the grammar only needs something beside the main thing.","cn":"be accompanied by 从人开始，后来让信件、症状、暴风雨也“跟着来”，因为语法上只需要有东西在主物旁边。"},{"en":"accompaniment is the thing that comes along; accompanist is the person who plays it. The suffixes -ment and -ist keep those two roles apart.","cn":"accompaniment 是跟着来的东西；accompanist 是演奏它的人。后缀 -ment 与 -ist 把这两个角色分开。"}],"abstract":[{"en":"The core geometry is side by side: one thing moves, and another moves with it on the same path or at the same time.","cn":"核心几何关系是“并肩”：一个东西在动，另一个沿着同一条路、或在同一时间跟它一起动。"},{"en":"The companion can be a person, a sound, a document, a symptom or a circumstance; only the medium changes, not the relation.","cn":"同伴可以是人、声音、文件、症状或情况；变的只是载体，关系本身没变。"},{"en":"So 'escort, happen together, accompany on the piano, be attached' are one relation of accompaniment seen in four different worlds.","cn":"所以“护送、同时发生、钢琴伴奏、附有”都是同一种“伴随”关系在四个不同世界里的样子。"}]},"examples":[{"en":"I will accompany you to the station.","cn":"我陪你去车站。"},{"en":"Heavy rain was accompanied by strong winds.","cn":"大雨伴随着强风。"},{"en":"The pianist accompanied her while she sang.","cn":"她唱歌时，钢琴师为她伴奏。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿康陪你”——阿康陪着你一起走 → accompany 陪伴、伴随","word":"accompany"},"root":"源自晚期拉丁语 companionem“同吃面包的人”（com- 一起 + panis 面包），经古法语 acompaignier 进入英语，核心是“并肩同行”。","sensesIntro":{"en":"Nine senses of accompany, all built on one relation: something goes beside something else. The companion may be a person, a sound, an event, a document, or a musical part.","cn":"accompany 的九个义项都建立在同一种关系上：一个事物走在另一个事物旁边。这个“同伴”可以是人、声音、事件、文件，也可以是一个音乐声部。"},"semanticMap":{"core":{"en":"CORE IMAGE: a companion walking beside you, sharing the same path.","cn":"核心意象：一个同伴走在你身边，共享同一条路。"},"chain":["SHARE BREAD","BECOME A COMPANION","GO TOGETHER","ESCORT AND PROTECT","HAPPEN TOGETHER","PLAY SUPPORT"],"branches":[{"senses":"S1 · S2","en":"PERSON WITH PERSON: the companion walks beside you, first as company, then as protection or ceremony.","cn":"人与人的并肩：同伴先是以作伴的身份走在你身边，随后带上保护或礼仪的色彩。"},{"senses":"S3 · S6","en":"EVENT WITH EVENT: two things occur together, and the passive phrase names whatever is present beside the main thing.","cn":"事件与事件的并肩：两件事同时发生，被动短语则命名主物旁边存在的东西。"},{"senses":"S4 · S7","en":"SOUND WITH SOUND: a supporting part follows the melody, and the -ment noun names that supporting part.","cn":"声音与声音的并肩：辅助声部跟着主旋律，-ment 名词命名这个辅助声部。"},{"senses":"S5","en":"THING WITH THING: a document or object is sent along with the main item, as if it too were walking beside it.","cn":"物与物的并肩：文件或物件随主件一起送出，仿佛它也在旁边走。"},{"senses":"S8 · S9","en":"STATE AND PRIVATION: the participle turns accompaniment into a description, and un- removes the companion entirely.","cn":"状态与缺失：分词把“伴随”变成一种描述，un- 则把同伴整个拿掉。"}]},"affixes":{"intro":{"en":"Accompany is a verb with a French shape but a Latin core. Its derivatives use -ment, -ist, -ing and the negative un-, while the companion family keeps com- and panis visible.","cn":"accompany 是法语外形、拉丁内核的动词。它的派生词用到 -ment、-ist、-ing 和否定前缀 un-；companion 词族则保留着 com- 与 panis 的痕迹。"},"latinIntro":{"en":"The Latin core is com- 'together' plus panis 'bread'. English relatives include companion, company and pantry, all originally about bread or shared supplies.","cn":"拉丁内核是 com-“一起”加 panis“面包”。英语同族词包括 companion、company、pantry，最初都与面包或共享的口粮有关。"},"items":[{"word":"accompany","structure":"ac- (ad-, to) + company (companion)","meaning":"to go along with someone","meaningCN":"陪同；伴随（ac- 表朝向，company 表同伴）","example":"A guide accompanied us through the museum.","exampleCN":"一位向导陪我们参观了博物馆。"},{"word":"accompaniment","structure":"accompany + -ment (noun of result)","meaning":"music that supports a performer; something that goes with another thing","meaningCN":"伴奏；伴随物（-ment 构成结果名词）","example":"The soup came with a small accompaniment of bread.","exampleCN":"这道汤配了一小份面包。"},{"word":"accompanist","structure":"accompany + -ist (person who does)","meaning":"a person who plays music to support another performer","meaningCN":"伴奏者（-ist 表示从事某活动的人）","example":"She works as a piano accompanist.","exampleCN":"她是一名钢琴伴奏者。"},{"word":"companion","structure":"com- (together) + panis (bread) + -ion","meaning":"a person who shares bread or time with another","meaningCN":"同伴；伴侣（com- 一起 + panis 面包）","example":"The old dog was his only companion.","exampleCN":"那条老狗是他唯一的伙伴。"},{"word":"companionship","structure":"companion + -ship (state or relationship)","meaning":"the state of having a companion; friendship","meaningCN":"陪伴；友谊（-ship 表示状态或关系）","example":"She values the companionship of old friends.","exampleCN":"她很珍视老友的陪伴。"},{"word":"unaccompanied","structure":"un- (not) + accompanied","meaning":"without a companion or without musical support","meaningCN":"无人陪伴的；无伴奏的（un- 表否定）","example":"Children under twelve may not travel unaccompanied.","exampleCN":"十二岁以下儿童不得独自出行。"},{"word":"accompanying","structure":"accompany + -ing (participle or adjective)","meaning":"going along with; attached to the main thing","meaningCN":"伴随的；随附的（-ing 构成分词或形容词）","example":"Read the accompanying instructions first.","exampleCN":"请先阅读随附说明。"},{"word":"company","structure":"com- (together) + panis (bread) + -y","meaning":"the state of being with others; a group or firm","meaningCN":"陪伴；一群人；公司（同源，原指同吃面包的群体）","example":"I enjoy his company on long walks.","exampleCN":"我喜欢长途散步时有他作伴。"},{"word":"pantry","structure":"panis (bread) + -ry (place)","meaning":"a small room where food is kept","meaningCN":"食品储藏室（panis 面包 + -ry 表场所）","example":"We keep rice and flour in the pantry.","exampleCN":"我们把米和面储存在食品柜里。"}],"latinEntries":[{"word":"companion","structure":"com- + panis + -ion","meaning":"one who shares bread with another","meaningCN":"同吃面包的人；同伴"},{"word":"company","structure":"com- + panis + -y","meaning":"a group that shares food or life; companions","meaningCN":"同食同行的群体；陪伴"},{"word":"pantry","structure":"panis + -ry","meaning":"a place for storing bread and food","meaningCN":"储存面包与食物的地方"}]}},{"word":"accomplish","ipa_uk":"/əˈkʌmplɪʃ/","ipa_us":"/əˈkɑːmplɪʃ/","definition_zh":"完成；实现；达到","definition_en":"to succeed in doing or completing something","core_image":"把空缺填满，让一件事变得完整","scene":"马拉松终点，教练拍着选手的肩说：You accomplished what you trained for.","sceneCN":"这里 accomplish 是「完成、实现」（第 1、2 个义项：完成计划中的任务、达成既定目标）；句意：你完成了你为之训练的目标。图中可辨识物件：终点拱门、计时牌、奖牌、教练。","pos":[{"tag":"vt.","zh":"完成；实现；达到"},{"tag":"adj.","zh":"（accomplished）技艺娴熟的；有造诣的"}],"collocations":[{"phrase":"accomplish a task","zh":"完成一项任务"},{"phrase":"accomplish a goal","zh":"实现一个目标"},{"phrase":"accomplish a feat","zh":"完成一项壮举"},{"phrase":"accomplish one's purpose","zh":"达到目的"},{"phrase":"a sense of accomplishment","zh":"成就感"}],"forms":[{"label":"三单","form":"accomplishes"},{"label":"过去式","form":"accomplished"},{"label":"过去分词","form":"accomplished"},{"label":"现在分词","form":"accomplishing"}],"derivatives":[{"word":"accomplishment","pos":"n.","zh":"成就；完成"},{"word":"accomplished","pos":"adj.","zh":"有造诣的；熟练的"},{"word":"unaccomplished","pos":"adj.","zh":"未完成的；没有成就的"},{"word":"accomplishable","pos":"adj.","zh":"可完成的"},{"word":"accomplisher","pos":"n.","zh":"完成者"}],"senses":[{"no":"01","title":"Complete a task","titleCN":"完成任务：把该做的做完","definition":"to finish a task that has been started","definitionCN":"把已经开始的任务做完","example":"We accomplished the repairs before the storm arrived.","exampleCN":"我们在暴风雨来临前完成了维修。","why":"The Latin source means 'to fill up'. A task is a container with empty places; filling them all means the task is complete.","whyCN":"拉丁语来源意为“填满”。任务是一个有空缺的容器，把所有空缺填上，任务就完成了。"},{"no":"02","title":"Achieve a goal or plan","titleCN":"实现目标或计划","definition":"to succeed in reaching a goal or carrying out a plan","definitionCN":"成功达到目标或执行计划","example":"The team accomplished its goal of finishing the bridge by June.","exampleCN":"团队实现了六月底前建成大桥的目标。","why":"A goal is a shape drawn in advance. Accomplishing it means filling that shape exactly, so the plan is no longer hollow.","whyCN":"目标是一个事先画好的形状。accomplish 它，就是把这个形状恰好填满，计划不再空心。"},{"no":"03","title":"Fulfill a promise or mission","titleCN":"履行承诺或使命","definition":"to carry out a promise, duty, or mission fully","definitionCN":"完整履行承诺、职责或使命","example":"The soldiers accomplished their mission without a single casualty.","exampleCN":"士兵们完成了使命，无一人伤亡。","why":"A promise is a space you have agreed to fill. Fulfilling it is the same filling, now measured by a given word rather than by a task.","whyCN":"承诺是你答应去填满的空间。履行承诺仍是同一个“填满”动作，只是衡量的依据从任务变成了诺言。"},{"no":"04","title":"Succeed in something difficult","titleCN":"做成难事：克服阻力达成","definition":"to succeed in doing something difficult or impressive","definitionCN":"成功做成困难或令人瞩目的事","example":"They accomplished the climb in six hours.","exampleCN":"他们用六小时完成了那次攀登。","why":"A difficult thing resists being filled, like a narrow opening. Getting through it and finishing is accomplishment in its most physical form.","whyCN":"难事像狭窄的开口，抗拒被填满。穿过它并把它做完，就是 accomplishment 最具体的样子。"},{"no":"05","title":"Bring a work to completion","titleCN":"使竣工：让工程或作品完整","definition":"to bring a building, work, or plan to a finished state","definitionCN":"使建筑、作品或计划达到完成状态","example":"The cathedral was accomplished after nearly a century of work.","exampleCN":"这座大教堂经过近一个世纪的施工才得以建成。","why":"For a building or a work of art, completion is literal completeness: every part is present and the outline is full.","whyCN":"对建筑或艺术品而言，完成就是字面意义上的完整：每个部分都在，轮廓被填满了。"},{"no":"06","title":"Accomplished: trained to a high level","titleCN":"造诣高的：技艺已经练满","definition":"the adjective accomplished describes a person highly skilled in an art or activity","definitionCN":"形容词 accomplished 指在某项技艺上造诣高、技巧纯熟的","example":"She is an accomplished pianist.","exampleCN":"她是一位造诣很高的钢琴家。","why":"A skill is also a container: practice fills it. An accomplished player is one whose capacity has been filled to the brim, not one who has merely finished.","whyCN":"技艺也是一个容器：练习把它填满。accomplished 的人，是容量已经被填到边的人，而不只是“做完了”的人。"},{"no":"07","title":"Accomplishment: the completed result","titleCN":"成就：完成之后留下的东西","definition":"the noun accomplishment names a completed achievement or the act of completing it","definitionCN":"名词 accomplishment 指已完成的成就，或完成这一动作","example":"Winning the scholarship was her greatest accomplishment.","exampleCN":"获得奖学金是她最大的成就。","why":"The -ment noun names the filled shape itself. Once a task is full, the fullness remains as a result you can point to.","whyCN":"-ment 名词命名被填满的那个形状本身。任务填满后，这份“满”会留下来，成为你可以指认的结果。"},{"no":"08","title":"Accomplish a feat or purpose","titleCN":"立下壮举；达到目的（固定搭配）","definition":"in phrases such as accomplish a feat or accomplish one's purpose, to carry out something notable or intended","definitionCN":"用于 accomplish a feat、accomplish one's purpose 等搭配，指完成非凡之事或达成意图","example":"The rescue team accomplished a remarkable feat.","exampleCN":"救援队完成了一项了不起的壮举。","why":"A feat or a purpose is a high or distant shape. The verb still fills it, but the object now measures the scale of the achievement.","whyCN":"壮举和目的都是高远的目标形状。动词仍在“填满”它，只是宾语凸显了成就的规模。"},{"no":"09","title":"Accomplish nothing: leave the space empty","titleCN":"一无所成：什么也没填上","definition":"in the phrase accomplish nothing, to produce no result at all","definitionCN":"用于 accomplish nothing，表示毫无成果","example":"The meeting accomplished nothing except more confusion.","exampleCN":"那场会议除了带来更多混乱，一无所成。","why":"The negative phrase exposes the container image: if nothing has been put in, the task remains as empty as it began.","whyCN":"否定短语把“容器”意象露了出来：如果什么都没放进去，任务就和开始时一样空。"}],"etymology":{"intro":{"en":"Accomplish is a French-shaped word with a Latin core: ad- 'to' plus complere 'to fill up'. Its history is a steady move from filling to finishing.","cn":"accomplish 是法语外形、拉丁内核的词：ad-“朝向”加 complere“填满”。它的历史就是从“填满”稳步走向“完成”。"},"items":[{"era":"LATIN","en":"Complere meant 'to fill up, complete', from com- (here intensive) plus plere 'to fill'. Its past participle completus gave English complete.","cn":"complere 意为“填满、完成”，由 com-（此处表加强）加 plere“填满”构成。其过去分词 completus 给出了英语 complete。"},{"era":"OLD FRENCH (12C)","en":"Acomplir meant 'to fulfill, finish, complete', from Vulgar Latin *accomplere, which added ad- 'to' to complere. The image is bringing something all the way to fullness.","cn":"acomplir 意为“履行、完成”，来自俗拉丁语 *accomplere，即在 complere 前加 ad-“朝向”。意象是把某物一路填到满。"},{"era":"LATE 14C ENGLISH","en":"English borrowed the word in the late 14c. as 'fulfill, perform, carry out an undertaking'. The spelling with -ish replaced earlier -isshen forms.","cn":"英语在 14 世纪后期借入，意为“履行、执行、完成一项事业”。-ish 拼写取代了更早的 -isshen 形式。"},{"era":"LATE 14C–15C","en":"Accomplished first meant 'completed, finished' in the late 14c. From the late 15c. it meant 'perfect in acquirements as a result of training', the source of the modern 'skilled' sense.","cn":"accomplished 在 14 世纪后期先表示“已完成的”；从 15 世纪后期起表示“因训练而在才艺上完备的”，这是现代“技艺娴熟”义的来源。"},{"era":"MODERN ENGLISH","en":"Modern English keeps accomplishment for a result and accomplished for a high level of skill. The verb itself stays close to 'complete successfully'.","cn":"现代英语用 accomplishment 指成果，用 accomplished 指高超技艺。动词本身仍接近“成功地完成”。"},{"era":"PROTO-INDO-EUROPEAN","en":"Plere goes back to PIE *pele- (1) 'to fill', the same root as full, fill and plenty. The reconstructed root is widely accepted but not directly attested.","cn":"plere 可追溯到原始印欧语 *pele-（第 1 义）“填满”，与 full、fill、plenty 同根。该重构词根被广泛接受，但没有直接文献记录。"}]},"similar":{"note":{"en":"The first group differs mainly in spelling, the second mainly in nuance. Read the tags before trusting the resemblance.","cn":"第一组主要在拼写上相近，第二组主要在词义细微处相近。看标签，别只凭相似就当成同义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"accomplice","ipa":"/əˈkʌmplɪs/","tag":"near spelling","definition":"a person who helps another commit a crime. The ending -ice is not the verb ending of accomplish.","definitionCN":"共犯；帮凶。词尾 -ice 不是 accomplish 的动词词尾。"},{"word":"accompany","ipa":"/əˈkʌmpəni/","tag":"near spelling","definition":"to go with someone. It shares the ac- + double consonant opening but means companionship, not completion.","definitionCN":"陪伴；伴随。它同样以 ac- 加双辅音开头，但意思是陪伴，不是完成。"},{"word":"accommodate","ipa":"/əˈkɒmədeɪt/","tag":"near spelling","definition":"to provide room for or adjust to something. It is about fitting, not about finishing a task.","definitionCN":"容纳；适应。它讲的是“合身”，不是“把任务做完”。"},{"word":"accomplished","ipa":"/əˈkʌmplɪʃt/","tag":"derived form","definition":"highly skilled or completed. It is the past participle and adjective of accomplish, not a separate verb.","definitionCN":"技艺高超的；已完成的。它是 accomplish 的过去分词和形容词，不是另一个动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"achieve","ipa":"/əˈtʃiːv/","tag":"goal","definition":"to succeed in reaching a goal, usually after effort. It is the closest synonym for the goal sense.","definitionCN":"实现；达到（目标），通常经过努力。它是“目标”一义最接近的同义词。"},{"word":"complete","ipa":"/kəmˈpliːt/","tag":"wholeness","definition":"to finish making something whole. It stresses the finished state rather than the effort.","definitionCN":"完成；使完整。它强调最终完整的状态，而不是付出的努力。"},{"word":"fulfill","ipa":"/fʊlˈfɪl/","tag":"promise or duty","definition":"to carry out a promise, duty, or need. It is the natural verb for the promise sense.","definitionCN":"履行；满足（承诺、职责或需求）。它是“承诺”一义最自然的动词。"},{"word":"attain","ipa":"/əˈteɪn/","tag":"reach","definition":"to reach or achieve something after a long effort. It stresses arrival at a point.","definitionCN":"达到；获得。它强调经过长期努力后抵达某个点。"},{"word":"finish","ipa":"/ˈfɪnɪʃ/","tag":"end point","definition":"to bring something to an end. It can be neutral or trivial, unlike the achievement tone of accomplish.","definitionCN":"结束；做完。它可以是中性甚至琐碎的，不像 accomplish 带有成就色彩。"},{"word":"realize","ipa":"/ˈrɪəlaɪz/","tag":"make real","definition":"to make a plan or hope actually happen. It emphasizes turning an idea into reality.","definitionCN":"实现；使成真。它强调把想法变成现实。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces only: ad- plus the Latin verb meaning 'to fill', the plere family, and the actual English derivatives accomplishment and accomplished.","cn":"只用真实成分：ad- 加意为“填满”的拉丁动词、plere 词族，以及英语里实际存在的派生词 accomplishment 和 accomplished。"},"normal":[{"en":"accomplish = ad- 'to' + complere 'fill up': to fill a task all the way, leaving no gap.","cn":"accomplish = ad-“朝向”+ complere“填满”：把任务一路填满，不留缺口。"},{"en":"Plere 'to fill' also lies behind complete, complement, supply and deplete, so the whole family is about fullness or emptiness.","cn":"plere“填”也藏在 complete、complement、supply、deplete 背后，整个词族都围绕“满”与“空”。"},{"en":"Accomplishment is the filled shape left behind; the noun lets you point at the result after the work is done.","cn":"accomplishment 是填满后留下的形状；这个名词让你在完工之后还能指向那个结果。"},{"en":"An accomplished pianist is not a finished object but a person whose skill has been filled to the top by years of practice.","cn":"an accomplished pianist 不是“被完成的物件”，而是技艺被多年练习填到顶的人。"},{"en":"Accomplish nothing is the empty container: work was done, but nothing was put into it.","cn":"accomplish nothing 就是那个空容器：工夫花了，里面却什么都没装。"}],"abstract":[{"en":"The core image is a container with gaps. Every sense asks the same question: what is being filled, and how full does it have to get?","cn":"核心意象是一个有缺口的容器。每个义项都在问同一个问题：填的是什么，要填到多满？"},{"en":"A task, a goal, a promise and a mission are all empty shapes waiting to be filled; a difficult deed is a narrow shape that resists filling.","cn":"任务、目标、承诺、使命都是等待被填满的空形状；难事则是一个抗拒被填满的窄形状。"},{"en":"The past participle then splits in two directions: a completed thing and a person filled with skill, which is why accomplished can describe both a work and a pianist.","cn":"过去分词随后分成两条路：已完成的物，和被技艺填满的人——所以 accomplished 既能形容作品，也能形容钢琴家。"}]},"examples":[{"en":"She accomplished the task in half the expected time.","cn":"她用预期时间的一半完成了任务。"},{"en":"The mission was accomplished without losing a single soldier.","cn":"任务完成了，没有损失一兵一卒。"},{"en":"He is an accomplished violinist.","cn":"他是一位造诣很高的小提琴家。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿康普利事”——阿康把普利家托付的事全办利索了 → accomplish 完成、实现","word":"accomplish"},"root":"源自拉丁语 complere“填满、完成”（com- 彻底 + plere 填），经古法语 acomplir 进入英语，核心是“把空缺填满，使事情完整”。","sensesIntro":{"en":"Nine senses of accomplish, all working on one shape: an empty container is filled until it is complete. The container may be a task, a goal, a promise, a mission, a building, or a skill.","cn":"accomplish 的九个义项都在处理同一个形状：一个空容器被填满，直到完整。这个容器可以是任务、目标、承诺、使命、建筑，也可以是一项技艺。"},"semanticMap":{"core":{"en":"CORE IMAGE: filling every gap in a task until the shape is complete.","cn":"核心意象：把任务里的每个缺口填满，直到整个形状完整。"},"chain":["EMPTY SHAPE","FILL UP","COMPLETE","SUCCEED","HIGH SKILL","ACHIEVEMENT"],"branches":[{"senses":"S1 · S8","en":"A TASK IS FILLED: routine work and notable feats are both containers, differing only in size.","cn":"任务被填满：日常工作和非凡壮举都是容器，区别只在尺寸。"},{"senses":"S2 · S3","en":"A SHAPE DRAWN IN ADVANCE: a goal or a promise is a promised outline that must be filled exactly.","cn":"事先画好的形状：目标和承诺都是预先许诺的轮廓，必须按原样填满。"},{"senses":"S4","en":"A NARROW OPENING: a difficult deed resists being filled, so getting through it feels like a feat.","cn":"狭窄的开口：难事抗拒被填满，所以穿过它就像立下壮举。"},{"senses":"S5","en":"A MATERIAL WHOLE: a building or artwork is complete when every part is present.","cn":"物质整体：建筑或艺术品在每个部分都到位时才算完成。"},{"senses":"S6 · S7 · S9","en":"FULLNESS BECOMES A RESULT: skill fills a person, the result remains as an accomplishment, and no filling leaves nothing accomplished.","cn":"“满”变成结果：技艺填满一个人，结果留成 accomplishment；什么都没填，则一事无成。"}]},"affixes":{"intro":{"en":"Accomplish is built from ad- plus Latin plere 'to fill'. Its English derivatives use the native-looking suffixes -ment, -ed, -able and -er, and the negative un-.","cn":"accomplish 由 ad- 加拉丁语 plere“填”构成。它的英语派生词使用 -ment、-ed、-able、-er 这些后缀，以及否定前缀 un-。"},"latinIntro":{"en":"Latin plere 'to fill' is the common thread in complete, complement, supplement, deplete and replete. Each prefix decides whether something is filled up, filled in addition, or emptied out.","cn":"拉丁语 plere“填”是 complete、complement、supplement、deplete、replete 的共同线索。每个前缀决定它是被填满、被补充，还是被倒空。"},"items":[{"word":"accomplish","structure":"ac- (ad-, to) + complere (fill up)","meaning":"to fill a task through to its end","meaningCN":"完成；实现（ac- 表朝向，complere 表填满）","example":"She accomplished the job ahead of schedule.","exampleCN":"她提前完成了那项工作。"},{"word":"accomplishment","structure":"accomplish + -ment (noun of result)","meaning":"an achievement; the act of completing something","meaningCN":"成就；完成（-ment 构成结果名词）","example":"The bridge was a great engineering accomplishment.","exampleCN":"这座桥是一项了不起的工程成就。"},{"word":"accomplished","structure":"accomplish + -ed (past participle and adjective)","meaning":"completed; highly skilled","meaningCN":"已完成的；技艺娴熟的（-ed 构成过去分词与形容词）","example":"She is an accomplished dancer.","exampleCN":"她是一位造诣很高的舞者。"},{"word":"unaccomplished","structure":"un- (not) + accomplished","meaning":"not completed; lacking skill or achievement","meaningCN":"未完成的；没有成就的（un- 表否定）","example":"The plan remained unaccomplished.","exampleCN":"那项计划仍未完成。"},{"word":"accomplishable","structure":"accomplish + -able (can be ...ed)","meaning":"possible to complete","meaningCN":"可完成的（-able 表示“能被……的”）","example":"The task is difficult but accomplishable.","exampleCN":"这项任务很难，但可以完成。"},{"word":"accomplisher","structure":"accomplish + -er (person who does)","meaning":"a person who completes something","meaningCN":"完成者（-er 表示做某事的人）","example":"He is a quiet accomplisher rather than a talker.","exampleCN":"他是个默默做事的人，而不是空谈者。"},{"word":"complete","structure":"com- (completely) + plere (fill) + -tus (past participle)","meaning":"whole, with nothing missing","meaningCN":"完整的；完成（com- 表彻底，plere 表填）","example":"The report is now complete.","exampleCN":"这份报告现在完整了。"},{"word":"complement","structure":"com- (together) + plere (fill) + -ment","meaning":"something that fills up or completes another thing","meaningCN":"补充物；补足（com- 一起 + plere 填）","example":"A little salt is the perfect complement to the dish.","exampleCN":"一点盐是这道菜完美的补充。"},{"word":"deplete","structure":"de- (away, reverse) + plere (fill)","meaning":"to empty something out; to reduce a supply greatly","meaningCN":"耗尽；使枯竭（de- 表去除 + plere 填，即把“满”反过来）","example":"The long drought depleted the reservoirs.","exampleCN":"长期干旱耗尽了水库。"}],"latinEntries":[{"word":"complete","structure":"com- + plere + -tus","meaning":"filled up, with nothing missing","meaningCN":"填满的；完整的"},{"word":"complement","structure":"com- + plere + -ment","meaning":"that which fills up or completes","meaningCN":"补足物；补充"},{"word":"supplement","structure":"sub- (up from below) + plere","meaning":"something added to fill a gap","meaningCN":"补充；增补"},{"word":"deplete","structure":"de- + plere","meaning":"to empty out, to reverse fullness","meaningCN":"耗尽；倒空"},{"word":"replete","structure":"re- (again) + plere","meaning":"filled again; abundantly full","meaningCN":"充满的；饱足的"}]}},{"word":"accumulate","ipa_uk":"/əˈkjuːmjəleɪt/","ipa_us":"/əˈkjuːmjəleɪt/","definition_zh":"积累；积攒；堆积","definition_en":"to collect or increase gradually over a period of time","core_image":"一层层往上堆，越堆越高，堆成小丘","scene":"书桌角落，旧杂志从地板堆到窗台，室友说：Dust has accumulated behind the books.","sceneCN":"这里 accumulate 是「堆积、累积」（第 2、5 个义项：数量逐渐增多、尘埃一层层积起来）；句意：书后面已经积了一层灰。图中可辨识物件：书桌、旧杂志、窗台、灰尘。","pos":[{"tag":"vt.","zh":"积累；积攒；蓄积"},{"tag":"vi.","zh":"累积；堆积；逐渐增加"}],"collocations":[{"phrase":"accumulate wealth","zh":"积累财富"},{"phrase":"accumulate experience","zh":"积累经验"},{"phrase":"accumulate evidence","zh":"收集证据"},{"phrase":"accumulate interest","zh":"累积利息"},{"phrase":"accumulate dust","zh":"积灰"}],"forms":[{"label":"三单","form":"accumulates"},{"label":"过去式","form":"accumulated"},{"label":"过去分词","form":"accumulated"},{"label":"现在分词","form":"accumulating"}],"derivatives":[{"word":"accumulation","pos":"n.","zh":"积累；堆积物"},{"word":"accumulative","pos":"adj.","zh":"累积的；逐渐增加的"},{"word":"accumulator","pos":"n.","zh":"蓄电池；累加器"},{"word":"accumulated","pos":"adj.","zh":"累积的；积攒下来的"}],"senses":[{"no":"01","title":"Collect things over time","titleCN":"积攒：一件件收拢起来","definition":"to gather things together gradually, often until there is a large number","definitionCN":"逐渐把东西收拢起来，通常直到数量很大","example":"He accumulated a large collection of old maps.","exampleCN":"他积攒了一大批旧地图。","why":"The Latin root cumulus means 'heap'. Collecting is the first step of heaping: one thing is placed on another until a pile exists.","whyCN":"拉丁词根 cumulus 意为“小丘”。收集就是堆积的第一步：一件放在另一件上，直到形成一堆。"},{"no":"02","title":"Increase in amount or number","titleCN":"累积：数量随时间往上走","definition":"to increase gradually in quantity, especially without a single sudden cause","definitionCN":"数量逐渐增加，尤指没有一个突然的单一原因","example":"Dust accumulated on the shelves while we were away.","exampleCN":"我们不在的时候，架子上积了灰。","why":"A heap grows by small additions. When the subject is the heap itself rather than the collector, accumulate becomes intransitive and means 'grow by piling up'.","whyCN":"小丘靠一点点添加而长大。当主语是小丘本身而不是收集者时，accumulate 变为不及物，意思是“靠堆积而增长”。"},{"no":"03","title":"Amass wealth or capital","titleCN":"蓄财：把财富堆成山","definition":"to build up money, property, or capital over time","definitionCN":"随着时间积累金钱、财产或资本","example":"The family accumulated its fortune over three generations.","exampleCN":"这个家族用了三代人积累起财富。","why":"Money is the most heapable thing of all: each coin is a unit that can be added to the pile. Wealth is literally a cumulus of value.","whyCN":"金钱是最容易堆的东西：每一枚硬币都是可以加到堆上的单位。财富字面上就是价值堆成的小丘。"},{"no":"04","title":"Build up experience or knowledge","titleCN":"积累经验与知识","definition":"to gain more experience, knowledge, or skill over time","definitionCN":"随时间获得更多经验、知识或技能","example":"She accumulated twenty years of teaching experience.","exampleCN":"她积累了二十年的教学经验。","why":"Experience is not one object but many small events layered in memory. The heap becomes invisible, yet the same adding still applies.","whyCN":"经验不是一件东西，而是许多小事层层叠在记忆里。这个堆看不见，但“不断往上加”的动作仍然一样。"},{"no":"05","title":"Pile up as physical matter","titleCN":"堆积：尘土、雪、水等实物越积越厚","definition":"of physical substances, to collect and form a layer or pile","definitionCN":"（尘土、雪、水等实物）聚集并形成一层或一堆","example":"Snow accumulated against the door overnight.","exampleCN":"一夜之间，雪在门边堆了起来。","why":"This is the core image made visible again: grains, flakes or drops fall one by one and form a mound with no plan behind it.","whyCN":"这是核心意象再次变得可见：颗粒、雪花或水滴一粒粒落下，在无人安排的情况下自然堆成小丘。"},{"no":"06","title":"Accumulate interest or dividends","titleCN":"生息：利息一层层加上去","definition":"in finance, to add interest or dividends to a fund instead of paying them out","definitionCN":"在金融上，把利息或股息留在基金里而不发放，使其继续累加","example":"The account accumulates interest at four percent a year.","exampleCN":"这个账户按年利率百分之四累积利息。","why":"Interest is added to the sum, and then the larger sum earns more. The heap grows on itself, which is why the financial sense feels like a pile compounding.","whyCN":"利息被加到本金上，变大的本金又生出更多利息。堆在自己身上继续长高，所以金融义特别像“利滚利”的堆。"},{"no":"07","title":"Accumulated: the adjective of pile-up","titleCN":"累积的：已经堆起来的状态","definition":"the past participle accumulated describes something that has built up over time","definitionCN":"过去分词 accumulated 作形容词，指随着时间已经积起来的状态","example":"The accumulated snow closed the mountain road.","exampleCN":"积雪封住了山路。","why":"The participle freezes the process at its result: the pile is no longer being added to, it simply exists as accumulated matter.","whyCN":"分词把过程冻结在结果上：这堆东西不再继续添加，它只是作为“已累积之物”存在着。"},{"no":"08","title":"Accumulation: the pile and the process","titleCN":"积累：堆积的过程或堆出来的东西","definition":"the noun accumulation names both the act of accumulating and the pile that results","definitionCN":"名词 accumulation 既指积累这一动作，也指堆积出来的东西","example":"The accumulation of plastic in the ocean is a global problem.","exampleCN":"海洋中塑料的堆积是一个全球性问题。","why":"The -ation noun can look at either side of the event: the adding (process) or the heap left behind (result). English lets one word hold both.","whyCN":"-ation 名词可以看事件的两面：添加的过程，或留下的堆。英语让一个词同时装下两者。"},{"no":"09","title":"Accumulative: tending to pile up","titleCN":"累积性的：会越积越多","definition":"the adjective accumulative describes effects that add up over repeated events","definitionCN":"形容词 accumulative 指效果在反复事件中不断叠加的","example":"The drug has an accumulative effect on the body.","exampleCN":"这种药对身体有累积效应。","why":"The -ive suffix turns the heap into a tendency: each dose adds a little, and the total keeps rising even if each addition is small.","whyCN":"-ive 后缀把“堆”变成一种倾向：每一剂都加一点，即使每次添加很小，总量仍不断上升。"}],"etymology":{"intro":{"en":"Accumulate is Latin all the way down: ad- 'to' plus cumulare 'to heap', from cumulus 'heap, mound'. The word for a pile became the word for gradual increase.","cn":"accumulate 一路都来自拉丁语：ad-“朝向”加 cumulare“堆积”，而 cumulare 又来自 cumulus“堆、小丘”。表示“堆”的词，后来变成了表示“逐渐增加”的词。"},"items":[{"era":"LATIN (1C BC)","en":"Cumulus meant 'heap, pile, mound'. English later borrowed the same noun for a kind of cloud, because a cumulus cloud looks like a heap of white wool.","cn":"cumulus 意为“堆、垛、小丘”。英语后来借同一个名词指积云，因为积云看起来像一堆白羊毛。"},{"era":"LATIN VERB","en":"Accumulare meant 'to heap up, amass', from ad- 'to' (perhaps emphatic) plus cumulare 'to pile'. The past participle accumulatus is the direct source of English accumulate.","cn":"accumulare 意为“堆起、积聚”，由 ad-“朝向”（或表加强）加 cumulare“堆积”构成。过去分词 accumulatus 是英语 accumulate 的直接来源。"},{"era":"1520s ENGLISH","en":"English recorded accumulate in the 1520s as a transitive verb meaning 'to heap up'.","cn":"英语在 16 世纪 20 年代记录 accumulate，作及物动词，意为“堆起”。"},{"era":"1759 ENGLISH","en":"The intransitive sense 'to grow in size or number' is recorded from 1759. Once the pile can grow by itself, the verb no longer needs a collector as subject.","cn":"不及物义“数量或规模增长”记录于 1759 年。堆一旦能自己长高，动词就不再需要“收集者”作主语。"},{"era":"19C–MODERN ENGLISH","en":"Accumulator was applied to a device that stores energy, especially the lead-acid battery, and later to a register that adds numbers. Both keep the heap image in machinery.","cn":"accumulator 被用于储存能量的装置，尤其是铅酸蓄电池，后来又指累加寄存器。两者都把“堆”的意象带进机器。"},{"era":"PROTO-INDO-EUROPEAN","en":"Cumulus is traced to a suffixed form of PIE *keue- 'to swell'. The reconstruction is not attested in writing, so this deepest step is source uncertain.","cn":"cumulus 被追溯到原始印欧语 *keue-“膨胀”的带后缀形式。该重构没有书面记录，故这一最深层来源不确定。"}]},"similar":{"note":{"en":"Spelling look-alikes are listed first; verbs close in meaning follow. The tags name the kind of resemblance.","cn":"先列拼写形近词，再列词义相近的动词。标签说明相似的类型。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"acclimate","ipa":"/ˈækləmeɪt/","tag":"near spelling","definition":"to get used to a new climate or situation. It shares the ac- + cl- opening but means adapting, not piling up.","definitionCN":"适应新气候或新环境。它同样以 ac- + cl- 开头，但意思是适应，不是堆积。"},{"word":"accumulation","ipa":"/əˌkjuːmjəˈleɪʃn/","tag":"derived noun","definition":"the act of accumulating or the pile that results. It is the noun built on accumulate.","definitionCN":"积累；堆积物。它是建立在 accumulate 之上的名词。"},{"word":"accumulative","ipa":"/əˈkjuːmjələtɪv/","tag":"derived adjective","definition":"tending to add up over time. It is the adjective formed from accumulate, not a separate verb.","definitionCN":"累积性的。它是由 accumulate 构成的形容词，不是另一个动词。"},{"word":"accommodate","ipa":"/əˈkɒmədeɪt/","tag":"near spelling","definition":"to provide room for or adjust to something. It looks similar but is about fitting, not heaping.","definitionCN":"容纳；适应。拼写相似，但讲的是“合身”，不是“堆起来”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"amass","ipa":"/əˈmæs/","tag":"large quantity","definition":"to collect a large amount of something, especially money or information. It is stronger than accumulate.","definitionCN":"积聚（大量钱财或信息）。它比 accumulate 语气更强，强调数量大。"},{"word":"gather","ipa":"/ˈɡæðə/","tag":"bring together","definition":"to bring things together from different places. It focuses on the act of collecting, not on gradual growth.","definitionCN":"收集；聚集。它强调把散在各处的东西收拢，而不强调逐渐增长。"},{"word":"collect","ipa":"/kəˈlekt/","tag":"deliberate gathering","definition":"to bring items together, often as a hobby or for a purpose. It usually implies a person's intention.","definitionCN":"收集；收藏。它通常暗示人有意识地去做。"},{"word":"pile up","ipa":"/paɪl ʌp/","tag":"physical heap","definition":"to form a pile or to accumulate in a pile. It is the visible, physical version of accumulate.","definitionCN":"堆积起来。它是 accumulate 可见、具体的版本。"},{"word":"build up","ipa":"/bɪld ʌp/","tag":"gradual increase","definition":"to increase gradually, especially over time. It often describes pressure, reserves, or experience.","definitionCN":"逐步建立；逐渐增加。它常描述压力、储备或经验。"},{"word":"hoard","ipa":"/hɔːd/","tag":"secret storage","definition":"to store a large amount of something secretly or greedily. It adds a negative tone that accumulate lacks.","definitionCN":"囤积；秘藏。它带有 accumulate 所没有的负面色彩。"}]}]},"mnemonics":{"normalIntro":{"en":"All links here are real: ad- plus cumulus 'heap', the cloud name cumulus, and the actual derivatives accumulation, accumulative and accumulator.","cn":"这里的联想都真实：ad- 加 cumulus“堆”、云名 cumulus，以及实际存在的派生词 accumulation、accumulative、accumulator。"},"normal":[{"en":"accumulate = ad- 'to' + cumulus 'heap' + -ate: to add to a heap, one piece at a time.","cn":"accumulate = ad-“朝向”+ cumulus“堆”+ -ate：一件一件往堆上加。"},{"en":"Cumulus is also the name of the heap-shaped cloud. A cloud builds the same way: many small droplets gather into one mass.","cn":"cumulus 也是那种堆状云的名字。云的形成方式相同：许多小水滴聚成一团。"},{"en":"Accumulated interest means the interest has been added to the pile instead of being paid out, so the pile itself earns more.","cn":"accumulated interest 指利息被加进堆里而不是发出去，于是这堆钱本身又能生息。"},{"en":"Experience accumulates like dust: no single day is noticeable, but the layer becomes thick over years.","cn":"经验像灰尘一样积累：单看一天毫不起眼，几年下来却厚厚一层。"},{"en":"Accumulation is the pile or the process; accumulator is the container or device that holds the charge or the running total.","cn":"accumulation 是堆或堆积过程；accumulator 是存电或存累加值的容器、装置。"}],"abstract":[{"en":"The core shape is addition without subtraction: each new unit lands on the old surface and raises the level.","cn":"核心形状是“只加不减”：每个新单位落在旧表面上，把高度抬高一点。"},{"en":"The added units can be objects, money, experience, dust, interest or effects; the heap is sometimes visible and sometimes not.","cn":"被加的单位可以是物品、金钱、经验、灰尘、利息或效应；这个堆有时看得见，有时看不见。"},{"en":"That is why the intransitive sense is not a new meaning but a change of viewpoint: from someone heaping to the heap growing by itself.","cn":"所以不及物义并不是新意义，而是视角变化：从“有人堆”变成“堆自己长高”。"}]},"examples":[{"en":"He accumulated enough money to buy a small house.","cn":"他积攒了足够的钱，买下了一栋小房子。"},{"en":"Evidence accumulated slowly over the next two years.","cn":"证据在接下来两年里慢慢累积起来。"},{"en":"The interest accumulates in the account each month.","cn":"利息每个月在账户里累积。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿Q木累特”——阿Q把木头一块块累起来，越累越高 → accumulate 积累、堆积","word":"accumulate"},"root":"源自拉丁语 accumulare“堆起、积聚”，由 ad-“朝向”+ cumulus“堆、小丘”构成，核心是“一层层往上堆”。","sensesIntro":{"en":"Nine senses of accumulate, all built on a heap. Things, numbers, money, experience, dust, interest and effects are heaped in turn; the only change is what the pile is made of.","cn":"accumulate 的九个义项都建立在一个“堆”上。物品、数字、金钱、经验、灰尘、利息、效应依次被堆起来；变化的只是这堆东西由什么构成。"},"semanticMap":{"core":{"en":"CORE IMAGE: one unit after another added to a heap, raising its level.","cn":"核心意象：一个单位接一个单位加到堆上，把高度不断抬高。"},"chain":["ONE UNIT","ADD","HEAP","RISE","ACCUMULATED","ACCUMULATION"],"branches":[{"senses":"S1 · S3","en":"THINGS AND MONEY: deliberate collecting turns separate units into a hoard or a fortune.","cn":"物品与金钱：有意的收集把分散的单位变成一堆藏品或一笔财富。"},{"senses":"S2 · S6","en":"NUMBERS THAT GROW: quantity rises by itself, and interest adds to the sum so that the sum earns still more.","cn":"会增长的数字：数量自己往上走；利息加进本金，本金又生出更多利息。"},{"senses":"S4","en":"AN INVISIBLE HEAP: experience and knowledge accumulate as layers in memory rather than as visible objects.","cn":"看不见的堆：经验和知识作为记忆中的层积存在，而不是可见物件。"},{"senses":"S5","en":"A VISIBLE HEAP: dust, snow and water show the core image directly, one particle at a time.","cn":"看得见的堆：灰尘、雪、水直接呈现核心意象，一粒一滴地加。"},{"senses":"S7 · S8 · S9","en":"THE HEAP AS STATE, RESULT AND TENDENCY: accumulated describes its state, accumulation its product or process, accumulative its tendency.","cn":"堆作为状态、结果与倾向：accumulated 描述状态，accumulation 指产物或过程，accumulative 指倾向。"}]},"affixes":{"intro":{"en":"Accumulate is a Latin verb with a transparent English shape: ad- + cumulus + -ate. Its derivatives add -ation, -ive, -or and -ed, all still tied to the heap.","cn":"accumulate 是一个拉丁动词，英语结构清晰：ad- + cumulus + -ate。它的派生词加上 -ation、-ive、-or、-ed，都仍然围绕“堆”。"},"latinIntro":{"en":"The Latin family around cumulus is small but real: cumulare 'to heap', cumulatus 'heaped', and the English borrowings cumulate, cumulative and cumulus.","cn":"围绕 cumulus 的拉丁词族不大但真实：cumulare“堆积”、cumulatus“堆起的”，以及英语借词 cumulate、cumulative、cumulus。"},"items":[{"word":"accumulate","structure":"ad- (to) + cumulus (heap) + -ate (verb)","meaning":"to heap up; to collect gradually","meaningCN":"积累；堆积（ad- 表朝向，-ate 构成动词）","example":"They accumulated a large number of books.","exampleCN":"他们积攒了大量书籍。"},{"word":"accumulation","structure":"accumulate + -ation (noun of action or result)","meaning":"the act of accumulating or the pile that results","meaningCN":"积累；堆积物（-ation 构成动作或结果名词）","example":"The accumulation of data took ten years.","exampleCN":"数据的积累花了十年。"},{"word":"accumulative","structure":"accumulate + -ive (adjective)","meaning":"tending to add up or increase","meaningCN":"累积性的（-ive 构成形容词）","example":"The process has an accumulative effect.","exampleCN":"这个过程有累积效应。"},{"word":"accumulator","structure":"accumulate + -or (person or device)","meaning":"a device that stores energy or adds values","meaningCN":"蓄电池；累加器（-or 表示装置）","example":"The accumulator stores power for the night.","exampleCN":"蓄电池为夜间储存电力。"},{"word":"accumulated","structure":"accumulate + -ed (past participle and adjective)","meaning":"built up over time","meaningCN":"累积的；积起来的（-ed 构成过去分词与形容词）","example":"The accumulated evidence was overwhelming.","exampleCN":"累积起来的证据令人无法辩驳。"},{"word":"cumulate","structure":"cumulus (heap) + -ate (verb)","meaning":"to heap up; to combine into one mass","meaningCN":"堆积；累积（同一词根的动词）","example":"The layers cumulate over centuries.","exampleCN":"这些层历经数百年堆积起来。"},{"word":"cumulative","structure":"cumul- (heap) + -ative (adjective)","meaning":"increasing by successive additions","meaningCN":"累积的；渐增的（同一词根的形容词）","example":"The cumulative effect of small savings is large.","exampleCN":"小额储蓄的累积效应很大。"},{"word":"cumulus","structure":"cumulus (heap, mound)","meaning":"a heap; also a thick white cloud with a flat base","meaningCN":"堆；积云（直接借自拉丁语“堆”）","example":"Cumulus clouds filled the afternoon sky.","exampleCN":"积云布满了午后的天空。"},{"word":"accumulatively","structure":"accumulative + -ly","meaning":"in a way that builds up over a period of time","meaningCN":"以累积的方式（-ly 构成副词）","example":"The effects operate accumulatively.","exampleCN":"这些影响以累积的方式起作用。"},{"word":"accumulativeness","structure":"accumulative + -ness","meaning":"the quality of building up over time","meaningCN":"累积性（-ness 构成抽象名词）","example":"The accumulativeness of the damage became clear only later.","exampleCN":"损害的累积性直到后来才显现出来。"}],"latinEntries":[{"word":"cumulate","structure":"cumul- (heap) + -ate","meaning":"to heap up, to pile together","meaningCN":"堆积；累积"},{"word":"cumulative","structure":"cumul- + -ative","meaning":"growing by repeated addition","meaningCN":"累积的；渐增的"},{"word":"cumulus","structure":"cumulus (heap)","meaning":"a heap or mound; a heap-shaped cloud","meaningCN":"堆；积云"}]}},{"word":"accurate","ipa_uk":"/ˈækjərət/","ipa_us":"/ˈækjərət/","definition_zh":"准确的；精确的；严谨的","definition_en":"correct in every detail and free from error","core_image":"用心照看每个细节，不让它偏离事实","scene":"厨房里，烘焙师把温度计插进糖浆，说：The thermometer gives an accurate reading to the degree.","sceneCN":"这里 accurate 是「精确的」（第 1 个义项：测量、数字准确无误）；句意：这支温度计能精确到一度。图中可辨识物件：温度计、糖浆锅、刻度、烘焙师。","pos":[{"tag":"adj.","zh":"准确的；精确的；无误的"},{"tag":"adj.","zh":"（人、工作）严谨细致的"}],"collocations":[{"phrase":"accurate information","zh":"准确的信息"},{"phrase":"accurate measurement","zh":"精确的测量"},{"phrase":"an accurate description","zh":"准确的描述"},{"phrase":"accurate to three decimal places","zh":"精确到小数点后三位"},{"phrase":"an accurate shot","zh":"精准的一击／一枪"}],"forms":[{"label":"比较级","form":"more accurate"},{"label":"最高级","form":"most accurate"}],"derivatives":[{"word":"accuracy","pos":"n.","zh":"准确；准确度"},{"word":"accurately","pos":"adv.","zh":"准确地；精确地"},{"word":"inaccurate","pos":"adj.","zh":"不准确的；有错误的"},{"word":"inaccuracy","pos":"n.","zh":"不准确；错误"},{"word":"accurateness","pos":"n.","zh":"精确性；准确"}],"senses":[{"no":"01","title":"Exact in number or measurement","titleCN":"精确：数字与测量无误","definition":"giving a correct and exact figure, measurement, or result","definitionCN":"给出正确且精确的数字、测量或结果","example":"The scale gives an accurate reading to the nearest gram.","exampleCN":"这台秤能精确到克。","why":"The Latin source means 'prepared with care'. A number is accurate when every digit has been attended to, leaving no unexamined gap.","whyCN":"拉丁语来源意为“用心准备好的”。一个数字之所以 accurate，是因为每一位都被照看到，没有未经检查的空隙。"},{"no":"02","title":"True to the facts","titleCN":"准确属实：信息与事实相符","definition":"correct and true, with no mistakes or invented details","definitionCN":"正确属实，没有错误或编造的细节","example":"The report gave an accurate account of the accident.","exampleCN":"那篇报道对事故作了准确的叙述。","why":"Care moves from the number to the story: an account is accurate when each claim has been checked against what happened.","whyCN":"“用心”从数字移到叙述：一篇报道之所以 accurate，是因为每个说法都对照过实际发生的事。"},{"no":"03","title":"Precise in aim or action","titleCN":"精准：动作、瞄准、预测到位","definition":"done with exact aim or timing, so that it hits the intended point","definitionCN":"瞄准或时机精确，恰好落在预期点上","example":"The archer made an accurate shot from forty metres.","exampleCN":"那位弓箭手在四十米外射出了精准的一箭。","why":"The hand also takes care: it adjusts until the line of motion meets the target. Accuracy here is care expressed as physical precision.","whyCN":"手也会“用心”：它不断调整，直到运动路线与目标相交。这里的 accuracy 是把“用心”表现为身体上的精准。"},{"no":"04","title":"Faithful to the original","titleCN":"逼真：复制品与原物一致","definition":"of a copy, portrait, or recording, closely matching the original","definitionCN":"（复制品、画像、录音）与原物高度一致","example":"The museum made an accurate copy of the vase.","exampleCN":"博物馆制作了那只花瓶的逼真复制品。","why":"Care can be directed at a model: the copy is accurate when no detail has drifted away from the original it is measured against.","whyCN":"“用心”也可以对着一个原型：复制品之所以 accurate，是因为没有任何细节偏离它所对照的原物。"},{"no":"05","title":"Careful and exact as a person","titleCN":"严谨：人做事细致准确","definition":"of a person or method, careful and exact in work","definitionCN":"（人或方法）在工作中细致而准确","example":"She is accurate in checking every invoice.","exampleCN":"她核对每一张发票都很严谨。","why":"Here accuracy is a habit rather than a result: the person is the one who takes care, so the adjective describes the caretaker, not the figure.","whyCN":"这里的 accuracy 是一种习惯而非结果：人成了“照看者”，所以形容词描述的是这个人，而不是数字。"},{"no":"06","title":"Accurate to: exact down to a level","titleCN":"精确到：准确到某个刻度","definition":"in the phrase accurate to, correct down to a stated unit or decimal place","definitionCN":"用于 accurate to，表示准确到某一单位或小数位","example":"The figure is accurate to two decimal places.","exampleCN":"这个数字精确到小数点后两位。","why":"The phrase sets the edge of care: we stop measuring at that unit, and everything above it is guaranteed to be right.","whyCN":"这个短语给“用心”划了边界：量到那个单位为止，它以上的部分都保证正确。"},{"no":"07","title":"Accuracy: the quality of being exact","titleCN":"准确度：精确这一性质","definition":"the noun accuracy names the quality of being correct or exact","definitionCN":"名词 accuracy 指正确、精确这一性质","example":"The test measures the accuracy of the weather forecast.","exampleCN":"这项测试衡量天气预报的准确度。","why":"The -acy noun turns the adjective into a measurable quality. What was a careful act becomes a score you can compare.","whyCN":"-acy 名词把形容词变成一种可衡量的性质。原本用心的动作，变成了可以比较的分数。"},{"no":"08","title":"Accurately: in an exact manner","titleCN":"准确地：以精确的方式","definition":"the adverb accurately describes doing something in a correct and exact way","definitionCN":"副词 accurately 指以正确、精确的方式做某事","example":"He accurately predicted the election result.","exampleCN":"他准确地预测了选举结果。","why":"The -ly adverb turns the quality into the manner of an action: the care is now visible in how the thing is done.","whyCN":"-ly 副词把这种性质变成动作的方式：用心现在体现在“怎么做的”上。"},{"no":"09","title":"Inaccurate: falling away from exactness","titleCN":"不准确：偏离精确","definition":"the negative adjective inaccurate means not correct or not exact","definitionCN":"否定形容词 inaccurate 指不正确或不精确的","example":"The first map was inaccurate and led us the wrong way.","exampleCN":"第一张地图不准确，把我们带错了路。","why":"In- removes the care. The word then names the gap between the claim and the fact, which is the same scale read from the other end.","whyCN":"in- 把“用心”拿掉。这个词于是命名说法与事实之间的缺口，也就是同一把尺子从另一端读出来的结果。"}],"etymology":{"intro":{"en":"Accurate is a Latin loan: ad- 'to' plus curare 'to take care of', from cura 'care'. Its history is the move from 'done with care' to 'exact'.","cn":"accurate 是拉丁语借词：ad-“朝向”加 curare“照料”，而 curare 又来自 cura“关心”。它的历史就是从“用心做的”走向“精确的”。"},"items":[{"era":"LATIN","en":"Cura meant 'care, concern, attention'. It could also mean anxiety, because caring too much can turn into worry.","cn":"cura 意为“关心、关注、照料”，也可指焦虑，因为过分在意会变成担忧。"},{"era":"LATIN VERB","en":"Accurare meant 'to take care of, attend to carefully', from ad- 'to' plus curare 'to care for'. The past participle accuratus meant 'prepared with care'.","cn":"accurare 意为“照料、细心处理”，由 ad-“朝向”加 curare“关心”构成。过去分词 accuratus 意为“用心准备的”。"},{"era":"1610s ENGLISH","en":"English borrowed accurate in the 1610s with the sense 'done with care'. The notion of doing something carefully led to the modern sense 'exact, precise'.","cn":"英语在 17 世纪 10 年代借入 accurate，意为“用心做的”。由“做得仔细”发展出“精确、准确”的现代义。"},{"era":"1650s ENGLISH","en":"The sense 'precise, exact' is recorded by the 1650s. A stronger word than correct but weaker than exact, accurate describes care that reaches the details.","cn":"“精确、准确”义记录于 17 世纪 50 年代。accurate 比 correct 强、比 exact 弱，指细致到每个细节的用心。"},{"era":"17C–18C ENGLISH","en":"Accuracy and accurately were formed in English on the Latin model, and inaccurate appears in the 18th century as the negative branch.","cn":"accuracy 与 accurately 按拉丁语模式在英语中构成；inaccurate 于 18 世纪出现，是否定分支。"},{"era":"PROTO-INDO-EUROPEAN","en":"The deeper origin of Latin cura is uncertain: it may go back to Old Latin coira-, but no reliable Indo-European root is agreed. This step is source uncertain.","cn":"拉丁语 cura 的更早来源不确定：它可能追溯到古拉丁语 coira-，但没有公认可靠的印欧词根。这一步来源不确定。"}]},"similar":{"note":{"en":"Group one gathers words that look alike; group two gathers words that mean something close. The notes explain where the resemblance stops.","cn":"第一组收拼写相近的词，第二组收词义相近的词。说明会指出相似到哪里为止。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"accuracy","ipa":"/ˈækjərəsi/","tag":"derived noun","definition":"the quality of being exact. It is the noun built on accurate, not a synonym you can use in the same slot.","definitionCN":"准确度；精确性。它是建立在 accurate 上的名词，不能和形容词随意互换位置。"},{"word":"accredit","ipa":"/əˈkredɪt/","tag":"near spelling","definition":"to officially approve or attribute something to someone. It shares the acc- opening but has a different root.","definitionCN":"正式认可；把某事归功于某人。它同样以 acc- 开头，但词根不同。"},{"word":"accumulate","ipa":"/əˈkjuːmjəleɪt/","tag":"near spelling","definition":"to collect or increase gradually. The shape is close but the meaning is piling up, not being exact.","definitionCN":"积累；堆积。外形接近，但意思是堆起来，而不是精确。"},{"word":"accustom","ipa":"/əˈkʌstəm/","tag":"near spelling","definition":"to make someone used to something. It also begins with acc- but is about habit, not correctness.","definitionCN":"使习惯。它同样以 acc- 开头，但讲的是习惯，不是正确。"}]},{"heading":"NEAR MEANING","entries":[{"word":"precise","ipa":"/prɪˈsiːs/","tag":"fine detail","definition":"exact and giving attention to small details. It often stresses sharpness of definition.","definitionCN":"精确的；精细的。它常强调定义或细节的清晰锐利。"},{"word":"exact","ipa":"/ɪɡˈzækt/","tag":"no deviation","definition":"completely correct and matching a standard in every detail. It is the strictest of the group.","definitionCN":"完全正确的；与标准分毫不差的。它是这组里最严格的。"},{"word":"correct","ipa":"/kəˈrekt/","tag":"no error","definition":"free from error and in line with the facts or a rule. It is broader and less about fine measurement.","definitionCN":"正确的；无误的。它更宽泛，不太强调精细测量。"},{"word":"right","ipa":"/raɪt/","tag":"everyday","definition":"true or correct in an ordinary sense. It is the plain conversational word.","definitionCN":"对的；正确的（日常说法）。它是最口语化的表达。"},{"word":"faithful","ipa":"/ˈfeɪθfl/","tag":"copy or account","definition":"matching the original closely, used of copies, translations, or accounts. It stresses loyalty to a source.","definitionCN":"忠实于原物的。用于复制品、译文或叙述，强调对来源的忠实。"},{"word":"spot-on","ipa":"/ˈspɒt ɒn/","tag":"informal exact","definition":"completely right or exact, used informally. It often praises a guess or a description.","definitionCN":"完全正确的；一语中的（非正式）。常用来称赞猜测或描述。"}]}]},"mnemonics":{"normalIntro":{"en":"Only real material: ad- plus cura 'care', the cura family in cure, curious and secure, and the actual derivatives accuracy, accurately and inaccurate.","cn":"只用真实材料：ad- 加 cura“关心”、cura 词族在 cure、curious、secure 中的体现，以及实际存在的派生词 accuracy、accurately、inaccurate。"},"normal":[{"en":"accurate = ad- 'to' + cura 'care' + -ate: something that has been carefully attended to, so it comes out exact.","cn":"accurate = ad-“朝向”+ cura“关心”+ -ate：被认真照看过的东西，结果就精确。"},{"en":"Cura 'care' also gives cure (care for a patient), curious (full of care or inquiry) and secure (se- 'without' + cura 'care', free from worry).","cn":"cura“关心”还给出 cure（照料病人）、curious（充满关切与探究）和 secure（se-“没有”+ cura“忧虑”，即无忧）。"},{"en":"Accurate to three decimal places means care stops at that edge: every digit above it is guaranteed.","cn":"accurate to three decimal places 意思是“用心”到那个边界为止：它以上的每一位都得到保证。"},{"en":"Inaccurate is in- plus accurate: a small in- is enough to turn exactness into error.","cn":"inaccurate 是 in- 加 accurate：一个小小的 in- 就足以把精确变成错误。"},{"en":"Accuracy is the noun, accurately the adverb. The word class changes, but the same care is being measured or applied.","cn":"accuracy 是名词，accurately 是副词。词性变了，但被衡量或运用的仍是同一份“用心”。"}],"abstract":[{"en":"Accuracy is not 'approximately right'; it means every relevant detail has been checked against a standard.","cn":"accuracy 不是“差不多对”，而是每一个相关细节都对照过标准。"},{"en":"The care starts as a human attitude and ends as a property of a number, a statement, a copy, or a shot. That is the shift from 'careful' to 'exact'.","cn":"这份“用心”从人的态度开始，最后变成数字、陈述、复制品或射击的属性。这就是从“细心”到“精确”的转移。"},{"en":"Because any object can be measured against a standard, accurate can describe so many things: figures, facts, copies, aims and people.","cn":"因为任何对象都可以对照标准来衡量，所以 accurate 能形容这么多东西：数字、事实、复制品、瞄准和人。"}]},"examples":[{"en":"The map is accurate and shows every street.","cn":"这张地图很准确，标出了每一条街。"},{"en":"Her description of the man was surprisingly accurate.","cn":"她对那个男人的描述准确得令人惊讶。"},{"en":"The clock is accurate to within one second a day.","cn":"这只钟每天的误差在一秒以内。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿Q rat”——阿Q连老鼠都数得清，数字当然准确 → accurate 精确的","word":"accurate"},"root":"源自拉丁语 accuratus“用心准备的”，由 ad-“朝向”+ curare“照料”构成，而 curare 出自 cura“关心”，核心是“照看到每个细节，所以不出偏差”。","sensesIntro":{"en":"Nine senses of accurate, all measuring the same thing: how closely a result matches its standard. The standard may be a number, a fact, an original, a target, or a good habit of work.","cn":"accurate 的九个义项都在衡量同一件事：结果与标准的贴合程度。这个标准可以是数字、事实、原物、目标，也可以是一种良好的工作习惯。"},"semanticMap":{"core":{"en":"CORE IMAGE: care applied to every detail until the result lines up with the standard.","cn":"核心意象：把用心落到每个细节上，直到结果与标准对齐。"},"chain":["CARE","ATTEND TO DETAIL","EXACT","TRUE TO FACT","ON TARGET","ACCURACY"],"branches":[{"senses":"S1 · S6","en":"MEASURING: a figure is exact when every digit is checked, and accurate to sets the last unit that is guaranteed.","cn":"测量：每个数字都核对过，数值才精确；accurate to 则划出最后一个受保证的单位。"},{"senses":"S2 · S4","en":"MATCHING A SOURCE: a statement matches the facts, and a copy matches the original, both measured against something outside themselves.","cn":"对照来源：陈述对照事实，复制品对照原物，两者都以自身之外的东西为尺度。"},{"senses":"S3","en":"AIMING: the body adjusts until the line of action meets the target, which is care turned into physical precision.","cn":"瞄准：身体不断调整，直到动作路线与目标相交，这是“用心”变成身体上的精准。"},{"senses":"S5","en":"A HABIT OF CARE: the adjective can describe the person who checks everything, not only the result of the check.","cn":"用心的习惯：这个形容词也能形容那个凡事核对的人，而不只是核对的结果。"},{"senses":"S7 · S8 · S9","en":"THE QUALITY AND ITS FORMS: accuracy names the quality, accurately names the manner, and inaccurate names the gap when care is removed.","cn":"性质及其形式：accuracy 命名性质，accurately 命名方式，inaccurate 则命名拿掉用心后出现的缺口。"}]},"affixes":{"intro":{"en":"Accurate is ad- + cura 'care' + -ate. Its English family uses -acy for the quality, -ly for the manner, -ness for the state, and in- for negation.","cn":"accurate 是 ad- + cura“关心”+ -ate。它的英语词族用 -acy 表性质、-ly 表方式、-ness 表状态，并用 in- 表否定。"},"latinIntro":{"en":"Latin cura 'care' also gives cure, curious, secure and procure. The prefixes se- 'without' and pro- 'for' show how far the same root can travel.","cn":"拉丁语 cura“关心”还给出 cure、curious、secure、procure。前缀 se-“没有”与 pro-“为了”显示了同一词根能走多远。"},"items":[{"word":"accurate","structure":"ad- (to) + cura (care) + -ate (adjective)","meaning":"done with care, therefore exact","meaningCN":"用心的，因而精确的（ad- 表朝向，-ate 构成形容词）","example":"We need accurate figures for the budget.","exampleCN":"我们需要准确的预算数字。"},{"word":"accuracy","structure":"accurate + -acy (quality or state)","meaning":"the quality of being exact","meaningCN":"准确度；精确性（-acy 表性质或状态）","example":"The accuracy of the data is important.","exampleCN":"数据的准确性很重要。"},{"word":"accurately","structure":"accurate + -ly (adverb of manner)","meaning":"in an exact or correct way","meaningCN":"准确地；精确地（-ly 构成方式副词）","example":"She accurately described the suspect.","exampleCN":"她准确地描述了嫌疑人。"},{"word":"inaccurate","structure":"in- (not) + accurate","meaning":"not exact or not correct","meaningCN":"不准确的；有错误的（in- 表否定）","example":"The first report was inaccurate.","exampleCN":"最初的报告不准确。"},{"word":"inaccuracy","structure":"in- (not) + accuracy","meaning":"a mistake or lack of exactness","meaningCN":"不准确；错误（in- 加 accuracy）","example":"The article contained several inaccuracies.","exampleCN":"那篇文章有几处不准确的地方。"},{"word":"accurateness","structure":"accurate + -ness (state)","meaning":"the state of being exact","meaningCN":"精确性；准确（-ness 表状态）","example":"The accurateness of the translation surprised us.","exampleCN":"译文的准确程度让我们吃惊。"},{"word":"curious","structure":"cur- (care) + -ious (full of)","meaning":"eager to know or learn; strange","meaningCN":"好奇的；奇怪的（同一词根 cura“关心”）","example":"The child was curious about everything.","exampleCN":"那个孩子对一切都很好奇。"},{"word":"secure","structure":"se- (without) + cura (care, worry)","meaning":"safe and free from worry","meaningCN":"安全的；无忧的（se-“没有”+ cura“忧虑”）","example":"Keep your passport in a secure place.","exampleCN":"把护照放在安全的地方。"},{"word":"cure","structure":"cura (care) + -e","meaning":"to care for a sick person; to make healthy again","meaningCN":"治愈；照料病人（源自 cura“关心”）","example":"The doctors cured him of the infection.","exampleCN":"医生治好了他的感染。"}],"latinEntries":[{"word":"cure","structure":"cura (care) + -e","meaning":"care for a patient; restoration to health","meaningCN":"照料病人；治愈"},{"word":"curious","structure":"cur- + -ious","meaning":"full of care or inquiry; eager to know","meaningCN":"关切的；好奇的"},{"word":"secure","structure":"se- (without) + cura (care, worry)","meaning":"free from care or danger","meaningCN":"无忧的；安全的"},{"word":"curator","structure":"curare (to care for) + -or","meaning":"one who takes care of a collection","meaningCN":"管理者；策展人"}]}},{"word":"achieve","ipa_uk":"/əˈtʃiːv/","ipa_us":"/əˈtʃiːv/","definition_zh":"实现；达到；取得（成就）","definition_en":"to succeed in reaching a goal or producing a result through effort","core_image":"把一件事推到顶端、做到头","scene":"马拉松终点线前，计时牌显示着四小时的刻度。 She crossed the timing mat at the finish line and achieved the four-hour goal she had set for herself.","sceneCN":"这里 achieve 是「达到、实现」（第 1 个义项：通过努力达成目标）；句意：她冲过终点线的计时毯，实现了自己定下的四小时目标。","pos":[{"tag":"vt.","zh":"实现；达到；取得；完成"}],"collocations":[{"phrase":"achieve a goal","zh":"实现目标"},{"phrase":"achieve success","zh":"取得成功"},{"phrase":"achieve a balance","zh":"取得平衡"},{"phrase":"achieve recognition","zh":"获得认可"},{"phrase":"achieve a result","zh":"取得结果"}],"forms":[{"label":"三单（he/she/it）","form":"achieves"},{"label":"过去式（已经发生）","form":"achieved"},{"label":"过去分词（完成／被动）","form":"achieved"},{"label":"现在分词（进行体）","form":"achieving"}],"derivatives":[{"word":"achievement","pos":"n.","zh":"成就；成绩；达成"},{"word":"achievable","pos":"adj.","zh":"可实现的；可达到的"},{"word":"achiever","pos":"n.","zh":"取得成就的人；实干者"},{"word":"underachieve","pos":"v.","zh":"表现不佳；未发挥应有水平"},{"word":"overachieve","pos":"v.","zh":"超额完成；表现超出预期"},{"word":"underachiever","pos":"n.","zh":"未能发挥潜力的人"}],"senses":[{"no":"01","title":"Reach a goal through effort","titleCN":"达成目标：努力走到终点","definition":"to succeed in reaching a goal, especially after effort","definitionCN":"（经过努力）成功达到某个目标","example":"She achieved her goal of running a marathon.","exampleCN":"她实现了跑完马拉松的目标。","why":"The Old French phrase behind achieve is a chief, literally 'to a head'. Effort is pictured as pushing a task all the way to its head or top; arriving there is reaching the goal.","whyCN":"achieve 背后的古法语短语 a chief 字面是“到头”。努力被想象成把一件事一直推到它的“头部”或顶端，推到那里就是达成了目标。"},{"no":"02","title":"Turn a plan into reality","titleCN":"把计划变成现实","definition":"to make a plan, idea, or intention actually happen","definitionCN":"使计划、想法或意图真正实现","example":"The team achieved the design they had sketched in January.","exampleCN":"团队把一月勾勒的设计真正做了出来。","why":"A plan exists only in the mind until it is carried to its head, that is, through to the end. Achievement is the completed edge of an intention.","whyCN":"计划在做成之前只存在于脑中；把它“推到头部”就是一路推到终点。achieve 指的就是意图完成之后的那条边。"},{"no":"03","title":"Earn a score or a result","titleCN":"取得（分数、成绩、结果）","definition":"to obtain a particular score, grade, or measured result","definitionCN":"获得某个分数、等级或可衡量的结果","example":"He achieved a score of 720 on the test.","exampleCN":"他在考试中取得了 720 分。","why":"Once reaching the top is the core image, any measured outcome can be the top you reach: a score is simply a height on a scale.","whyCN":"既然核心意象是“推到顶端”，任何被测量的结果都可以是你够到的那个高度：分数不过是刻度尺上的一格。"},{"no":"04","title":"Win success, fame, or status","titleCN":"获得成功、名声或地位","definition":"to become successful or to gain fame, status, or public recognition","definitionCN":"获得成功，或赢得名声、地位与公众认可","example":"The young pianist achieved international fame in her twenties.","exampleCN":"这位年轻的钢琴家在二十多岁时赢得了国际声誉。","why":"Public success is the visible summit. The same upward motion now measures reputation rather than the completion of a task.","whyCN":"公众层面的成功是看得见的山顶。同一个“向上走”的动作，这里衡量的不再是把事做完，而是声誉。"},{"no":"05","title":"Reach an agreement or peace","titleCN":"达成（协议、和平、妥协）","definition":"to reach or bring about an agreement, peace, or compromise","definitionCN":"达成或促成协议、和平或妥协","example":"The two sides achieved a ceasefire after weeks of talks.","exampleCN":"经过数周谈判，双方达成了停火。","why":"Negotiation is a road with a head at its end; when both sides arrive there, the agreement is achieved. The object shifts from a private goal to a shared one.","whyCN":"谈判是一条有终点的路，尽头就是那个“头”；双方都走到那里，协议便达成了。宾语从个人目标变成了共同目标。"},{"no":"06","title":"Produce an effect or a change","titleCN":"产生（效果、变化）","definition":"to produce a change, effect, or improvement in something","definitionCN":"在某事物上产生变化、效果或改善","example":"The new policy achieved a sharp drop in waiting times.","exampleCN":"新政策使等候时间大幅缩短。","why":"The head can also be a result that flows out of an action: what an action brings to a head is its effect.","whyCN":"“头”也可以是一个行动所引出的结果：行动推到尽头所结出的东西，就是它的效果。"},{"no":"07","title":"Attain a standard or a level","titleCN":"达到（标准、水平、年龄）","definition":"to reach a particular standard, level, or stage","definitionCN":"达到某个标准、水平或阶段","example":"The soil achieved the required moisture level after the rain.","exampleCN":"雨后土壤达到了所需的湿度水平。","why":"A standard is a marked height on a scale; achieving it means bringing the marker up to that line.","whyCN":"标准是刻度上标出的一道高度；达到它就是把指针推到那条线。"},{"no":"08","title":"Fulfil a dream or one's potential","titleCN":"实现梦想、发挥潜力","definition":"to realize a dream, an ambition, or one's full potential","definitionCN":"实现梦想、抱负，或充分发挥自身潜力","example":"She moved to Paris to achieve her dream of becoming a chef.","exampleCN":"她搬到巴黎，去实现当厨师的梦想。","why":"Potential is what lies folded inside a person; achieving it brings that inner thing out to its head, where it can finally be seen.","whyCN":"潜力是折在一个人内部的东西；实现潜力，就是把它推到“头部”、推到能被看见的地方。"},{"no":"09","title":"Historical: bring something to an end","titleCN":"古义：结束、终成","definition":"in older use, to finish something or bring it to an end","definitionCN":"在较早的用法中，表示结束某事、使其终成","example":"The old chronicle says the knight achieved his journey at sunset.","exampleCN":"那部旧编年史说，骑士在日落时结束了旅程。","why":"This is the literal oldest layer: a chief meant 'to a head', and the head is the end of a body or of a journey. Finishing is the parent sense, not a later metaphor.","whyCN":"这是最古老的字面一层：a chief 意为“到头”，而头就是身体或旅程的终点。“结束”是母义，不是后来添加的比喻。"},{"no":"10","title":"Word family: -ment freezes effort into a result","titleCN":"词族：-ment 把努力固化成成果","definition":"the suffix -ment forms achievement, naming the result or the process of achieving","definitionCN":"后缀 -ment 构成 achievement，指达成的结果或实现的过程","example":"Her achievement was the product of ten years of quiet work.","exampleCN":"她的成就来自十年默默的工作。","why":"When the verb is nominalized, the moving act freezes into a thing: achievement is the head that the effort reached, kept as a noun.","whyCN":"动词名词化之后，流动的动作凝固成一个东西：achievement 就是努力所到达的那个“头”，被保存成了名词。"}],"etymology":{"intro":{"en":"Achieve came into English through Old French from the Latin phrase ad caput, 'to a head'. The modern spelling with -ie- is a later English settlement, not part of the French form.","cn":"achieve 经由古法语进入英语，来源是拉丁语短语 ad caput“到头”。现代拼写中的 -ie- 是英语后来定下来的，并不属于法语原形。"},"items":[{"era":"EARLY 14C","en":"English recorded acheven in the early 14c. meaning 'to perform, execute, accomplish'; by the late 14c. it also meant 'gain as a result of effort'.","cn":"英语在 14 世纪初记录 acheven，意为“执行、完成”；到 14 世纪后期又表示“通过努力获得”。"},{"era":"OLD FRENCH (12C)","en":"Old French achever meant 'to finish, come or bring to a head', from the phrase à chef 'at an end, finished'. A Vulgar Latin *accapare from Late Latin ad caput is also proposed.","cn":"古法语 achever 意为“完成、到头”，来自短语 à chef“在末端、结束了”。也有人提出它来自俗拉丁语 *accapare，再上溯到晚期拉丁语 ad caput。"},{"era":"LATIN","en":"The French phrase rests on Latin ad 'to' plus caput 'head', literally 'to come to a head'. The source is the phrase, not a single Latin verb.","cn":"这一法语短语建立在拉丁语 ad“向”加 caput“头”上，字面是“来到头／末端”。来源是一个短语，而不是某个单一拉丁动词。"},{"era":"MIDDLE–EARLY MODERN ENGLISH","en":"Middle English spellings included acheve and atchieve. The modern form achieve settled in the 16c.; the reason for the final -ie- is a matter of spelling history rather than a separate root.","cn":"中古英语拼写包括 acheve 与 atchieve。现代形式 achieve 在 16 世纪固定；词尾 -ie- 属于拼写史问题，并非另一个词根。"},{"era":"LATE 15C–16C","en":"Achievement is recorded in the late 15c. as 'act of completing'; the sense 'thing achieved' follows in the 1590s.","cn":"achievement 在 15 世纪后期记录为“完成的行为”；“所取得的成果”一义于 16 世纪 90 年代出现。"},{"era":"PROTO-INDO-EUROPEAN","en":"Caput goes back to the reconstructed root *kaput- 'head', which also lies behind German Haupt. The root is reconstructed from comparing related languages, not attested in writing.","cn":"caput 可追溯到重构词根 *kaput-“头”，德语 Haupt 也出自它。该词根由比较亲属语言重构，并无书面记录。"}]},"similar":{"note":{"en":"Look-alike words are grouped apart from true near-synonyms, so spelling and meaning are not mixed up.","cn":"拼写相近词与真正的近义词分开成组，避免把词形和词义混在一起。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"archive","ipa":"/ˈɑːkaɪv/","tag":"spelling neighbour","definition":"a collection of historical records, or to store records. It begins with a- and ends in -ive, but has no ch.","definitionCN":"档案；档案馆；把资料存档。它同样以 a- 开头、-ive 结尾，但中间没有 ch。"},{"word":"arrive","ipa":"/əˈraɪv/","tag":"same ending and stress","definition":"to reach a place at the end of a journey. It shares the -ive ending and the idea of reaching, but has no ch.","definitionCN":"到达；抵达。它同样以 -ive 结尾，也有“到达”的意思，但拼写中没有 ch。"},{"word":"aggrieve","ipa":"/əˈɡriːv/","tag":"same stress pattern","definition":"to make someone feel distressed or wronged. It looks close in shape but means to hurt, not to accomplish.","definitionCN":"使委屈；使苦恼。词形看上去接近，但意思是使人受伤害，而不是完成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"accomplish","ipa":"/əˈkʌmplɪʃ/","tag":"complete a task","definition":"to finish a task successfully. It stresses carrying something through to the end rather than reaching a measured goal.","definitionCN":"完成；做成。它强调把一件事做到底，而不强调达到某个可衡量的目标。"},{"word":"attain","ipa":"/əˈteɪn/","tag":"reach a high level","definition":"to reach a high level, standard, or age after effort. It is more formal than achieve and often points to a distant height.","definitionCN":"达到；获得（较高水平、标准或年龄）。它比 achieve 正式，常指一个较远的高度。"},{"word":"reach","ipa":"/riːtʃ/","tag":"arrive at","definition":"to arrive at a goal, level, or agreement. It is the plainest of the group and focuses on arrival, not on the effort spent.","definitionCN":"达到；抵达。它是这组里最朴素的词，只强调到达，不强调付出的努力。"},{"word":"realize","ipa":"/ˈriːəlaɪz/","tag":"make real","definition":"to make a plan or hope real. It stresses the change from idea to fact, where achieve stresses the successful endpoint.","definitionCN":"实现（计划、希望）。它强调从想法变成事实，而 achieve 强调成功到达的终点。"},{"word":"fulfil","ipa":"/fʊlˈfɪl/","tag":"satisfy a promise or need","definition":"to carry out a promise, duty, or need completely. It often implies meeting an expectation rather than winning a result.","definitionCN":"履行；满足；实现。它常指满足某项期望或职责，而不是赢得某个结果。"},{"word":"earn","ipa":"/ɜːn/","tag":"gain by merit","definition":"to gain something because of effort or merit. It highlights that the result was deserved, not merely reached.","definitionCN":"赢得；挣得。它强调成果是靠努力和功劳换来的，而不只是“到达”。"}]}]},"mnemonics":{"normalIntro":{"en":"Only real word parts and real relatives: the 'to a head' phrase, -ment, -able, -er, and the under-/over- branches.","cn":"只使用真实构词成分与真实同族词：“到头”短语、-ment、-able、-er，以及 under-/over- 分支。"},"normal":[{"en":"achieve traces to a chief 'to a head': push the task until it reaches its head, and you have achieved it.","cn":"achieve 可追溯到 a chief“到头”：把任务一直推到它的“头”，你就把它做成了。"},{"en":"achievement = achieve + -ment: the act is packed into a result you can point at.","cn":"achievement = achieve + -ment：动作被装进一个可以指出来的成果。"},{"en":"achievable = achieve + -able: something that can be brought to its head.","cn":"achievable = achieve + -able：能被推到“头”的事，就是可实现的。"},{"en":"underachieve and overachieve use under- and over- to say the reach fell short of, or went beyond, the expected line.","cn":"underachieve 和 overachieve 用 under-、over- 表示伸手没够到、或越过了预期的线。"},{"en":"The same chief 'head' is hidden in chief, chef and capital, all words about a head or top position.","cn":"同一个 chief“头”还藏在 chief、chef、capital 里，这些词都与“头”或最高位置有关。"}],"abstract":[{"en":"Think of achievement as a line with a head at one end: effort travels along the line until it touches that head.","cn":"把 achievement 想成一条一端有“头”的线：努力沿着线走，直到碰到那个头。"},{"en":"The line can be a goal, a plan, a score, a reputation, an agreement, or a standard; the geometry stays the same.","cn":"这条线可以是目标、计划、分数、声誉、协议或标准；几何形状始终不变。"},{"en":"When you turn the verb into achievement, the travelling line becomes a fixed point you can stand on.","cn":"把动词变成 achievement 之后，那条行走的线就变成一个可以站上去的固定点。"}]},"examples":[{"en":"The students achieved better results than anyone expected.","cn":"学生们取得了比任何人预想都好的成绩。"},{"en":"It took years of patient work to achieve the restoration.","cn":"完成这次修复花了好几年耐心的功夫。"},{"en":"Both countries hope to achieve a lasting peace.","cn":"两国都希望达成持久和平。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿奇夫”——阿奇把旗子插到山顶，事情做到头 → achieve 实现、达到","word":"achieve"},"root":"源自拉丁语短语 ad caput“到头”，经古法语 achever“结束、到头”进入英语；核心是“把事推到顶端、做到头”。","sensesIntro":{"en":"Ten senses of achieve. Each follows one line: effort travels toward a head, and whatever is reached at that head becomes the achievement.","cn":"achieve 的十个义项都沿着同一条线：努力朝“头”前进，而在那个“头”上够到的东西，就是所实现的成就。"},"semanticMap":{"core":{"en":"CORE IMAGE: effort pushes a task to its head, and the head is reached.","cn":"核心意象：努力把一件事推到它的“头”，并最终到达那里。"},"chain":["HEAD","TO A HEAD","FINISH","ATTAIN","EARN","REALIZE"],"branches":[{"senses":"S1 · S2","en":"PRIVATE COMPLETION: a goal or a plan is carried all the way to its end.","cn":"私人层面的完成：目标或计划被一路推到终点。"},{"senses":"S3 · S4","en":"MEASURED HEIGHT: a score or a reputation is a summit on a public scale.","cn":"可测量的高度：分数或声誉是公开刻度上的一个山顶。"},{"senses":"S5 · S6","en":"SHARED OUTCOME: two sides reach one head in an agreement, and an action brings an effect to its head.","cn":"共同结果：双方在协议里走到同一个“头”，而行动则把效果推到它的“头”。"},{"senses":"S7 · S8","en":"INNER STANDARD: a line on a scale, or a potential folded inside a person, is brought up to view.","cn":"内在标准：刻度上的一条线，或折在人内部的潜力，被推到可见处。"},{"senses":"S9 · S10","en":"HISTORICAL AND GRAMMATICAL: the oldest sense is simply 'finish'; -ment turns the moving act into a fixed result.","cn":"历史与语法层：最古老的义项就是“结束”；-ment 把流动的动作变成固定的成果。"}]},"affixes":{"intro":{"en":"Achieve takes a small but real English family: -ment, -able, -er, and the prefixes under- and over-.","cn":"achieve 拥有一个不大但真实的英语词族：-ment、-able、-er，以及前缀 under- 和 over-。"},"latinIntro":{"en":"The Latin element behind the word is caput 'head', seen in the phrase ad caput. Words such as capital and capitulum belong to that Latin head-family, not to an English affix of achieve.","cn":"这个词背后的拉丁成分是 caput“头”，见于短语 ad caput。capital、capitulum 等词属于这个拉丁“头”词族，而不是 achieve 的英语词缀派生。"},"items":[{"word":"achievement","structure":"achieve + -ment","meaning":"the result or process of achieving something","meaningCN":"成就；达成；实现的过程（-ment 把动作变成名词）","example":"Winning the prize was her greatest achievement.","exampleCN":"赢得这个奖项是她最大的成就。"},{"word":"achievable","structure":"achieve + -able","meaning":"possible to achieve","meaningCN":"可实现的；可达到的（-able 表示“可以……的”）","example":"The target is ambitious but achievable.","exampleCN":"这个目标雄心勃勃，但可以实现。"},{"word":"achiever","structure":"achieve + -er","meaning":"a person who achieves a lot","meaningCN":"取得成就的人；实干者（-er 表示做事的人）","example":"She is a quiet achiever who never seeks attention.","exampleCN":"她是个不爱声张的实干者，从不追求关注。"},{"word":"underachieve","structure":"under- (below) + achieve","meaning":"to do worse than expected or than one's ability suggests","meaningCN":"表现不佳；未发挥应有水平（under- 表示“低于”）","example":"He underachieved at school despite his intelligence.","exampleCN":"他尽管聪明，在学校却表现不佳。"},{"word":"overachieve","structure":"over- (beyond) + achieve","meaning":"to do better than expected","meaningCN":"超额完成；表现超出预期（over- 表示“超过”）","example":"The small team overachieved and won the contract.","exampleCN":"这个小团队超额完成任务，赢下了合同。"},{"word":"unachievable","structure":"un- (not) + achievable","meaning":"impossible to achieve","meaningCN":"无法实现的（un- 表示否定）","example":"Without funding, the plan is unachievable.","exampleCN":"没有资金，这个计划无法实现。"},{"word":"achieved","structure":"achieve + -ed","meaning":"reached or gained, used as an adjective","meaningCN":"已达到的；取得的（-ed 构成形容词，如 achieved status 获得性地位）","example":"In sociology, achieved status contrasts with status you are born with.","exampleCN":"在社会学里，achieved status（获得性地位）与与生俱来的地位相对。"},{"word":"high-achieving","structure":"high + achieving (achieve + -ing)","meaning":"regularly achieving at a high level","meaningCN":"成绩优异的；表现突出的（high + achieve 的现在分词）","example":"The school attracts high-achieving students.","exampleCN":"这所学校吸引成绩优异的学生。"},{"word":"underachievement","structure":"under- (below) + achievement","meaning":"performance that is below the level expected","meaningCN":"成绩低于预期；未充分发挥（under- 表示“低于”）","example":"The school is trying to reduce underachievement among boys.","exampleCN":"这所学校正努力减少男生中成绩低于预期的现象。"},{"word":"overachievement","structure":"over- (beyond) + achievement","meaning":"performance that goes beyond what was expected","meaningCN":"超出预期的表现（over- 表示“超过”）","example":"Her overachievement surprised no one who knew her.","exampleCN":"她超出预期的表现并没有让了解她的人感到意外。"}],"latinEntries":[{"word":"caput","structure":"Latin noun, genitive capitis","meaning":"head; top; chief part","meaningCN":"头；顶端；主要部分"},{"word":"ad caput","structure":"ad (to) + caput (head)","meaning":"to the head; to a head","meaningCN":"到头；向顶端（achieve 的直接语义来源）"},{"word":"capitulum","structure":"caput (head) + -culum (diminutive)","meaning":"a little head; a chapter heading","meaningCN":"小头；章节的标题（caput 的指小形式）"}]}},{"word":"acknowledge","ipa_uk":"/əkˈnɒlɪdʒ/","ipa_us":"/əkˈnɑːlɪdʒ/","definition_zh":"承认；认可；告知收到；致谢","definition_en":"to admit that something is true, or to show that you have noticed, received, or value it","core_image":"心里先“知道”，再点头把它摆到明面上","scene":"项目会上，投影上的图表被实习生指出了问题。 At the project meeting the manager acknowledged the data error the intern had pointed out and corrected the slide.","sceneCN":"这里 acknowledge 是「承认（事实、错误）」（第 1 个义项：承认某事为真）；句意：项目会上，经理承认了实习生指出的数据错误，并改正了幻灯片。","pos":[{"tag":"vt.","zh":"承认；认可；确认收到；答谢"}],"collocations":[{"phrase":"acknowledge a mistake","zh":"承认错误"},{"phrase":"acknowledge receipt of","zh":"告知已收到（某物）"},{"phrase":"be widely acknowledged","zh":"被广泛认可"},{"phrase":"acknowledge the importance of","zh":"承认……的重要性"},{"phrase":"acknowledge someone's contribution","zh":"认可某人的贡献"}],"forms":[{"label":"三单（he/she/it）","form":"acknowledges"},{"label":"过去式（已经发生）","form":"acknowledged"},{"label":"过去分词（完成／被动）","form":"acknowledged"},{"label":"现在分词（进行体）","form":"acknowledging"}],"derivatives":[{"word":"acknowledgement","pos":"n.","zh":"承认；认可；致谢；收到确认（英式拼写）"},{"word":"acknowledgment","pos":"n.","zh":"承认；认可；致谢；收到确认（美式拼写）"},{"word":"unacknowledged","pos":"adj.","zh":"未被承认的；未获回应的"},{"word":"acknowledged","pos":"adj.","zh":"公认的；得到承认的"},{"word":"acknowledger","pos":"n.","zh":"承认者；确认者（罕用）"}],"senses":[{"no":"01","title":"Admit a fact or a mistake","titleCN":"承认事实或错误","definition":"to admit that something is true, especially something you would rather not admit","definitionCN":"承认某事为真，尤指自己不太愿意承认的事","example":"She acknowledged that the delay was her fault.","exampleCN":"她承认延误是她的责任。","why":"The Old English ancestor meant 'to know'. Acknowledging is knowing something and then placing that knowledge in public view: the private fact is brought out and admitted.","whyCN":"古英语祖词的意思是“知道”。acknowledge 就是先知道一件事，再把这份“知道”摆到公众面前：把私下的事实拿出来承认。"},{"no":"02","title":"Recognize that something exists or matters","titleCN":"承认（某事物的存在或重要性）","definition":"to accept that a problem, fact, or quality exists and is important","definitionCN":"承认某个问题、事实或性质确实存在且重要","example":"The report acknowledges the limits of the data.","exampleCN":"报告承认了这些数据的局限。","why":"Once knowledge is made public, it can be directed at anything: a problem, a limit, a quality. You first notice it, then say that it counts.","whyCN":"“知道”一旦被公开，就可以指向任何对象：问题、局限、性质。你先注意到它，再说明它算数。"},{"no":"03","title":"Recognize someone's merit","titleCN":"认可某人的价值或成就","definition":"to publicly recognize the value of someone's work, skill, or achievement","definitionCN":"公开认可某人的工作、技能或成就的价值","example":"The award acknowledges her work with young readers.","exampleCN":"这个奖项认可了她为年轻读者所做的工作。","why":"The object moves from a fact to a person: you know the person's worth, and you say it out loud. Public recognition is knowledge turned into honour.","whyCN":"宾语从“事实”转到了“人”：你知道这个人的价值，并且把它说出来。公开的认可，就是“知道”变成了荣誉。"},{"no":"04","title":"Accept someone's authority or status","titleCN":"承认某人的权威或身份","definition":"to accept that someone has a particular authority, rank, or identity","definitionCN":"承认某人拥有某种权威、地位或身份","example":"The council acknowledged him as the rightful leader.","exampleCN":"委员会承认他是合法的领导人。","why":"Knowing a fact about a person can become accepting a claim about that person. Here the 'fact' is their rank, and saying it counts is granting legitimacy.","whyCN":"知道某人的一个事实，可以变成接受关于此人的一项主张。这里的“事实”是他的地位，而把它说成算数，就是给予合法性。"},{"no":"05","title":"Confirm that a letter or message arrived","titleCN":"告知已收到（信件、消息）","definition":"to tell someone that you have received their letter, message, or request","definitionCN":"告知对方已收到其信件、消息或请求","example":"Please acknowledge receipt of this email within two days.","exampleCN":"请在两天内告知已收到这封邮件。","why":"The oldest sense 'to know' narrows to 'to know that something has arrived'. A short reply makes that knowledge visible to the sender, so acknowledge comes to mean confirm receipt.","whyCN":"最古老的“知道”缩小为“知道某物已经到了”。一个简短回复让这份“知道”对发件人可见，于是 acknowledge 就表示确认收到。"},{"no":"06","title":"Signal that a message was received","titleCN":"确认（信号、消息已被接收）","definition":"to send a signal showing that a message or command has been received, used of machines and networks","definitionCN":"（机器、网络）发送信号表明消息或指令已被接收","example":"The server acknowledged the request and began processing it.","exampleCN":"服务器确认了请求，并开始处理。","why":"Machines repeat the human act: a received packet is 'known', and a return signal makes that knowing visible. The technology sense is the receipt sense without a person.","whyCN":"机器重复了人的动作：收到数据包就是“知道了”，回一个信号则让这份“知道”可见。技术义就是去掉人的“收到确认”。"},{"no":"07","title":"Credit help or funding","titleCN":"答谢、鸣谢（帮助或资助）","definition":"to publicly thank or credit the people or organizations that helped or funded something","definitionCN":"公开感谢或注明帮助、资助过某事的人或机构","example":"The authors acknowledge the foundation that funded the study.","exampleCN":"作者们鸣谢资助这项研究的基金会。","why":"If you know that someone helped, the honest response is to name that help in public. Acknowledgement becomes the written form of gratitude: knowledge of a debt turned into credit.","whyCN":"如果你知道有人帮过忙，诚实的回应就是把这份帮助公开写出来。acknowledgement 因而成为书面致谢：把“知道欠情”变成“记上一笔功劳”。"},{"no":"08","title":"Nod or greet: show that you noticed someone","titleCN":"点头、示意：表示注意到某人","definition":"to show by a nod, smile, or word that you have noticed someone or their greeting","definitionCN":"用点头、微笑或言语表示已注意到某人或其问候","example":"He acknowledged me with a quick nod across the room.","exampleCN":"他在房间那头快速点了下头，表示看到我了。","why":"The body performs the word: a nod is the smallest public sign that knowledge has registered. No words are needed, only a visible mark of 'I know you are there'.","whyCN":"身体在替这个词做动作：点头是“已经知道”的最小公开信号。不必说话，只要一个可见的标记，表示“我知道你在”。"},{"no":"09","title":"Historical: to know or recognize","titleCN":"古义：知晓、认出","definition":"in older English, to know, perceive, or recognize something","definitionCN":"在早期英语中表示知道、察觉或认出某事物","example":"In old texts, to acknowledge a person often meant simply to know who they were.","exampleCN":"在旧文本里，acknowledge a person 常常只表示知道此人是谁。","why":"This is the root layer: Old English oncnawan was 'to know'. Every later sense is that knowing made social, legal, or mechanical.","whyCN":"这是词根的底层：古英语 oncnawan 就是“知道”。后来所有义项，都是把这份“知道”变成社会性的、法律性的或机械性的表达。"},{"no":"10","title":"Word family: -ment makes the act a formal noun","titleCN":"词族：-ment 把动作变成正式名词","definition":"the suffix -ment forms acknowledgement, naming the act or the statement of acknowledging","definitionCN":"后缀 -ment 构成 acknowledgement，指承认的动作或承认的声明","example":"The book opens with an acknowledgement of everyone who helped.","exampleCN":"这本书以一份致谢名单开篇，感谢所有帮助过的人。","why":"The verb is an event in time; -ment turns that event into an object that can be written, signed, or read. The noun is the public trace left by the act of knowing.","whyCN":"动词是时间中的事件；-ment 把事件变成可以书写、签署、阅读的对象。名词就是“知道”这一动作留下的公开痕迹。"}],"etymology":{"intro":{"en":"Acknowledge is a Germanic word, not a Latin borrowing. Old English oncnawan 'to know, recognize' met Middle English knowlechen 'to admit', and the two forms merged in the late 15c.","cn":"acknowledge 是日耳曼语词，不是拉丁语借词。古英语 oncnawan“知道、认出”与中古英语 knowlechen“承认”相遇，两个形式在 15 世纪后期融合。"},"items":[{"era":"LATE 15C","en":"Acknowledge is recorded in the late 15c. meaning 'admit or show one's knowledge'. It is a blend of Middle English aknow and knowlechen.","cn":"acknowledge 记录于 15 世纪后期，意为“承认或表明自己知道”。它是中古英语 aknow 与 knowlechen 的混合形式。"},{"era":"MIDDLE ENGLISH","en":"Middle English aknow came from Old English oncnawan 'understand, come to recognize'. Knowlechen 'admit, acknowledge' is recorded from c. 1200.","cn":"中古英语 aknow 来自古英语 oncnawan“理解、逐渐认出”。knowlechen“承认、认可”记录于约 1200 年。"},{"era":"OLD ENGLISH","en":"Oncnawan was on- plus cnawan 'to know'. Cnawan goes back to Proto-Germanic *knewan and PIE *gno- 'to know', the same family as know, knowledge and recognize.","cn":"oncnawan 由 on- 加 cnawan“知道”构成。cnawan 可追溯到原始日耳曼语 *knewan 与原始印欧语 *gno-“知道”，与 know、knowledge、recognize 同族。"},{"era":"16C SPELLING","en":"By the 16c. the older verbs knowledge and aknow were obsolete and acknowledge took their place. An unetymological -c- slipped in; the exact reason is source uncertain, though one suggestion is that it preserved the old kn- sound.","cn":"到 16 世纪，较早的动词 knowledge 与 aknow 已废弃，acknowledge 取代了它们。词中多出一个非词源的 -c-；确切原因来源不确定，一种说法是它保留了古时的 kn- 音。"},{"era":"MIDDLE ENGLISH -LEDGE","en":"The second element of knowledge, and hence the ending of acknowledge, is obscure; it may be Scandinavian and cognate with the -lock of wedlock. Its origin is source uncertain.","cn":"knowledge 的第二个成分（也就是 acknowledge 的词尾）来源晦涩，可能来自斯堪的纳维亚语，与 wedlock 的 -lock 同源。其来源不确定。"},{"era":"MODERN ENGLISH","en":"Modern English keeps both spellings of the noun, acknowledgement in British usage and acknowledgment in American. The verb itself means admit, recognize, confirm receipt or thank.","cn":"现代英语保留名词的两种拼写：英式 acknowledgement，美式 acknowledgment。动词本身表示承认、认可、确认收到或致谢。"}]},"similar":{"note":{"en":"The first group shares sound or spelling with acknowledge; the second shares meaning. They are kept separate on purpose.","cn":"第一组与 acknowledge 共享读音或拼写，第二组共享词义；有意分开排列。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"knowledge","ipa":"/ˈnɒlɪdʒ/","tag":"shared -ledge","definition":"the facts or understanding a person has. It shares the know- root and the -ledge ending, but is a noun, not a verb.","definitionCN":"知识；了解。它与 acknowledge 共享 know- 词根和 -ledge 词尾，但它是名词，不是动词。"},{"word":"college","ipa":"/ˈkɒlɪdʒ/","tag":"same ending sound","definition":"a place of higher education. It ends in the same /ɪdʒ/ sound but has no know- element.","definitionCN":"学院；大学。它以同样的 /ɪdʒ/ 音结尾，但里面没有 know- 这个成分。"},{"word":"privilege","ipa":"/ˈprɪvəlɪdʒ/","tag":"same ending sound","definition":"a special right or advantage. The ending sounds like -ledge, but the word is unrelated.","definitionCN":"特权；特殊待遇。词尾听起来像 -ledge，但这个词与 acknowledge 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"admit","ipa":"/ədˈmɪt/","tag":"reluctant truth","definition":"to agree that something is true, often unwillingly. It is the plainest word for sense 1.","definitionCN":"承认（常指不情愿地）。它是义项 1 最朴素的对应词。"},{"word":"recognize","ipa":"/ˈrekəɡnaɪz/","tag":"notice and accept","definition":"to know someone or something because you have seen it before, or to accept its value. It stresses identification.","definitionCN":"认出；承认……的价值。它强调“辨认出来”。"},{"word":"concede","ipa":"/kənˈsiːd/","tag":"yield a point","definition":"to admit that a point is true after first resisting it. It carries the sense of giving way in an argument.","definitionCN":"（争论中）承认、让步。它带有“先抵抗、后让出这一点”的意味。"},{"word":"confess","ipa":"/kənˈfes/","tag":"admit wrongdoing","definition":"to admit that you did something wrong or illegal. It is stronger and more personal than acknowledge.","definitionCN":"坦白；供认。它比 acknowledge 语气更重，也更个人化。"},{"word":"confirm","ipa":"/kənˈfɜːm/","tag":"receipt or truth","definition":"to state that something is true or that a message has arrived. It fits the receipt sense rather than the moral one.","definitionCN":"确认；证实。它对应“收到确认”这一义项，而不是承认过错那一义项。"},{"word":"credit","ipa":"/ˈkredɪt/","tag":"name a helper","definition":"to publicly name someone as the source of work or help. It matches the acknowledgement of funding.","definitionCN":"归功于；注明（某人）的贡献。它对应“鸣谢资助”这一义项。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces only: the Old English know-root, the knowlechen ending, -ment, un-, and the knowledge family.","cn":"只用真实成分：古英语的 know 词根、knowlechen 的词尾、-ment、un-，以及 knowledge 词族。"},"normal":[{"en":"acknowledge = a- + know + -ledge: at bottom it is 'know', dressed for public use.","cn":"acknowledge = a- + know + -ledge：底层就是“知道”，只是穿上了公开场合的外衣。"},{"en":"The Old English a- here is an intensifying or 'on' prefix, so oncnawan is 'to know, to be on knowing'.","cn":"这里的古英语 a- 是加强或“在……上”的前缀，所以 oncnawan 是“知道、处在知道的状态”。"},{"en":"acknowledgement = acknowledge + -ment: the act becomes a signed or printed statement.","cn":"acknowledgement = acknowledge + -ment：动作变成一份可签署、可印出的声明。"},{"en":"unacknowledged = un- + acknowledged: knowledge that was never brought into public view.","cn":"unacknowledged = un- + acknowledged：从未被摆到公众面前的“知道”。"},{"en":"knowledge, knowledgeable and foreknowledge share the same know- core; -ledge is the old noun ending, -able adds 'having'.","cn":"knowledge、knowledgeable、foreknowledge 共享同一个 know- 核心；-ledge 是旧名词词尾，-able 表示“具有”。"}],"abstract":[{"en":"Picture a light inside a head: acknowledging switches that light on so others can see it.","cn":"想象脑袋里有一盏灯：acknowledge 就是把这盏灯打开，让别人也能看见。"},{"en":"The light can illuminate a fact, a person's worth, a letter, a signal, or a helper; the act is always 'make known'.","cn":"这盏灯可以照见一个事实、一个人的价值、一封信、一个信号或一位帮手；动作始终是“让之被知道”。"},{"en":"When the light is formalized in writing, it becomes an acknowledgement — a trace that outlives the moment.","cn":"当这盏灯被写进正式文本，它就成了 acknowledgement——一道比当下活得更久的痕迹。"}]},"examples":[{"en":"He refused to acknowledge that he had lost the argument.","cn":"他拒绝承认自己在争论中输了。"},{"en":"The company acknowledged the complaint and promised a reply.","cn":"公司确认收到了投诉，并承诺回复。"},{"en":"Her early work is now acknowledged as a classic.","cn":"她的早期作品如今被公认为经典。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“额克诺力奇”——额头上亮起“诺力奇”三个字，把知道的点头认下来 → acknowledge 承认","word":"acknowledge"},"root":"源自古英语 oncnawan“知道、察觉”，由 a-（加强／在……上）+ cnawan“知道”构成，与 know 同源；核心是“知道并公开认下”。","sensesIntro":{"en":"Ten senses, one movement: something is known, and then that knowledge is made visible — as an admission, a recognition, a receipt, a greeting, or a thank-you.","cn":"十个义项其实是同一个动作：先知道一件事，再让这份“知道”变得可见——成为承认、认可、收到确认、招呼或致谢。"},"semanticMap":{"core":{"en":"CORE IMAGE: knowledge inside the head is switched on and made public.","cn":"核心意象：脑袋里的“知道”被打开，摆到明面上。"},"chain":["KNOW","NOTICE","NOD","ADMIT","RECEIVE","CREDIT"],"branches":[{"senses":"S1 · S2","en":"MAKE KNOWN: a private fact or a neglected problem is brought into the open and admitted.","cn":"让之被知道：私下的事实或被忽视的问题被摆到明面上并承认。"},{"senses":"S3 · S4","en":"PUBLIC WORTH: recognition moves from a person's merit to that person's rank and legitimacy.","cn":"公开的价值：认可从某人的功劳，延伸到其地位与合法性。"},{"senses":"S5 · S6","en":"RECEIPT: knowing that something arrived becomes a human reply or a machine signal.","cn":"收到确认：知道某物已到达，变成人的回复或机器的信号。"},{"senses":"S7","en":"GRATITUDE: knowledge of help received is turned into public credit.","cn":"感激：知道受过帮助，就把它变成公开的鸣谢。"},{"senses":"S8 · S9 · S10","en":"BODY, ROOT, AND NOUN: a nod is the smallest visible knowing; the oldest sense is bare 'know'; -ment fixes the act in writing.","cn":"身体、词根与名词：点头是最小的可见“知道”；最古义就是光秃秃的“知道”；-ment 把动作固定在文字里。"}]},"affixes":{"intro":{"en":"Acknowledge is a native word, so its affixes are English: -ment, -ed, un-, and compounds with self- and well-. The know- root also supports knowledge and its family.","cn":"acknowledge 是本土词，因此词缀是英语的：-ment、-ed、un-，以及与 self-、well- 构成的复合词。know- 词根还支撑 knowledge 词族。"},"latinIntro":{"en":"There is no Latin ancestor or Latin relative for acknowledge; the word is Germanic. The Latin-based synonyms recognize and admit belong to other families and are not listed here.","cn":"acknowledge 没有拉丁语祖词或拉丁同族词，它是日耳曼语词。拉丁语源的近义词 recognize、admit 属于别的词族，不列在这里。"},"items":[{"word":"acknowledgement","structure":"acknowledge + -ment","meaning":"the act of acknowledging, or a statement that thanks or recognizes someone","meaningCN":"承认；致谢；鸣谢（-ment 构成动作或结果名词，英式拼写）","example":"The paper ends with an acknowledgement of its funders.","exampleCN":"论文末尾有对资助方的鸣谢。"},{"word":"acknowledgment","structure":"acknowledge + -ment (US spelling)","meaning":"the same noun, written without the middle e in American English","meaningCN":"同 acknowledgement，美式拼写省去中间的 e","example":"He signed the acknowledgment of receipt.","exampleCN":"他签了收件确认书。"},{"word":"unacknowledged","structure":"un- (not) + acknowledged","meaning":"not admitted or not responded to","meaningCN":"未被承认的；未获回应的（un- 表否定）","example":"Her letters went unacknowledged for months.","exampleCN":"她的信好几个月都没有收到回应。"},{"word":"acknowledged","structure":"acknowledge + -ed","meaning":"generally recognized, used as an adjective","meaningCN":"公认的；得到承认的（-ed 构成形容词）","example":"He is an acknowledged expert on the region.","exampleCN":"他是该地区公认的专家。"},{"word":"self-acknowledged","structure":"self- + acknowledged","meaning":"admitted by oneself","meaningCN":"自己承认的（self- 表示“自我”）","example":"He is a self-acknowledged workaholic.","exampleCN":"他是个自己都承认的工作狂。"},{"word":"knowledgeable","structure":"knowledge + -able","meaning":"having a lot of knowledge","meaningCN":"知识渊博的；在行的（-able 表示“具有”）","example":"The guide was knowledgeable about local history.","exampleCN":"这位向导对当地历史很在行。"},{"word":"knowledgeably","structure":"knowledgeable + -ly","meaning":"in a way that shows knowledge","meaningCN":"内行地；有见地地（-ly 构成副词）","example":"She spoke knowledgeably about the wine region.","exampleCN":"她内行地谈起了那个葡萄酒产区。"},{"word":"foreknowledge","structure":"fore- (before) + knowledge","meaning":"knowledge of something before it happens","meaningCN":"预先知道；预知（fore- 表示“先、前”）","example":"No one had foreknowledge of the decision.","exampleCN":"没有人事先知道这个决定。"},{"word":"knowledge","structure":"know + -ledge (noun suffix of uncertain origin)","meaning":"facts and understanding gained by learning or experience","meaningCN":"知识；学识（-ledge 为来源不确定的名词词尾）","example":"His knowledge of local history is impressive.","exampleCN":"他对当地历史的了解令人印象深刻。"},{"word":"knowing","structure":"know + -ing (adjective)","meaning":"showing that one is aware of something that is not openly stated","meaningCN":"会意的；心照不宣的（know + -ing 构成形容词）","example":"She gave him a knowing smile.","exampleCN":"她对他露出会意的微笑。"}],"latinEntries":[]}},{"word":"acquire","ipa_uk":"/əˈkwaɪə/","ipa_us":"/əˈkwaɪər/","definition_zh":"获得；取得；习得；收购","definition_en":"to obtain or gain something, especially through effort, purchase, or a gradual process","core_image":"伸手多拿一件，把它收进自己的“拥有圈”","scene":"二手书店里，他在木架上找到那本绝版的植物图鉴。 In the second-hand bookshop he acquired the out-of-print plant guide with the coins he had saved for half a year.","sceneCN":"这里 acquire 是「购得、取得」（第 2 个义项：通过购买或交换得到某物）；句意：在二手书店里，他用攒了半年的零钱购得了那本绝版的植物图鉴。","pos":[{"tag":"vt.","zh":"获得；取得；习得；收购"}],"collocations":[{"phrase":"acquire knowledge","zh":"获取知识"},{"phrase":"acquire a taste for","zh":"逐渐喜欢上"},{"phrase":"acquire a company","zh":"收购一家公司"},{"phrase":"acquire skills","zh":"习得技能"},{"phrase":"acquire a reputation","zh":"获得某种名声"}],"forms":[{"label":"三单（he/she/it）","form":"acquires"},{"label":"过去式（已经发生）","form":"acquired"},{"label":"过去分词（完成／被动）","form":"acquired"},{"label":"现在分词（进行体）","form":"acquiring"}],"derivatives":[{"word":"acquisition","pos":"n.","zh":"获得；收购；习得"},{"word":"acquisitive","pos":"adj.","zh":"贪得的；渴望获得的"},{"word":"acquirer","pos":"n.","zh":"获得者；收购方"},{"word":"acquiree","pos":"n.","zh":"被收购的公司（商业术语）"},{"word":"acquired","pos":"adj.","zh":"后天获得的；已取得的"},{"word":"reacquire","pos":"v.","zh":"重新获得；再次购得"}],"senses":[{"no":"01","title":"Gain knowledge or understanding","titleCN":"获得知识、获得理解","definition":"to gain knowledge or understanding, usually gradually","definitionCN":"获得知识或理解，通常是一个逐渐的过程","example":"Children acquire basic maths ideas long before school.","exampleCN":"孩子们在上学之前很久就已经获得了基本的数学概念。","why":"The Latin verb acquirere is ad- 'to' plus quaerere 'seek': to seek toward something until it becomes yours. Knowledge is one of the things you can seek toward and keep.","whyCN":"拉丁动词 acquirere 是 ad-“向”加 quaerere“寻求”：朝着某物寻求，直到它归你所有。知识就是可以这样“寻求到手”并留住的东西之一。"},{"no":"02","title":"Obtain a thing by buying or getting it","titleCN":"取得、购得某物","definition":"to obtain a particular object, especially by buying it or arranging to get it","definitionCN":"获得某件具体物品，尤指通过购买或安排取得","example":"She acquired the painting at an auction in London.","exampleCN":"她在伦敦的一场拍卖会上购得了这幅画。","why":"When the thing sought is a physical object, 'seek toward' ends in possession: money or an arrangement moves the object into your own circle.","whyCN":"当寻求的对象是一件实物时，“朝它寻求”的终点就是占有：用钱或安排把物品移进你自己的圈里。"},{"no":"03","title":"Take over a company or an asset","titleCN":"收购公司或资产","definition":"to buy a company or a large asset and take control of it","definitionCN":"买下并控制一家公司或一项大型资产","example":"The group acquired three rival studios in one year.","exampleCN":"该集团一年内收购了三家竞争对手的工作室。","why":"Corporate acquisition scales up the same geometry: a whole company is 'sought toward' and then brought inside the buyer's boundary.","whyCN":"企业收购是同一几何形状的放大：一整家公司被“寻求到手”，然后被移进买方的边界之内。"},{"no":"04","title":"Gain a right, a status, or citizenship","titleCN":"取得权利、身份或国籍","definition":"to come to have a legal right, status, or nationality","definitionCN":"取得某项合法权利、身份或国籍","example":"He acquired citizenship after ten years in the country.","exampleCN":"他在这个国家住满十年后取得了国籍。","why":"Rights and status are abstract possessions. The seeker moves toward a legal state, and when the state is granted, it is held like property.","whyCN":"权利和身份是抽象的占有物。寻求者朝某种法律状态前进，一旦获准，它就象财产一样被持有。"},{"no":"05","title":"Pick up a language or a skill","titleCN":"习得语言或技能","definition":"to learn a language or skill through use and exposure rather than formal teaching","definitionCN":"通过使用和接触而非正式教学学会一门语言或技能","example":"She acquired fluent Spanish during two years in Madrid.","exampleCN":"她在马德里待了两年，习得了流利的西班牙语。","why":"This is the knowledge sense made concrete: repeated contact gradually adds pieces to the learner, until the skill sits inside like something owned.","whyCN":"这是“知识”义项的具体化：反复接触把一块块内容逐渐加到学习者身上，直到这项技能像自有物一样留在里面。"},{"no":"06","title":"Develop a habit or a taste","titleCN":"养成习惯、喜欢上某物","definition":"to develop a habit, a preference, or a taste over time","definitionCN":"随着时间养成某种习惯、偏好或口味","example":"He acquired a taste for strong coffee while working night shifts.","exampleCN":"上夜班期间，他渐渐喜欢上了浓咖啡。","why":"A taste is not bought in one moment; it is added to you in small installments. The 'get in addition' idea shows clearly here: each exposure adds a little more liking.","whyCN":"口味不是一次买来的，而是一小份一小份加到身上的。“额外得到”这一层在这里最清楚：每一次接触都多加一点喜欢。"},{"no":"07","title":"Gather data or information","titleCN":"获取数据、信息","definition":"to obtain data, information, or evidence, often systematically","definitionCN":"获取数据、信息或证据，通常是有系统地获取","example":"The satellite acquires images every ninety minutes.","exampleCN":"这颗卫星每九十分钟获取一次图像。","why":"Information is invisible property: a sensor or a researcher reaches toward it and stores it. Acquiring data is possession in the form of records.","whyCN":"信息是无形的财产：传感器或研究者朝它伸过去，然后把它存起来。获取数据就是以记录形式完成的占有。"},{"no":"08","title":"Build a collection or a fortune","titleCN":"积累收藏、积聚财富","definition":"to collect or accumulate things over time","definitionCN":"随着时间收集或积累物品","example":"Over forty years he acquired a remarkable collection of maps.","exampleCN":"四十多年间，他积累了一批了不起的地图收藏。","why":"The Latin source also meant 'get in addition, accumulate'. One acquisition follows another, and the total grows beyond any single act of getting.","whyCN":"这个拉丁词源本来也有“额外得到、积累”的意思。一次获得接着一次获得，总量就超出任何单次取得的动作。"},{"no":"09","title":"Come to have a quality or a reputation","titleCN":"逐渐具有某种特性或名声","definition":"to come to be known for a quality, especially a reputation","definitionCN":"逐渐以某种特性为人所知，尤指获得某种名声","example":"The bakery acquired a reputation for unusually sour bread.","exampleCN":"这家面包店渐渐以特别酸的面包出了名。","why":"A reputation is something others attach to you. You do not grab it; it accrues, and at some point it is said that you have acquired it.","whyCN":"名声是别人加到你身上的东西。你不是去抓它，它是慢慢累积的；到了某个时候，人们就说你已经“获得”了它。"},{"no":"10","title":"Historical: to get in addition","titleCN":"词源义：额外得到、增添","definition":"in the Latin source, to get or gain something in addition to what one already has","definitionCN":"在拉丁语源中，指在已有之物之外额外获得或增添","example":"The Latin acquirere literally suggested adding something to what was already held.","exampleCN":"拉丁语 acquirere 字面上暗示在已持有之物上再添一样东西。","why":"This is the oldest layer and the key to the whole family: ad- 'to' plus quaerere 'seek' pictures a seeker moving toward a thing and adding it to his store. Every modern sense is that addition, applied to knowledge, objects, rights, habits, data, or fame.","whyCN":"这是最古老的一层，也是整个词族的钥匙：ad-“向”加 quaerere“寻求”，画出一个寻求者朝某物移动、并把它添进自己仓库的画面。所有现代义项都是这种“添入”，只是对象换成了知识、物品、权利、习惯、数据或名声。"}],"etymology":{"intro":{"en":"Acquire came through Old French from Latin acquirere, a compound of ad- 'to' and quaerere 'to seek'. The same Latin verb family gives require, inquire and question.","cn":"acquire 经由古法语来自拉丁语 acquirere，由 ad-“向”和 quaerere“寻求”复合而成。同一个拉丁词族还给出 require、inquire 和 question。"},"items":[{"era":"MODERN ENGLISH","en":"The verb and the noun acquisition are standard modern forms. Acquisition covers both learning (language acquisition) and business takeovers.","cn":"动词及名词 acquisition 是现代标准形式。acquisition 既指学习层面的“习得”（language acquisition），也指商业上的“收购”。"},{"era":"MIDDLE ENGLISH (15C.)","en":"Recorded in the mid-15c. meaning 'to get, obtain'. It was borrowed through Old French rather than taken directly from Latin.","cn":"15 世纪中期有记录，意为“得到、获得”。它是经由古法语借入的，而不是直接从拉丁语取来。"},{"era":"OLD FRENCH","en":"Old French aquerre meant 'to acquire, gain', and supplied the form that English took over.","cn":"古法语 aquerre 意为“获得、取得”，提供了英语所接手的形式。"},{"era":"LATIN","en":"acquirere 'to get in addition, accumulate' is ad- 'to' + quaerere 'to seek, seek to obtain'. Its past participle acquisitus is the stem behind acquisition and acquisitive.","cn":"acquirere“额外得到、积累”是 ad-“向”+ quaerere“寻求、谋求”。它的过去分词 acquisitus 就是 acquisition 与 acquisitive 的词干。"},{"era":"PROTO-INDO-EUROPEAN","en":"The deeper origin of quaerere is uncertain: sources agree on the meaning 'seek' but do not settle on a single earlier root. source uncertain. The practical base for English is the Latin verb, not a reconstructed form.","cn":"quaerere 更早的来源不确定：各种资料都同意其意为“寻求”，但未能确定唯一的更早词根。来源不确定。对英语而言，可靠的起点是拉丁动词本身，而不是某个构拟形式。"}]},"similar":{"note":{"en":"The look-alike group shares the -quire or acqu- shape; the near-meaning group shares the idea of getting. Form and sense are kept apart.","cn":"形近组共享 -quire 或 acqu- 的外形；近义组共享“得到”的意思。词形与词义分开处理。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"require","ipa":"/rɪˈkwaɪə/","tag":"same -quire","definition":"to need something, or to officially demand it. It shares the Latin quaerere base but has no a-.","definitionCN":"需要；要求。它共享拉丁语 quaerere 词根，但没有 a- 前缀。"},{"word":"inquire","ipa":"/ɪnˈkwaɪə/","tag":"same -quire","definition":"to ask for information. It is in- 'into' + quaerere 'seek', literally 'seek into'.","definitionCN":"询问；打听。它是 in-“进入”+ quaerere“寻求”，字面就是“寻求进去”。"},{"word":"acquit","ipa":"/əˈkwɪt/","tag":"same acqu- start","definition":"to declare someone not guilty. It begins like acquire but comes from a different Latin verb.","definitionCN":"宣判无罪。它开头和 acquire 很像，但来自另一个拉丁动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"obtain","ipa":"/əbˈteɪn/","tag":"general get","definition":"to get something, especially by effort or request. It is the most neutral synonym of acquire.","definitionCN":"获得；得到。它是最中性的 acquire 近义词，常用于努力或申请得来的东西。"},{"word":"gain","ipa":"/ɡeɪn/","tag":"add an advantage","definition":"to get something useful or valuable, such as an advantage or weight. It stresses the increase rather than the possession.","definitionCN":"获得（有用的东西、优势、体重等）。它强调“增加”，而不是“持有”。"},{"word":"get","ipa":"/ɡet/","tag":"plain and informal","definition":"to come to have something. It is the everyday verb behind all the formal synonyms and works for almost any object.","definitionCN":"得到；拿到。它是所有正式近义词背后的日常动词，几乎什么对象都能用。"},{"word":"purchase","ipa":"/ˈpɜːtʃəs/","tag":"buy","definition":"to buy something. It matches the buying sense of acquire but says nothing about learning or reputation.","definitionCN":"购买。它对应 acquire 的“购得”义，但不涉及学习或名声。"},{"word":"secure","ipa":"/sɪˈkjʊə/","tag":"get after effort","definition":"to get something, especially something difficult, and make it safe. It adds the idea of locking the gain down.","definitionCN":"（努力后）获得，并确保到手。它多了一层“把所得锁定”的意思。"},{"word":"attain","ipa":"/əˈteɪn/","tag":"reach a level","definition":"to reach a level, standard, or age. It is used for goals and heights rather than for objects you own.","definitionCN":"达到（水平、标准、年龄）。它用于目标和高度，而不是你拥有的物品。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts only: ad- + quaerere 'seek', the -ition/-ive/-er/-ee family, and the re- and un- branches.","cn":"只用真实构词成分：ad- + quaerere“寻求”，以及 -ition/-ive/-er/-ee 词族和 re-、un- 分支。"},"normal":[{"en":"acquire = ac- (ad-, 'to') + quire (quaerere, 'seek'): seek toward a thing until it is yours.","cn":"acquire = ac-（ad-，“向”）+ quire（quaerere，“寻求”）：朝某物寻求，直到它归你所有。"},{"en":"acquisition = acquire + -ition: the act of getting, whether a skill or a company.","cn":"acquisition = acquire + -ition：获得的行为，无论是技能还是公司。"},{"en":"acquiree is the company that is acquired; acquirer is the one doing the acquiring.","cn":"acquiree 是被收购的公司；acquirer 是实施收购的一方。"},{"en":"require and inquire are close relatives: require is 'seek again' (need), inquire is 'seek into' (ask).","cn":"require 和 inquire 是近亲：require 是“再寻求”（需要），inquire 是“寻求进去”（询问）。"},{"en":"acquired is the adjective for something gained later, as in acquired taste or acquired immunity.","cn":"acquired 是形容词，指后天获得的东西，如 acquired taste（后天养成的口味）、acquired immunity（后天免疫）。"}],"abstract":[{"en":"Imagine a circle drawn around you: acquiring is reaching out and moving a new thing across that line.","cn":"想象你周围画着一个圈：acquire 就是伸手出去，把一件新东西移过那条线。"},{"en":"The thing can be a book, a skill, a right, a habit, a dataset, or a reputation; the crossing of the line is the same.","cn":"那件东西可以是一本书、一项技能、一项权利、一个习惯、一份数据或一种名声；越过那条线这个动作是一样的。"},{"en":"Repeated crossings build a collection, which is why the Latin source also meant 'accumulate'.","cn":"一次次越过这条线，就积累成收藏——所以这个拉丁词源也有“积累”的意思。"}]},"examples":[{"en":"It takes time to acquire the confidence to speak in public.","cn":"获得当众讲话的自信需要时间。"},{"en":"The museum acquired the letters from a private collector.","cn":"博物馆从一位私人收藏家手中购得了这批信件。"},{"en":"She acquired a reputation for fairness among her colleagues.","cn":"她在同事中获得了公正的名声。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿快尔”——阿快尔手快，一伸手就把东西收进自己怀里 → acquire 获得","word":"acquire"},"root":"源自拉丁语 acquirere“额外得到、积累”，由 ad-“向”+ quaerere“寻求”构成；核心是“朝某物寻求，把它添进自己的所有物”。","sensesIntro":{"en":"Ten senses of acquire, all built on one movement: seek toward something and add it to what you already hold.","cn":"acquire 的十个义项都建立在一个动作上：朝某物寻求，并把它添进你已有的所有物里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand reaches toward a thing and draws it inside the owner's circle.","cn":"核心意象：一只手朝某物伸过去，把它拉进所有者的圈内。"},"chain":["SEEK","PURSUE","OBTAIN","GAIN","LEARN","OWN"],"branches":[{"senses":"S1 · S5","en":"LEARNING: knowledge and language are gained by repeated seeking and contact.","cn":"学习：知识和语言通过反复寻求与接触而得。"},{"senses":"S2 · S8","en":"POSSESSIONS: one bought object crosses the line; many crossings build a collection.","cn":"占有物：一件买来的物品越过界线；多次越线便积累成收藏。"},{"senses":"S3 · S4","en":"FORMAL TRANSFER: a company or a legal status passes into a new owner's control.","cn":"正式转移：公司或法律身份转入新所有者的控制之下。"},{"senses":"S6 · S9","en":"SLOW ATTACHMENT: a taste or a reputation accrues in small additions until it is said to be acquired.","cn":"缓慢附着：口味或名声一小份一小份地累积，直到人们说它已被“获得”。"},{"senses":"S7 · S10","en":"INFORMATION AND ROOT: data is stored as records, while the oldest layer is simply 'get in addition'.","cn":"信息与词源：数据以记录形式被存储；最古老的一层就是“额外得到”。"}]},"affixes":{"intro":{"en":"Acquire has a productive family: -ition, -ive, -er, -ee, -ed, -able, plus re- and un-.","cn":"acquire 有一个能产的词族：-ition、-ive、-er、-ee、-ed、-able，以及 re- 和 un-。"},"latinIntro":{"en":"The Latin family is built on quaerere 'to seek': acquirere 'get in addition', requirere 'seek again, need', inquirere 'seek into, investigate'.","cn":"这一拉丁词族建立在 quaerere“寻求”上：acquirere“额外得到”、requirere“再寻求、需要”、inquirere“寻求进去、调查”。"},"items":[{"word":"acquisition","structure":"acquire + -ition (stem acquisit-)","meaning":"the act of obtaining something, or a company that has been bought","meaningCN":"获得；收购；（被收购的）公司（-ition 构成名词）","example":"The acquisition doubled the company's size.","exampleCN":"这次收购使公司规模扩大了一倍。"},{"word":"acquisitive","structure":"acquisit- + -ive","meaning":"eager to acquire things, especially possessions","meaningCN":"贪得的；渴望占有的（-ive 构成形容词）","example":"An acquisitive society measures people by what they own.","exampleCN":"一个贪求占有的社会用人们拥有的东西来衡量人。"},{"word":"acquirer","structure":"acquire + -er","meaning":"a person or company that acquires something","meaningCN":"获得者；收购方（-er 表示施动者）","example":"The acquirer paid a high price for the firm.","exampleCN":"收购方为这家公司付了高价。"},{"word":"acquiree","structure":"acquire + -ee","meaning":"a company that is acquired by another","meaningCN":"被收购的公司（-ee 表示受动者）","example":"The acquiree kept its own brand after the deal.","exampleCN":"被收购方在交易后保留了自己的品牌。"},{"word":"acquired","structure":"acquire + -ed","meaning":"gained later rather than present from birth","meaningCN":"后天获得的（-ed 构成形容词，如 acquired immunity 后天免疫）","example":"Acquired immunity develops after exposure to a disease.","exampleCN":"后天免疫是在接触某种疾病之后形成的。"},{"word":"acquirable","structure":"acquire + -able","meaning":"possible to acquire","meaningCN":"可获得的；可习得的（-able 表示“可以……的”）","example":"These skills are acquirable with steady practice.","exampleCN":"这些技能通过稳定练习是可以习得的。"},{"word":"unacquired","structure":"un- (not) + acquired","meaning":"not yet gained or obtained","meaningCN":"尚未获得的（un- 表否定）","example":"The unacquired land remained in public hands.","exampleCN":"尚未被收购的土地仍归公众所有。"},{"word":"reacquire","structure":"re- (again) + acquire","meaning":"to acquire something again","meaningCN":"重新获得；再次购得（re- 表示“再次”）","example":"The family reacquired the house thirty years later.","exampleCN":"这家人三十年后重新买回了那栋房子。"},{"word":"acquisitiveness","structure":"acquisitive + -ness","meaning":"a strong desire to acquire things","meaningCN":"占有欲；获取欲（-ness 构成抽象名词）","example":"His acquisitiveness led him to collect rare maps.","exampleCN":"他的占有欲使他收集起了珍稀地图。"},{"word":"acquisitively","structure":"acquisitive + -ly","meaning":"in a way that shows a desire to acquire something","meaningCN":"带有获取欲地（-ly 构成副词）","example":"He looked at the painting acquisitively.","exampleCN":"他带着想占有的目光看着那幅画。"}],"latinEntries":[{"word":"acquirere","structure":"ad (to) + quaerere (seek)","meaning":"to get in addition, accumulate","meaningCN":"额外得到；积累（acquire 的直接拉丁来源）"},{"word":"quaerere","structure":"Latin verb","meaning":"to seek, look for, seek to obtain","meaningCN":"寻求；谋求；追问"},{"word":"requirere","structure":"re- (again) + quaerere (seek)","meaning":"to seek again; to need or demand","meaningCN":"再寻求；需要；要求（英语 require 的来源）"},{"word":"inquirere","structure":"in- (into) + quaerere (seek)","meaning":"to seek into; to investigate","meaningCN":"寻求进去；调查（英语 inquire 的来源）"}]}},{"word":"adapt","ipa_uk":"/əˈdæpt/","ipa_us":"/əˈdæpt/","definition_zh":"适应；改编；改装；使适合","definition_en":"to change something, or oneself, so that it fits new conditions or a new purpose","core_image":"把一件东西“贴合”到新的接口上","scene":"搬进老房子后，窄厨房里放着一张书架。 After moving into the old house, she adapted the bookshelf into a folding dining table.","sceneCN":"这里 adapt 是「改装、改作他用」（第 3 个义项：改造某物以适应新用途）；句意：搬进老房子后，她把书架改装成了一张可折叠的餐桌。","pos":[{"tag":"vt.","zh":"使适应；改编；改装；使适合"},{"tag":"vi.","zh":"适应（新环境、新条件）"}],"collocations":[{"phrase":"adapt to","zh":"适应（新环境、新条件）"},{"phrase":"adapt a novel for the screen","zh":"把小说改编成影视作品"},{"phrase":"adapt oneself to","zh":"使自己适应"},{"phrase":"be well adapted to","zh":"很好地适应……"},{"phrase":"adapt a building for wheelchair access","zh":"改造建筑以便轮椅通行"}],"forms":[{"label":"三单（he/she/it）","form":"adapts"},{"label":"过去式（已经发生）","form":"adapted"},{"label":"过去分词（完成／被动）","form":"adapted"},{"label":"现在分词（进行体）","form":"adapting"}],"derivatives":[{"word":"adaptation","pos":"n.","zh":"适应；改编；改编作品"},{"word":"adaptable","pos":"adj.","zh":"能适应的；适应性强的"},{"word":"adaptability","pos":"n.","zh":"适应能力；适应性"},{"word":"adapter","pos":"n.","zh":"适配器；改编者"},{"word":"adaptor","pos":"n.","zh":"转接器；适配器（另一种拼写）"},{"word":"maladapted","pos":"adj.","zh":"适应不良的；不适应环境的"}],"senses":[{"no":"01","title":"Adjust to a new environment","titleCN":"适应新环境","definition":"to change one's behaviour or ideas in order to deal with a new situation","definitionCN":"改变自己的行为或观念以应对新情况","example":"It took him a month to adapt to life in the countryside.","exampleCN":"他花了一个月才适应乡下的生活。","why":"Latin adaptare is ad- 'to' plus aptare 'to fit': something is fitted onto a new shape. When the thing being fitted is yourself, adapt means changing until you sit well in the new situation.","whyCN":"拉丁语 adaptare 是 ad-“向”加 aptare“使贴合”：把某物贴合到一个新的形状上。当被贴合的是你自己时，adapt 就是改变自己，直到在新环境里坐得稳。"},{"no":"02","title":"Adapt oneself to a role or a place","titleCN":"使自己适应某个角色或场所","definition":"to make oneself suitable for a particular role, group, or place","definitionCN":"使自己适合某个角色、群体或场所","example":"She adapted herself quickly to the routines of the newsroom.","exampleCN":"她很快使自己适应了新闻编辑室的日常节奏。","why":"The same fitting can be done deliberately to oneself: you are both the object being shaped and the one doing the shaping. This is why English allows adapt oneself to.","whyCN":"同一种“贴合”可以刻意施加在自己身上：你既是被塑形的对象，也是塑形的人。正因如此，英语里可以说 adapt oneself to。"},{"no":"03","title":"Turn a story into a film or a play","titleCN":"改编（小说、故事为影视或戏剧）","definition":"to change a book, story, or play into a different form, such as a film","definitionCN":"把书、故事或戏剧改成另一种形式，如电影","example":"The novel was adapted for the screen in 2019.","exampleCN":"这部小说在 2019 年被改编成电影。","why":"A novel and a film have different shapes. Adapting does not copy the novel; it refits the same story onto the frame of another medium, so that it sits properly there.","whyCN":"小说和电影有不同的形状。改编不是复制小说，而是把同一个故事重新贴合到另一种媒介的框架上，让它在那边也能合身。"},{"no":"04","title":"Simplify a text for learners","titleCN":"改写（为学习者简写文本）","definition":"to rewrite a text in a simpler form for a particular group of readers","definitionCN":"为特定读者群体把文本改写成更简单的形式","example":"The classic is adapted for learners at level three.","exampleCN":"这部经典被改写成适合三级学习者的版本。","why":"Here the new shape is the reader's level. The text is cut and rewrapped until it fits that level; the original is not changed, only refitted.","whyCN":"这里的新形状是读者的水平。文本被裁剪、重新包装，直到贴合那个水平；原著没变，只是被重新合身了一次。"},{"no":"05","title":"Rebuild an object for a new use","titleCN":"改装物品、改造建筑","definition":"to change an object or a building so that it can be used for a different purpose","definitionCN":"改造某件物品或建筑，使其能用于另一种用途","example":"The barn was adapted into a small library.","exampleCN":"谷仓被改造成了一间小图书馆。","why":"A building has a fixed frame; adapting it means fitting a new function into that frame. The object stays, its interface changes.","whyCN":"建筑有固定的骨架；改造它就是给这副骨架接上新的功能。物体还在，接口换了。"},{"no":"06","title":"Adjust a method or a plan","titleCN":"调整方法、行为或计划","definition":"to change a method, plan, or approach so that it works better in the situation","definitionCN":"改变方法、计划或做法，使其更适应当前情况","example":"The teacher adapted her approach for the quieter class.","exampleCN":"老师针对这个比较安静的班级调整了教学方法。","why":"A method is a tool with a grip; if the handle no longer matches the hand, it is refitted. Adapting a plan is regripping it for the actual conditions.","whyCN":"方法是带握柄的工具；握柄不再合手时，就要重新贴合。调整计划，就是按实际情况重新握住它。"},{"no":"07","title":"Evolve to suit an environment","titleCN":"（生物）适应环境","definition":"to become better suited to an environment through evolution","definitionCN":"通过进化变得更适合某种环境","example":"These plants are adapted to very dry soil.","exampleCN":"这些植物适应了非常干燥的土壤。","why":"In biology the fitting happens without a designer: generation after generation, a body is shaped until it matches its habitat. Adapt here is slow fitting by survival.","whyCN":"在生物学里，这种贴合没有设计者：一代又一代，身体被塑形，直到与栖息地相合。这里的 adapt 是靠生存完成的缓慢贴合。"},{"no":"08","title":"Modify something for a specific need","titleCN":"为特定需求调整某物","definition":"to change something so that it meets a particular person's or group's needs","definitionCN":"调整某物以满足特定人或群体的需求","example":"The recipe was adapted to be free of dairy.","exampleCN":"这份食谱被调整成了不含乳制品的版本。","why":"The new shape here is a need: no dairy, less salt, more space. Adapting is fitting the thing to that requirement rather than to the general standard.","whyCN":"这里的新形状是一项需求：不含乳制品、少盐、更大的空间。改编就是让东西贴合这项要求，而不是贴合通用标准。"},{"no":"09","title":"Historical: to fasten or fit on","titleCN":"古义：系上、使贴合","definition":"in the Latin source, to fit or fasten something onto something else","definitionCN":"在拉丁语源中，指把某物装上、系上或贴合到另一物上","example":"Latin aptare could describe fitting a handle to a tool.","exampleCN":"拉丁语 aptare 可以指给工具装上一个握柄。","why":"This is the literal root: aptus meant 'fastened, joined'. The modern meanings are that physical joining applied to behaviour, stories, buildings, methods and bodies.","whyCN":"这是字面的词根层：aptus 意为“系紧的、接上的”。现代各义项，都是这种物理上的接合被用到行为、故事、建筑、方法和身体上。"},{"no":"10","title":"Word family: -ation names the fit or its product","titleCN":"词族：-ation 指贴合过程或产物","definition":"the suffix -ation forms adaptation, naming the process of adapting or the changed product","definitionCN":"后缀 -ation 构成 adaptation，指适应的过程或改编后的产物","example":"The film adaptation keeps the ending of the novel.","exampleCN":"这部改编电影保留了小说的结局。","why":"The verb names an act of refitting; -ation turns it into either the process or the thing that now fits. English uses the same noun for the journey and for the result.","whyCN":"动词指重新贴合的动作；-ation 把它变成过程，或变成现在已合身的东西。英语用同一个名词兼指“过程”和“产物”。"}],"etymology":{"intro":{"en":"Adapt entered English in the early 15c. through French, but its core is Latin adaptare 'fit to', built on aptus 'fitted'. The intransitive biological sense is surprisingly late, from 1956.","cn":"adapt 在 15 世纪初经由法语进入英语，核心是拉丁语 adaptare“使贴合”，其基础是 aptus“合身的”。不及物的生物学用法出现得意外地晚，来自 1956 年。"},"items":[{"era":"EARLY 15C","en":"English recorded adapt in the early 15c. (implied in adapted) meaning 'to fit something for a purpose'. It was borrowed through French rather than taken directly from Latin.","cn":"英语在 15 世纪初记录 adapt（见于 adapted），意为“使某物适合某一用途”。它经由法语借入，而不是直接从拉丁语搬来。"},{"era":"OLD FRENCH (14C)","en":"Old French adapter meant 'to fit, suit, adapt' and supplied the immediate form taken into English.","cn":"古法语 adapter 意为“使适合、使相配”，是英语借入的直接形式。"},{"era":"LATIN","en":"Adaptare 'to fit to' is ad- 'to' plus aptare 'to fit, put in order', a verb from aptus 'fit, suited'. The physical image is something fastened or joined on.","cn":"adaptare“使贴合”由 ad-“朝向”加 aptare“使适合、整理”构成，后者来自 aptus“合身的、合适的”。其具体意象是某物被系上、接上。"},{"era":"LATIN APTUS","en":"Aptus was the past participle of *apere 'to attach, join, tie to'. The physical sense 'fastened on' is the source of the modern idea of fitting.","cn":"aptus 是 *apere“系上、连接、绑上”的过去分词。正是“被系上”这个具体义，长成了现代“适合”的抽象义。"},{"era":"1956 ENGLISH","en":"The intransitive sense 'to undergo modification so as to fit new circumstances' is recorded from 1956, especially in biology. Before that, adapt was mainly transitive.","cn":"不及物义“为适应新环境而发生改变”记录于 1956 年，尤其用于生物学。在此之前，adapt 主要是及物动词。"},{"era":"PROTO-INDO-EUROPEAN","en":"Aptus is commonly connected with PIE *ap- (1) 'to grasp, take, reach'. The link is plausible but reconstructed, so the deepest step is source uncertain.","cn":"aptus 通常被联系到原始印欧语 *ap-（第 1 义）“抓住、取得、够到”。这一联系看似合理但属重构，故最深层来源不确定。"}]},"similar":{"note":{"en":"Adopt is the classic one-letter trap; adept and apt are also close in shape. The second group gives true synonyms with different shades.","cn":"adopt 是最经典的“差一个字母”陷阱；adept 和 apt 在词形上也很近。第二组给出真正的近义词及各自侧重。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adopt","ipa":"/əˈdɒpt/","tag":"one-letter trap","definition":"to take a child into your family, or to start using an idea or method. It differs from adapt by one vowel and has nothing to do with fitting.","definitionCN":"收养；采用（想法、方法）。它与 adapt 只差一个元音，意思却与“贴合”无关。"},{"word":"adept","ipa":"/əˈdept/","tag":"near spelling and sound","definition":"very skilled at something, used as an adjective or a noun. It sounds close to adapt but describes skill, not fitting.","definitionCN":"熟练的；内行（形容词或名词）。读音接近 adapt，但描述的是技能，不是贴合。"},{"word":"apt","ipa":"/æpt/","tag":"short base form","definition":"suitable or appropriate; also likely to do something. It is the Latin base behind adapt, but shorter and with a different vowel.","definitionCN":"恰当的；易于……的。它是 adapt 背后的拉丁词根词，但更短，元音也不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adjust","ipa":"/əˈdʒʌst/","tag":"small change","definition":"to change something slightly so that it fits or works better. It usually suggests a smaller correction than adapt.","definitionCN":"调整；微调。它通常指比 adapt 更小的修正。"},{"word":"accommodate","ipa":"/əˈkɒmədeɪt/","tag":"make room for","definition":"to change in order to meet someone's needs, or to provide space for them. It stresses the needs of the other party.","definitionCN":"迁就；容纳；迎合……的需要。它强调照顾对方的需求。"},{"word":"modify","ipa":"/ˈmɒdɪfaɪ/","tag":"change form","definition":"to change something in form or quality, often only in part. It is broader and less goal-directed than adapt.","definitionCN":"修改；改动（形式或性质，常为部分改动）。它比 adapt 更宽泛，目标性更弱。"},{"word":"alter","ipa":"/ˈɔːltə/","tag":"general change","definition":"to make something different. It says nothing about fitting a purpose, so it is wider than adapt.","definitionCN":"改变；改动。它不涉及“是否合目的”，因此比 adapt 范围更广。"},{"word":"acclimatize","ipa":"/əˈklaɪmətaɪz/","tag":"climate and body","definition":"to become used to a new climate or conditions. It is a narrow kind of adapting, usually about the body.","definitionCN":"（使）适应气候或新环境。它是 adapt 的一种窄义，通常指身体。"},{"word":"fit","ipa":"/fɪt/","tag":"match shape","definition":"to be the right size or shape, or to make something match. It names the result that adapt aims at.","definitionCN":"合身；使相配。它指 adapt 所要达到的那个结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces only: ad- + aptare 'fit', the -ation/-able/-ability family, and the mal- and re- branches.","cn":"只用真实成分：ad- + aptare“使适合”，-ation/-able/-ability 词族，以及 mal-、re- 分支。"},"normal":[{"en":"adapt = ad- ('to') + apt ('fit'): to fit something to a new shape.","cn":"adapt = ad-（“向”）+ apt（“合适”）：把某物贴合到一个新形状。"},{"en":"apt, aptitude and adapt all sit on the same Latin base aptus 'fitted'.","cn":"apt、aptitude、adapt 都坐在同一个拉丁基础 aptus“合身的”上。"},{"en":"adaptation = adapt + -ation: both the process of fitting and the film or book that results.","cn":"adaptation = adapt + -ation：既指贴合的过程，也指由此产生的电影或书。"},{"en":"adaptable and adaptability add -able and -ity: able to be fitted, and the quality of being fittable.","cn":"adaptable 和 adaptability 加上 -able 与 -ity：能被贴合，以及可贴合的性质。"},{"en":"maladapted uses mal- 'bad': fitted badly to the environment.","cn":"maladapted 用 mal-“坏”：贴合得很糟，不适应环境。"}],"abstract":[{"en":"Think of a key and a lock: adapting is recutting the key until it turns in the new lock.","cn":"想象一把钥匙和一把锁：adapt 就是把钥匙重新锉到能转动新锁为止。"},{"en":"The key can be a person, a story, a building, a method, a recipe or a species; the recutting is the same.","cn":"这把“钥匙”可以是人、故事、建筑、方法、食谱或物种；重新锉的过程是一样的。"},{"en":"The noun adaptation can name either the recutting or the newly fitting key.","cn":"名词 adaptation 既可以指锉钥匙的过程，也可以指那把已经合用的新钥匙。"}]},"examples":[{"en":"The children adapted quickly to their new school.","cn":"孩子们很快就适应了新学校。"},{"en":"The play was adapted from a short story by Chekhov.","cn":"这部戏剧改编自契诃夫的一个短篇小说。"},{"en":"The kitchen was adapted for a wheelchair user.","cn":"厨房被改造得适合轮椅使用者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿达普特”——阿达铺好床垫，身体正好贴合新床 → adapt 适应、使适合","word":"adapt"},"root":"源自拉丁语 adaptare“使贴合”，由 ad-“向”+ aptare“使适合”构成，而 aptare 来自 aptus“合身的、系紧的”；核心是“把某物接到新的形状上”。","sensesIntro":{"en":"Ten senses of adapt, all one operation: take something with an existing shape and refit it to a new frame — a place, a medium, a use, a need, or a habitat.","cn":"adapt 的十个义项都是同一个操作：拿一个已有形状的东西，把它重新贴合到新的框架上——新地方、新媒介、新用途、新需求或新栖息地。"},"semanticMap":{"core":{"en":"CORE IMAGE: an object or a self is refitted onto a new frame until it sits well.","cn":"核心意象：一件物品或一个自我被重新贴合到新框架上，直到严丝合缝。"},"chain":["FIT","FASTEN","MATCH","ADJUST","CHANGE","SUIT"],"branches":[{"senses":"S1 · S2","en":"SELF-FITTING: a person changes behaviour, or deliberately reshapes the self, to sit in a new situation.","cn":"自我贴合：人改变行为，或有意识地重塑自己，以便在新环境中坐稳。"},{"senses":"S3 · S4","en":"MEDIUM FITTING: a story is refitted to the frame of a film, or to the level of a learner.","cn":"媒介贴合：故事被重新装到电影的框架上，或装到学习者的水平上。"},{"senses":"S5 · S8","en":"PURPOSE FITTING: a building, object, or recipe is changed to serve a new use or a specific need.","cn":"用途贴合：建筑、物品或食谱被改动，以服务新用途或特定需求。"},{"senses":"S6 · S7","en":"CONDITION FITTING: a method is regripped for real conditions, and a species is shaped by its habitat over generations.","cn":"条件贴合：方法按现实条件重新握好，物种则被栖息地在一代代中塑形。"},{"senses":"S9 · S10","en":"ROOT AND NOUN: the oldest layer is physical fastening; -ation names either the refitting or the fitted product.","cn":"词根与名词：最古一层是物理上的装接；-ation 指重新贴合的过程或已贴合的产品。"}]},"affixes":{"intro":{"en":"Adapt forms a regular family with -ation, -able, -ability, -er/-or and -ed, plus the prefixes mal- and re-.","cn":"adapt 与 -ation、-able、-ability、-er/-or、-ed 构成规则词族，另有前缀 mal- 和 re-。"},"latinIntro":{"en":"The Latin base is aptus 'fitted, fastened', with aptare 'to fit' and adaptare 'to fit to'. Aptitude and apt belong to the same base.","cn":"拉丁基础是 aptus“合身的、系紧的”，并有 aptare“使适合”和 adaptare“使贴合”。aptitude 与 apt 同属这一基础。"},"items":[{"word":"adaptation","structure":"adapt + -ation","meaning":"the process of adapting, or a work changed into a new form","meaningCN":"适应；改编；改编作品（-ation 构成过程或结果名词）","example":"The adaptation moved the story to modern Tokyo.","exampleCN":"这版改编把故事搬到了现代东京。"},{"word":"adaptable","structure":"adapt + -able","meaning":"able to change to suit new conditions","meaningCN":"能适应的；适应性强的（-able 表示“能够……”）","example":"The desk is light and adaptable.","exampleCN":"这张桌子轻便且便于改造。"},{"word":"adaptability","structure":"adaptable + -ity","meaning":"the quality of being able to adapt","meaningCN":"适应能力；灵活性（-ity 构成抽象名词）","example":"Adaptability matters more than raw strength in this job.","exampleCN":"这份工作里，适应能力比蛮力更重要。"},{"word":"adapter","structure":"adapt + -er","meaning":"a device that connects different fittings, or a person who adapts a work","meaningCN":"适配器；改编者（-er 表示工具或施动者）","example":"The adapter lets the old lens fit the new camera.","exampleCN":"这个转接器让旧镜头能装到新相机上。"},{"word":"adaptor","structure":"adapt + -or","meaning":"the same device, spelled with the Latin -or suffix","meaningCN":"转接器；适配器（-or 拼写变体）","example":"The travel adaptor has three sockets.","exampleCN":"这个旅行转换器有三个插孔。"},{"word":"adapted","structure":"adapt + -ed","meaning":"changed to fit a new situation, used as an adjective","meaningCN":"已适应的；改编过的（-ed 构成形容词）","example":"The text is an adapted version for beginners.","exampleCN":"这个文本是面向初学者的改写版。"},{"word":"maladapted","structure":"mal- (bad, badly) + adapted","meaning":"poorly suited to the environment","meaningCN":"适应不良的（mal- 表示“坏、不良”）","example":"A maladapted response can make the crisis worse.","exampleCN":"适应不良的反应会让危机更糟。"},{"word":"readapt","structure":"re- (again) + adapt","meaning":"to adapt again after a change","meaningCN":"重新适应；重新改编（re- 表示“再次”）","example":"The team had to readapt after the merger.","exampleCN":"合并之后团队不得不重新适应。"},{"word":"adaptive","structure":"adapt + -ive","meaning":"able to change in order to fit new conditions","meaningCN":"有适应力的；能调整的（-ive 构成形容词）","example":"Adaptive teaching responds to each learner’s pace.","exampleCN":"适应性教学会回应每个学习者的节奏。"},{"word":"adaptively","structure":"adaptive + -ly","meaning":"in a way that changes to fit new conditions","meaningCN":"以适应的方式（-ly 构成副词）","example":"The team responded adaptively to the sudden change.","exampleCN":"团队以适应的方式回应了突如其来的变化。"}],"latinEntries":[{"word":"aptus","structure":"Latin adjective, literally 'fastened, joined'","meaning":"fit, suited, appropriate","meaningCN":"合适的；相配的（字面“装上的、接合的”）"},{"word":"aptare","structure":"Latin verb from aptus","meaning":"to fit, adjust, put in order","meaningCN":"使适合；调整；整理"},{"word":"adaptare","structure":"ad (to) + aptare (fit)","meaning":"to fit to, adapt","meaningCN":"使贴合；使适应（adapt 的直接拉丁来源）"},{"word":"aptitudo","structure":"aptus + -itudo (noun suffix)","meaning":"fitness, aptitude","meaningCN":"适合性；资质（英语 aptitude 的来源）"}]}},{"word":"adequate","ipa_uk":"/ˈædɪkwət/","ipa_us":"/ˈædɪkwət/","definition_zh":"足够的；充分的；合格的；适当的","definition_en":"enough in quantity, or good enough in quality, for a particular purpose or standard","core_image":"水位刚好升到刻度线——不多不少，够用","scene":"验收时，工程师拿着照度计站在教室门口。 At the inspection the engineer said the light in the classroom was adequate and no extra lamps were needed.","sceneCN":"这里 adequate 是「足够的、达标的」（第 1 个义项：数量或程度满足需要）；句意：验收时，工程师说这间教室的照度足够，不必再加灯。","pos":[{"tag":"adj.","zh":"足够的；充分的；合格的；适当的"}],"collocations":[{"phrase":"adequate for","zh":"对……来说足够"},{"phrase":"an adequate supply","zh":"充足的供应"},{"phrase":"adequate evidence","zh":"充分的证据"},{"phrase":"more than adequate","zh":"绰绰有余"},{"phrase":"adequate to the task","zh":"足以胜任这项任务"}],"forms":[{"label":"比较级（更……）","form":"more adequate"},{"label":"最高级（最……）","form":"most adequate"}],"derivatives":[{"word":"adequacy","pos":"n.","zh":"足够；充分；胜任"},{"word":"adequately","pos":"adv.","zh":"充分地；足够地；恰当地"},{"word":"inadequate","pos":"adj.","zh":"不足的；不充分的；不胜任的"},{"word":"inadequacy","pos":"n.","zh":"不足；不充分；不胜任"},{"word":"adequateness","pos":"n.","zh":"足够；适当（罕用）"}],"senses":[{"no":"01","title":"Enough in quantity","titleCN":"数量足够","definition":"enough in amount for a particular need or purpose","definitionCN":"在数量上足以满足某种需要或目的","example":"We have adequate food for the three-day trip.","exampleCN":"我们有足够的食物应付这三天的行程。","why":"Latin aequus meant 'level, even'. A quantity is adequate when its surface rises to the required line: not below it, and not necessarily far above it.","whyCN":"拉丁语 aequus 意为“水平的、齐平的”。数量足够，就是它的“水面”升到了要求的那条线：不低于，也不必远高于。"},{"no":"02","title":"Sufficient in degree","titleCN":"程度充分","definition":"great enough in degree, strength, or detail for the purpose","definitionCN":"在程度、强度或细节上足以达到目的","example":"The lamp gives adequate light for reading.","exampleCN":"这盏灯的光线足够读书。","why":"The line can be drawn at any degree: light, heat, detail, care. Adequate means the level of that quality reaches the line the task sets.","whyCN":"这条线可以画在任何“程度”上：亮度、热度、细节、用心程度。adequate 就是这项品质的水平达到了任务设定的那条线。"},{"no":"03","title":"Good enough in quality","titleCN":"质量合格、达标","definition":"good enough to meet a required standard, though not excellent","definitionCN":"达到规定标准，虽不优秀但已够格","example":"The report was adequate, but it lacked original analysis.","exampleCN":"这份报告达到了要求，但缺少原创分析。","why":"Quality is also measured on a scale. The pass line is the level a piece of work must reach; adequate means it touches that line, no more.","whyCN":"质量同样在刻度上衡量。及格线是一件作品必须达到的高度；adequate 表示它刚好碰到那条线，没有更高。"},{"no":"04","title":"Acceptable but not impressive","titleCN":"尚可、勉强够用","definition":"acceptable or passable, often suggesting that something better was possible","definitionCN":"可以接受、勉强过得去，常暗示本可以更好","example":"The hotel room was adequate for one night.","exampleCN":"这间酒店房间住一晚还算凑合。","why":"A line that is only touched, not crossed, leaves no margin. That is why adequate can carry a faint shrug: it satisfies the requirement, but the word does not praise.","whyCN":"只是碰到线、没有越过，就没有余量。这就是 adequate 常带一点“耸耸肩”意味的原因：它满足了要求，但这个词本身并不称赞。"},{"no":"05","title":"Appropriate to the occasion","titleCN":"适当的、恰当的","definition":"suitable or appropriate for a particular situation or purpose","definitionCN":"适合特定情境或目的的；恰当的","example":"The committee took adequate measures to protect the records.","exampleCN":"委员会采取了适当的措施来保护这些记录。","why":"Fitting the occasion is matching one shape to another. What is adequate is level with the demand of the moment, neither too weak nor out of place.","whyCN":"适合场合，就是让一个形状与另一个形状相合。adequate 的东西与当下的需求齐平，既不太弱，也不显得不合时宜。"},{"no":"06","title":"Competent for a job or role","titleCN":"胜任的、够格的","definition":"having enough skill or ability to do a job or fill a role","definitionCN":"拥有足够的技能或能力完成工作或胜任角色","example":"She is adequate to the demands of the position.","exampleCN":"她足以胜任这个职位的要求。","why":"A person's capacity is also a level. If that level reaches the line set by the job, the person is adequate to it; the same image now measures ability rather than volume.","whyCN":"人的能力也是一个高度。如果这个高度达到了职位设定的线，这个人就 adequate to it；同一个意象，这里量的不是容量，而是能力。"},{"no":"07","title":"Corresponding or equal to something","titleCN":"与……相当、对等","definition":"equal or corresponding to something in amount, value, or meaning","definitionCN":"在数量、价值或含义上与某事物相等或相当","example":"The punishment should be adequate to the seriousness of the offence.","exampleCN":"惩罚应与罪行的严重程度相当。","why":"This is the oldest layer made visible: adaequare was 'to make equal to'. Adequate to X means level with X, a pair of equal heights rather than a mere supply.","whyCN":"这是最古老一层直接露出来的地方：adaequare 就是“使与……相等”。adequate to X 意为与 X 齐平，是一对相等的高度，而不只是“有存货”。"},{"no":"08","title":"Sufficient as proof or reason","titleCN":"（证据、理由）充分的","definition":"strong enough to support a claim, decision, or legal judgment","definitionCN":"足以支撑某项主张、决定或法律判断的","example":"There was adequate evidence to justify the investigation.","exampleCN":"有充分的证据支持这项调查。","why":"In law and logic, proof must climb to the line set for the claim. Below it the evidence is insufficient; at it, adequate; above it, strong or conclusive.","whyCN":"在法律和逻辑里，证据必须爬到为该项主张设定的那条线。线以下是“不足”，到线是 adequate，线以上才是“有力”或“确凿”。"},{"no":"09","title":"Historical: equal to, made level with","titleCN":"词源义：与……相等、齐平","definition":"in the Latin source, made equal or level with something","definitionCN":"在拉丁语源中，指与某物相等或齐平","example":"The Latin adaequatus literally meant 'made equal to'.","exampleCN":"拉丁语 adaequatus 字面上就是“被弄得与……相等”。","why":"This is the parent sense: ad- 'to' plus aequare 'make level' gives 'equal to'. Sufficiency is a later child of equality: enough is the amount that is level with the need.","whyCN":"这是母义：ad-“向”加 aequare“使齐平”就是“与……相等”。足够是“相等”后来生出的孩子：够用的量，就是与需求齐平的那个量。"}],"etymology":{"intro":{"en":"Adequate came into English in the 17c. through French from Latin adaequatus, the past participle of adaequare 'to make equal to'. The base aequus also gives equal, equity and equator.","cn":"adequate 在 17 世纪经由法语进入英语，来自拉丁语 adaequatus，即 adaequare“使与……相等”的过去分词。其基础 aequus 还给出 equal、equity 和 equator。"},"items":[{"era":"MODERN ENGLISH","en":"Recorded from the 1610s meaning 'equal to what is required; suitable to the case'. The modern sense 'enough' grew from that idea of being level with a requirement.","cn":"自 17 世纪 10 年代起有记录，意为“与所需之物相等；适合情况”。现代“足够”的义项，就是从“与要求齐平”这一观念长出来的。"},{"era":"FRENCH","en":"French adéquat was the immediate borrowed form, carrying the Latin sense of being equal or proportionate.","cn":"法语 adéquat 是直接借入的形式，带着拉丁语“相等、相称”的意思。"},{"era":"LATIN","en":"adaequatus is the past participle of adaequare 'to make equal to', from ad- 'to' + aequare 'to make level'.","cn":"adaequatus 是 adaequare“使与……相等”的过去分词，由 ad-“向”+ aequare“使齐平”构成。"},{"era":"LATIN (AEQUUS)","en":"aequus meant 'level, even, equal, just'. It also lies behind equal, equality, equity and equator, the line where day and night are equal.","cn":"aequus 意为“平的、齐的、相等的、公正的”。它也支撑 equal、equality、equity 和 equator（昼夜等长之线）。"},{"era":"PROTO-INDO-EUROPEAN","en":"The deeper origin of aequus is uncertain: no single earlier root is firmly established. source uncertain. For English the safe starting point is the Latin adjective, not a reconstructed form.","cn":"aequus 更早的来源不确定：没有哪一个更早的词根被牢固确立。来源不确定。对英语而言，可靠的起点是拉丁形容词本身，而不是某个构拟形式。"}]},"similar":{"note":{"en":"The first group is built on the same equ- shape but has different meanings; the second group gives true near-synonyms.","cn":"第一组共享 equ- 词形但意思不同；第二组是真正的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"equate","ipa":"/ɪˈkweɪt/","tag":"same Latin base","definition":"to treat two things as equal. It comes from the same aequus base but is a verb about comparison, not sufficiency.","definitionCN":"把两件事等同起来。它来自同一个 aequus 基础，但这是比较的动词，不表示“足够”。"},{"word":"equitable","ipa":"/ɪˈkwɪtəbl/","tag":"same equ- shape","definition":"fair and impartial. It looks close to adequate but belongs to the idea of justice, not quantity.","definitionCN":"公平的；公正的。它看上去接近 adequate，但属于“公正”的观念，与数量无关。"},{"word":"adulate","ipa":"/əʸdjuːleɪt/","tag":"similar ad- + -ate shape","definition":"to praise someone far too much. It shares the ad- opening and -ate ending but has no link to level or sufficiency.","definitionCN":"过分称赞；谄媚。它同样以 ad- 开头、-ate 结尾，但与“齐平、足够”毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sufficient","ipa":"/səˈfɪʃənt/","tag":"formal enough","definition":"enough for a particular purpose. It is more formal than adequate and focuses strictly on quantity or degree.","definitionCN":"足够的；充分的。它比 adequate 正式，严格聚焦于数量或程度。"},{"word":"enough","ipa":"/ɪˈnʌf/","tag":"plain and neutral","definition":"as much as is needed. It is the everyday word behind adequate and carries no hint of quality.","definitionCN":"足够的。它是 adequate 背后的日常词，不暗示质量高低。"},{"word":"satisfactory","ipa":"/ˌsætɪsˈfæktəri/","tag":"meets expectations","definition":"good enough to be accepted. It adds a judgment: someone is satisfied, whereas adequate only states the level.","definitionCN":"令人满意的；合格的。它多了一层判断：有人满意了，而 adequate 只陈述水平。"},{"word":"acceptable","ipa":"/əkˈseptəbl/","tag":"allowed but not praised","definition":"good enough to be allowed or tolerated. It is close to sense 4 and often implies a low bar.","definitionCN":"可接受的；过得去的。它接近义项 4，常暗示标准不高。"},{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"person's skill","definition":"having enough skill for a task. It is used mainly of people, where adequate would need 'to the task'.","definitionCN":"胜任的；有能力的。它主要用于人，而 adequate 指人时需要接 to the task。"},{"word":"suitable","ipa":"/ˈsuːtəbl/","tag":"right for the case","definition":"right or appropriate for a purpose. It matches sense 5 and stresses fit rather than amount.","definitionCN":"合适的；适宜的。它对应义项 5，强调“相配”而非“数量”。"}]}]},"mnemonics":{"normalIntro":{"en":"Real pieces only: ad- + aequare 'make level', the equal/equity family, and the -acy/-ly/-ness and in- branches.","cn":"只用真实成分：ad- + aequare“使齐平”，equal/equity 词族，以及 -acy/-ly/-ness 和 in- 分支。"},"normal":[{"en":"adequate = ad- ('to') + aequus ('level'): brought level with the need.","cn":"adequate = ad-（“向”）+ aequus（“齐平”）：被弄得与需求齐平。"},{"en":"equal, equality, equity and equator all sit on the same aequus base as adequate.","cn":"equal、equality、equity、equator 与 adequate 都坐在同一个 aequus 基础上。"},{"en":"adequacy = adequate + -acy: the state of being enough.","cn":"adequacy = adequate + -acy：足够的状态。"},{"en":"inadequate = in- + adequate: the level falls below the line.","cn":"inadequate = in- + adequate：水平落到线以下。"},{"en":"adequate to the task literally means 'level with the task' — the same 'equal to' idea as the Latin participle.","cn":"adequate to the task 字面上就是“与任务齐平”——和拉丁分词“与……相等”是同一个想法。"}],"abstract":[{"en":"Picture a glass of water and a line drawn on the side: adequate is the water reaching that line.","cn":"想象一杯水和杯壁上画的一条线：adequate 就是水升到了那条线。"},{"en":"The line can mark food, light, quality, skill, evidence, or punishment; in every case the question is 'is it level with the need?'","cn":"这条线可以标食物、光线、质量、技能、证据或惩罚；每一种情况下，问题都是“它与需求齐平了吗？”"},{"en":"Because the word only says 'at the line', it never promises excellence — that is why adequate can sound faintly lukewarm.","cn":"因为这个词只说“到了线”，从不承诺优秀——所以 adequate 听起来总有点不冷不热。"}]},"examples":[{"en":"The shelter provided adequate space for forty people.","cn":"这座避难所为四十个人提供了足够的空间。"},{"en":"His salary is adequate to support his family.","cn":"他的薪水足以养家。"},{"en":"The court found the evidence adequate to proceed.","cn":"法庭认为证据充分，可以继续审理。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿德夸特”——阿德夸口说“够特了”，水位刚好到刻度 → adequate 足够的","word":"adequate"},"root":"源自拉丁语 adaequatus，即 adaequare“使与……相等”的过去分词，基础是 aequus“齐平的、相等的”；核心是“刚好与需求齐平、够用”。","sensesIntro":{"en":"Nine senses of adequate. All of them ask one question: has this reached the line drawn by the need, the standard, or the occasion?","cn":"adequate 的九个义项都在问同一个问题：它是否达到了由需求、标准或场合画出的那条线？"},"semanticMap":{"core":{"en":"CORE IMAGE: a level rises exactly to the marked line — enough, no more.","cn":"核心意象：水平面正好升到刻线——够用，不多不少。"},"chain":["MEASURE","LEVEL","EQUAL","MATCH","ENOUGH","ACCEPTABLE"],"branches":[{"senses":"S1 · S2","en":"AMOUNT AND DEGREE: a supply or a quality rises to the required line.","cn":"数量与程度：供应量或某种品质升到要求的那条线。"},{"senses":"S3 · S4","en":"QUALITY: a pass line is touched, which satisfies the standard but leaves no margin for praise.","cn":"质量：碰到及格线，满足标准，却没有留下可供称赞的余量。"},{"senses":"S5 · S8","en":"FITNESS AND PROOF: measures match the occasion, and evidence climbs to the line set for the claim.","cn":"适配与证明：措施与场合相合，证据爬到为该项主张设定的线。"},{"senses":"S6","en":"PERSON: a person's capacity is measured against the line set by the role.","cn":"人：一个人的能力被拿来与角色设定的线对照。"},{"senses":"S7 · S9","en":"EQUALITY: the oldest sense is 'made equal to'; correspondence and sufficiency both grow from that level pair.","cn":"相等：最古老的义项是“被弄得与……相等”；对应与足够都从这一对齐平的高度长出来。"}]},"affixes":{"intro":{"en":"Adequate has a compact family: -acy, -ly, -ness, -ion, and the negative prefix in-. The Latin base aequus also supports equal and equity.","cn":"adequate 的词族不大：-acy、-ly、-ness、-ion，以及否定前缀 in-。拉丁基础 aequus 还支撑 equal 与 equity。"},"latinIntro":{"en":"The Latin family is built on aequus 'level, equal': aequare 'make level', adaequare 'make equal to', aequalitas 'equality'.","cn":"这一拉丁词族建立在 aequus“平的、相等的”上：aequare“使齐平”、adaequare“使与……相等”、aequalitas“相等”。"},"items":[{"word":"inadequate","structure":"in- (not) + adequate","meaning":"not enough, or not good enough","meaningCN":"不足的；不充分的；不胜任的（in- 表否定）","example":"The lighting was inadequate for night work.","exampleCN":"这样的照明不足以应付夜间工作。"},{"word":"inadequately","structure":"in- (not) + adequately","meaning":"in a way that is not sufficient","meaningCN":"不充分地；不够地（in- 加在副词上）","example":"The room was inadequately heated.","exampleCN":"这个房间供暖不足。"},{"word":"inadequacy","structure":"in- (not) + adequacy","meaning":"the state of being insufficient","meaningCN":"不足；不充分；不胜任（in- 加在名词上）","example":"He felt a deep sense of inadequacy.","exampleCN":"他深深感到自己不够好。"},{"word":"adequacy","structure":"adequate + -acy","meaning":"the quality of being enough","meaningCN":"足够；充分；胜任（-acy 构成抽象名词）","example":"They questioned the adequacy of the safety checks.","exampleCN":"他们质疑安全检查是否足够。"},{"word":"adequately","structure":"adequate + -ly","meaning":"in a way that is enough","meaningCN":"充分地；足够地；恰当地（-ly 构成副词）","example":"The team was adequately trained.","exampleCN":"团队接受了足够的培训。"},{"word":"adequateness","structure":"adequate + -ness","meaning":"the state of being adequate","meaningCN":"足够；适当（-ness 构成名词，较罕用）","example":"The adequateness of the response was debated.","exampleCN":"这一回应是否足够，引发了争论。"},{"word":"inadequateness","structure":"in- (not) + adequateness","meaning":"the state of not being adequate","meaningCN":"不充分；不适当（in- 加在 -ness 名词上）","example":"The inadequateness of the plan became clear at once.","exampleCN":"这个计划的不充分之处立刻显现出来。"},{"word":"adequation","structure":"adequate + -ion","meaning":"the act of making equal; correspondence","meaningCN":"使相等；相符（-ion 构成名词，罕用，多见于哲学与神学）","example":"The old debate concerned the adequation of thought to things.","exampleCN":"那场古老的争论涉及思想与事物的相符。"},{"word":"equal","structure":"aequus ‘level’ → aequalis","meaning":"the same in amount, size, value or status","meaningCN":"相等的；平等的（同一 aequus 词根）","example":"The two sides deserve equal treatment.","exampleCN":"双方应得到平等的对待。"},{"word":"equate","structure":"aequus + -ate","meaning":"to treat two things as equal or equivalent","meaningCN":"把……等同；使相等（同一 aequus 词根 + -ate）","example":"We should not equate wealth with happiness.","exampleCN":"我们不应把财富等同于幸福。"}],"latinEntries":[{"word":"aequus","structure":"Latin adjective","meaning":"level, even, equal, just","meaningCN":"平的；齐的；相等的；公正的"},{"word":"aequare","structure":"Latin verb from aequus","meaning":"to make level or equal","meaningCN":"使齐平；使相等"},{"word":"adaequare","structure":"ad (to) + aequare (make level)","meaning":"to make equal to, level with","meaningCN":"使与……相等；使齐平（adequate 的直接拉丁来源）"},{"word":"aequalitas","structure":"aequalis (equal) + -itas","meaning":"equality, evenness","meaningCN":"相等；均等（英语 equality 的来源）"}]}},{"word":"adjacent","ipa_uk":"/əˈdʒeɪsənt/","ipa_us":"/əˈdʒeɪsənt/","definition_zh":"邻近的；毗连的；（时间上）紧接着的","definition_en":"next to or very near something, often sharing a border with it","core_image":"两样东西贴着边并排躺着，中间只隔一条线","scene":"酒店前台把房卡推过来说：Your room is adjacent to the lift, so you may hear it at night.","sceneCN":"这里 adjacent 是「紧挨着的、毗邻的」（第 1 个义项：空间上相邻）；句意：前台说你的房间紧挨着电梯，夜里可能会听到电梯声。可辨识物件：前台柜台、房卡、电梯门、走廊地毯。","pos":[{"tag":"adj.","zh":"邻近的；毗连的；紧接着的"}],"collocations":[{"phrase":"adjacent to","zh":"与……相邻；紧挨着"},{"phrase":"adjacent rooms","zh":"相邻的房间"},{"phrase":"immediately adjacent","zh":"紧邻的；直接毗连的"},{"phrase":"adjacent angles","zh":"邻角（几何中共享顶点和一条边）"},{"phrase":"adjacent areas","zh":"邻近地区"}],"forms":[{"label":"比较级（书面语偶见，adjacent 通常不作分级形容词）","form":"more adjacent"},{"label":"最高级（书面语偶见）","form":"most adjacent"}],"derivatives":[{"word":"adjacency","pos":"n.","zh":"毗邻；邻接；相邻关系"},{"word":"adjacently","pos":"adv.","zh":"相邻地；紧挨着地"},{"word":"nonadjacent","pos":"adj.","zh":"不相邻的；非邻接的"}],"senses":[{"no":"01","title":"Spatial neighbour: lying next to something","titleCN":"位置相邻：紧挨着某物","definition":"next to or very near something in physical space","definitionCN":"在物理空间上紧挨着或非常靠近某物","example":"Our office is adjacent to the city library.","exampleCN":"我们的办公室紧挨着市图书馆。","why":"The Latin core is ad- 'to' + jacere 'to lie': the thing is pictured as lying down right beside another. Because the image is purely positional, the basic sense needs no metaphor at all.","whyCN":"拉丁语核心是 ad-“朝向”加 jacere“躺”：把一物想象成紧贴着另一物躺下。因为画面纯粹是位置关系，最基本的意义完全不需要比喻。"},{"no":"02","title":"Sharing a border: adjoining land or buildings","titleCN":"共用边界：土地或建筑毗连","definition":"touching something along an edge, so that the two share a boundary","definitionCN":"沿边缘接触某物，因而两者共享一条边界","example":"The garden is adjacent to a narrow lane that runs behind the house.","exampleCN":"花园紧挨着一条从屋后穿过的小巷。","why":"If one thing lies beside another, their edges eventually meet. The image of 'lying beside' gains a line of contact, and adjacent moves from mere nearness to sharing a boundary.","whyCN":"一物长期躺在另一物旁边，两者的边缘终会相接。“躺在旁边”的画面多出一条接触线，adjacent 便从单纯“靠近”变成“共用边界”。"},{"no":"03","title":"The next room or seat in a row","titleCN":"同一排里挨着的房间或座位","definition":"used of rooms, seats or buildings that come one after another along the same corridor or street","definitionCN":"指沿同一条走廊或街道依次排列、彼此紧挨的房间、座位或建筑","example":"We booked two adjacent rooms so the children could stay close.","exampleCN":"我们订了两间相邻的房间，这样孩子们可以住得近些。","why":"Hotels and theatres arrange space in a line. An adjacent room is the one lying immediately beside yours in that line, so the word becomes the practical label for 'the room next door'.","whyCN":"旅馆和剧院把空间排成一条线。adjacent room 就是这条线上紧贴你那一间躺着的房间，于是这个词成了“隔壁那间”的实用标签。"},{"no":"04","title":"Neighbouring in a field of knowledge","titleCN":"学科或部门的相邻","definition":"close to something in an abstract order, such as a subject, department or category","definitionCN":"在抽象次序中靠近某物，如学科、部门或类别","example":"Molecular biology is adjacent to biochemistry, and the two departments share equipment.","exampleCN":"分子生物学与生物化学相邻，两个系共用设备。","why":"Knowledge is commonly pictured as a map with regions. Two disciplines sitting side by side on that map count as adjacent although nothing physical touches; the spatial image is simply moved onto ideas.","whyCN":"知识常被画成一张分区域的地图。两个学科在这张图上并排而坐，就算没有任何实物接触也算 adjacent；空间意象被整体搬到了观念上。"},{"no":"05","title":"Adjacent in time: the period right after","titleCN":"时间相邻：紧接着的时段","definition":"coming immediately before or after a period of time","definitionCN":"在时间上紧接在某段时期之前或之后","example":"The two adjacent decades show the same rise in city population.","exampleCN":"相邻的两个十年显示出同样的城市人口增长。","why":"Time is spoken of as a line or a stretch. Periods laid end to end on that line become neighbours, so the 'lying beside' relation is read along the time axis.","whyCN":"时间常被说成一条线或一段段。把时段在这条线上首尾相接，它们就成了邻居，“躺在旁边”的关系于是沿时间轴读出来。"},{"no":"06","title":"Adjacent angles: geometry's shared side","titleCN":"邻角：几何中共享一条边","definition":"of two angles, having the same vertex and one shared side","definitionCN":"指两个角有共同顶点和一条公共边","example":"In the diagram, angle AOB and angle BOC are adjacent angles.","exampleCN":"图中角 AOB 与角 BOC 是邻角。","why":"Geometry names this relation at its purest: two figures lie side by side and share the line between them. The literal 'bordering' fits exactly, which is why the term has stayed in textbooks.","whyCN":"几何学最纯粹地命名了这种关系：两个图形并排躺着，共用中间那条线。字面的“接边”正好吻合，所以这个术语一直留在教科书里。"},{"no":"07","title":"Adjacent nodes in a network","titleCN":"网络中相邻的节点","definition":"of vertices or nodes in a graph, joined directly by a single edge","definitionCN":"指图中的顶点或节点由一条边直接相连","example":"In this graph, node A is adjacent to node B but not to node D.","exampleCN":"在这个图里，节点 A 与节点 B 相邻，但与节点 D 不相邻。","why":"A network is a drawing of points joined by lines. Two points joined by one line sit at the ends of that line, beside each other on the page, so graph theory borrows the geometry of neighbouring plots.","whyCN":"网络是用线连接点的图画。被一条线连起的两个点就在这条线两端，在纸面上彼此相邻，于是图论借用了邻地的几何关系。"},{"no":"08","title":"Adjacent notes and sounds","titleCN":"相邻音：音乐与语音中的邻近","definition":"of notes or speech sounds, next to each other on a scale or in the order of articulation","definitionCN":"指音符或语音在音阶上或发音部位次序上彼此相邻","example":"The melody moves by adjacent notes instead of jumping across an octave.","exampleCN":"这段旋律以相邻音级进，而不是跨越八度大跳。","why":"A scale is an ordered row of pitches, each note lying beside the next in that row. Adjacent notes therefore means the smallest step along the row, not nearness in physical space.","whyCN":"音阶是一排排好的音高，每个音在这排里紧挨着下一个。adjacent notes 因此指沿这排音阶迈出的最小一步，而不是物理空间的接近。"},{"no":"09","title":"The adjacent possible: the next reachable step","titleCN":"相邻可能：下一步可及的范围","definition":"in the phrase the adjacent possible, the set of new things that can be reached from the present state by one small step","definitionCN":"用于 the adjacent possible，指从当前状态再迈一小步就能达到的那组新事物","example":"The invention was not random; it sat in the adjacent possible of that decade's technology.","exampleCN":"这项发明并非偶然，它落在那十年技术条件的“相邻可能”之中。","why":"Here adjacency becomes a measure of distance from what already exists. Anything one step away is adjacent, so the phrase names the zone of ideas close enough to be built now.","whyCN":"这里的“相邻”成了衡量与既有事物距离的尺度。隔一步就能到达的就算 adjacent，所以这个短语指“近得现在就能造出来”的那片想法区域。"},{"no":"10","title":"The Latin parts inside the word","titleCN":"词内的拉丁结构","definition":"the word is built as ad- 'to' + jac- 'lie' + -ent, so its parts literally spell 'lying near'","definitionCN":"该词由 ad-“朝向”+ jac-“躺”+ -ent 构成，字面即“朝……躺着”","example":"Reading adjacent as ad- + jac- + -ent explains both its spelling and its meaning.","exampleCN":"把 adjacent 拆成 ad- + jac- + -ent，既能解释拼写，也能解释词义。","why":"The prefix aims the action, the root supplies the posture, and the suffix turns it into an adjective. Reading the parts is reading the picture that produced every sense above.","whyCN":"前缀指出动作方向，词根提供姿态，后缀使它成为形容词。读这些部件，就是在读产生上面所有义项的那个画面。"}],"etymology":{"intro":{"en":"Adjacent is a Latin present participle that entered English through learned borrowing, not through everyday French speech. Its parts are unusually transparent: ad- 'to' and jacere 'to lie, to be thrown down'.","cn":"adjacent 是拉丁语现在分词，经由学术借入英语，而不是从日常法语口语传入。它的部件异常透明：ad-“朝向”与 jacere“躺、被投下”。"},"items":[{"era":"EARLY 15C.","en":"The word is first recorded in English in the early 15th century as an adjective meaning 'contiguous, bordering, neighbouring'. That is still its central meaning today.","cn":"该词在 15 世纪早期首次见于英语，作形容词，意为“接壤的、毗邻的、邻近的”。这仍是今天的主要含义。"},{"era":"LATIN","en":"From Latin adjacens (genitive adjacentem), present participle of adjacere 'to lie near to', built on ad- 'to' + jacere 'to throw, lay'. The underlying picture is something thrown down beside another thing.","cn":"来自拉丁语 adjacens（属格 adjacentem），是 adjacere“躺在……旁边”的现在分词，由 ad-“朝向”+ jacere“投、放置”构成。底层画面是把一物投放在另一物旁边。"},{"era":"LATIN jacere FAMILY","en":"The root jacere 'to throw, lay' also lies inside eject, inject, project, reject, subject, object and jet. All of them keep some idea of throwing or placing.","cn":"词根 jacere“投、放置”也藏在 eject、inject、project、reject、subject、object、jet 之中，它们都保留着“投掷或放置”的意味。"},{"era":"PROTO-INDO-EUROPEAN","en":"jacere is usually traced to a PIE root *ye- 'to throw, impel'. The exact reconstructed shape and the set of words assigned to it differ between dictionaries, so this step is source uncertain.","cn":"jacere 通常被追溯到原始印欧语词根 *ye-“投掷、推动”。这一重构形式的确切写法和归属词集在各部辞书中并不一致，因此这一段属「来源不确定」。"},{"era":"16C–17C TECHNICAL USE","en":"The word is taken into technical description: geometry speaks of adjacent angles, anatomy of adjacent organs. The exact date when each technical label was fixed is source uncertain, but the narrowing of the spatial sense is certain.","cn":"这个词进入技术描述：几何学说 adjacent angles（邻角），解剖学说 adjacent organs（相邻器官）。每个术语固定下来的确切年代「来源不确定」，但空间义被收窄这一过程是确定的。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the spatial core and extends it to ordered systems — consecutive years, graph nodes, neighbouring notes — and to the phrase the adjacent possible in recent science writing.","cn":"现代英语保留空间核心，并把它扩展到有序系统——连续年份、图节点、相邻音符——以及近年科普写作中的 the adjacent possible。"}]},"similar":{"note":{"en":"The first group looks or sounds like adjacent; the second group shares part of its meaning. Keeping them apart prevents a spelling memory from being mistaken for a definition.","cn":"第一组与 adjacent 形近或音近，第二组与它部分同义。把两组分开，避免把拼写记忆误当成释义。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adjoin","ipa":"/əˈdʒɔɪn/","tag":"same ad- prefix","definition":"to be next to and joined with something. It is a verb, while adjacent is an adjective.","definitionCN":"与……毗连、紧接。它是动词，而 adjacent 是形容词。"},{"word":"adjust","ipa":"/əˈdʒʌst/","tag":"same ad- prefix","definition":"to change something slightly so that it fits or works. It shares the prefix but comes from Latin juxta 'near', a different root.","definitionCN":"调整；调节。它共享 ad- 前缀，但词根是拉丁语 juxta“靠近”，与 jacere 不同。"},{"word":"adjudicate","ipa":"/əˈdʒuːdɪkeɪt/","tag":"same ad- prefix","definition":"to act as a judge and decide a dispute. The root is judex 'judge', not jacere.","definitionCN":"裁决；审判。词根是 judex“法官”，不是 jacere。"},{"word":"adherent","ipa":"/ədˈhɪərənt/","tag":"same -ent ending","definition":"someone who supports a party or idea; also an adjective meaning sticking to a surface. It ends like adjacent but its root is haerere 'to stick'.","definitionCN":"拥护者；也可作形容词指“附着的”。词尾与 adjacent 相同，但词根是 haerere“粘附”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"neighbouring","ipa":"/ˈneɪbərɪŋ/","tag":"general","definition":"near or next to a place; the everyday word for what lies around something.","definitionCN":"邻近的；周边的。指某物周围之地的日常用词。"},{"word":"adjoining","ipa":"/əˈdʒɔɪnɪŋ/","tag":"touching","definition":"next to and joined with something, often sharing a wall or a border. It stresses actual contact more than adjacent does.","definitionCN":"毗连的；相连的，常指共用一堵墙或一条边界。它比 adjacent 更强调实际接触。"},{"word":"contiguous","ipa":"/kənˈtɪɡjuəs/","tag":"formal","definition":"sharing a border or touching along a surface; used especially of areas of land.","definitionCN":"接壤的；相连的，尤用于地块。属正式用语。"},{"word":"abutting","ipa":"/əˈbʌtɪŋ/","tag":"technical","definition":"touching or bordering on something, used of property and structures.","definitionCN":"紧靠的；毗连的，多用于房产与建筑结构。"},{"word":"proximate","ipa":"/ˈprɒksɪmət/","tag":"formal","definition":"very near in space or time; also used for a cause that is direct.","definitionCN":"空间或时间上很近的；也可指直接原因。属正式用语。"},{"word":"nearby","ipa":"/ˌnɪəˈbaɪ/","tag":"general","definition":"close to the place mentioned but not necessarily touching it. It is looser than adjacent.","definitionCN":"附近的；不远处的，不一定要接触。它比 adjacent 宽松。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal links use the real Latin parts ad- + jacere and the genuine derivative family adjacency, adjacently, nonadjacent.","cn":"正常联想只用真实的拉丁部件 ad- + jacere，以及真实的派生词 adjacency、adjacently、nonadjacent。"},"normal":[{"en":"ad- means 'to, toward'. In adjacent, the prefix aims the action at the neighbour.","cn":"ad- 意为“朝向”。在 adjacent 里，前缀把动作指向邻居。"},{"en":"jacere means 'to lie, to be thrown down'. A thing that lies beside you is adjacent; the same root sits inside adjective, project and reject.","cn":"jacere 意为“躺、被投下”。躺在你旁边的东西就是 adjacent；同一词根也在 adjective、project、reject 里。"},{"en":"-ent is the adjective ending: adjacent, different and patient all describe a state.","cn":"-ent 是形容词词尾：adjacent、different、patient 都在描述一种状态。"},{"en":"The fixed pattern is adjacent to, not 'adjacent with'. The preposition repeats the ad- 'toward'.","cn":"固定搭配是 adjacent to，而不是 adjacent with。介词 to 正好重复了 ad- 的“朝向”。"},{"en":"adjacency is the noun and adjacently the adverb; -cy and -ly mark the change of word class.","cn":"adjacency 是名词，adjacently 是副词；-cy 与 -ly 标记了词性的变化。"}],"abstract":[{"en":"Picture two floor tiles: they do not overlap, but their edges touch. That is adjacency in its simplest form.","cn":"想象两块地砖：它们不重叠，但边缘相接。这就是最简形态的“相邻”。"},{"en":"Move the same picture onto a map of subjects, a timeline or a graph, and touching edges become shared topics, consecutive years or a single link.","cn":"把同一幅画移到学科地图、时间轴或图上，相接的边缘就变成共享主题、连续年份或一条连线。"},{"en":"Adjacency measures one step: whatever can be reached without crossing a gap is adjacent.","cn":"相邻是在量“一步”：不用跨过空隙就能到达的，就是 adjacent。"}]},"examples":[{"en":"The hotel is adjacent to the railway station, so we walked there in two minutes.","cn":"酒店紧挨着火车站，所以我们两分钟就走到了。"},{"en":"Our seats were adjacent, which made the long flight easier to bear.","cn":"我们的座位相邻，这让漫长的飞行好受了一些。"},{"en":"In this graph, each node is adjacent to exactly two others.","cn":"在这个图中，每个节点恰好与另外两个节点相邻。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿这森特”——阿这（个人）在森（林）里特（别）挨着别人站 → adjacent 邻近的","word":"adjacent"},"root":"源自拉丁语 adjacere“躺在旁边”，由 ad-“朝向”+ jacere“躺、放置”构成，核心是“紧贴着躺下、共用一条边”。","sensesIntro":{"en":"Ten senses of adjacent. Each one keeps the same geometry: something lies beside something else, and the question is only how close the two edges come.","cn":"adjacent 的十个义项都保留同一个几何关系：一物躺在另一物旁边，区别只在于两条边靠得有多近。"},"semanticMap":{"core":{"en":"CORE IMAGE: one thing lying down at the side of another.","cn":"核心意象：一物躺在另一物旁边。"},"chain":["TOWARD","LIE","LIE BESIDE","BORDER CONTACT","NEIGHBOURHOOD","ONE STEP AWAY"],"branches":[{"senses":"S1 · S2 · S10","en":"SPACE: lying near becomes touching a border; the Latin parts restate the same picture.","cn":"空间：从躺在附近到共用边界；拉丁部件只是把这个画面再说一遍。"},{"senses":"S3","en":"BUILDINGS: the next room along the same corridor.","cn":"建筑：同一条走廊上紧挨着的下一间房。"},{"senses":"S4","en":"IDEAS: neighbouring disciplines on the map of knowledge.","cn":"观念：知识地图上相邻的学科。"},{"senses":"S5 · S6 · S7","en":"ORDERED SETS: adjacency inside a system — consecutive periods, a shared angle side, a single graph edge.","cn":"有序系统：系统内部的相邻——连续时段、共享的角边、图上的一条边。"},{"senses":"S8 · S9","en":"SOUND AND POSSIBILITY: the next note on the scale; the next idea that can be reached.","cn":"声音与可能性：音阶上的下一个音；下一个够得着的想法。"}]},"affixes":{"intro":{"en":"adjacent is built from a prefix, a root and an adjective suffix. The same jac- root also appears in several rare learned compounds, which makes the word family easy to read.","cn":"adjacent 由前缀、词根和形容词后缀构成。同一个 jac- 词根还出现在若干罕用的学术复合词里，使这个词族很容易读懂。"},"latinIntro":{"en":"The Latin family centres on jacere 'to throw, lay' and its compound adjacere 'to lie near'. Latin also formed subjacere 'to lie under', the source of the rare English subjacent.","cn":"这一拉丁词族以 jacere“投、放置”及其复合词 adjacere“躺在附近”为中心。拉丁语还构成 subjacere“躺在下面”，即罕用英语词 subjacent 的来源。"},"items":[{"word":"adjacent","structure":"ad- (to, toward) + jac- (lie) + -ent (adjective suffix)","meaning":"lying next to something","meaningCN":"朝……躺着的，即“毗邻的”（ad- 表朝向，jac- 表躺，-ent 为形容词后缀）","example":"The two rooms are adjacent.","exampleCN":"这两个房间相邻。"},{"word":"adjacency","structure":"adjacent + -cy (state, quality)","meaning":"the state of being next to something","meaningCN":"毗邻；邻接状态（-cy 构成抽象名词）","example":"The adjacency of the two buildings makes them easy to connect.","exampleCN":"这两栋楼相邻，连接起来很方便。"},{"word":"adjacently","structure":"adjacent + -ly (in the manner of)","meaning":"in a position next to something","meaningCN":"相邻地；紧挨着地（-ly 构成副词）","example":"The two plots are laid out adjacently.","exampleCN":"这两块地被相邻地划分出来。"},{"word":"nonadjacent","structure":"non- (not) + adjacent","meaning":"not next to each other; separated by something else","meaningCN":"不相邻的；非邻接的（non- 表否定）","example":"Nonadjacent seats in the same row are still in one booking.","exampleCN":"同一排中不相邻的座位仍属同一次订票。"},{"word":"adjoin","structure":"ad- (to) + join (join)","meaning":"to be next to and joined with something","meaningCN":"毗连；紧接（ad- 表朝向，join 表连接）","example":"Their land adjoins ours at the river.","exampleCN":"他们的土地在河边与我们的土地毗连。"},{"word":"circumjacent","structure":"circum- (around) + jac- (lie) + -ent","meaning":"lying around; surrounding (rare, learned)","meaningCN":"环绕的；四周的（罕用学术词；circum- 表环绕）","example":"The circumjacent hills shelter the village from wind.","exampleCN":"环绕的丘陵为村庄挡风。"},{"word":"interjacent","structure":"inter- (between) + jac- (lie) + -ent","meaning":"lying between two things (rare)","meaningCN":"位于中间的；夹在两者之间的（罕用；inter- 表在……之间）","example":"An interjacent strip of grass separates the two paths.","exampleCN":"一条夹在中间的草带把两条小路隔开。"},{"word":"subjacent","structure":"sub- (under) + jac- (lie) + -ent","meaning":"lying beneath or below something","meaningCN":"下伏的；位于下方的（sub- 表在……之下）","example":"The subjacent rock layer holds most of the groundwater.","exampleCN":"下伏的岩层储存了大部分地下水。"},{"word":"superjacent","structure":"super- (above) + jac- (lie) + -ent","meaning":"lying above or over something","meaningCN":"上覆的；位于上方的（super- 表在……之上）","example":"The superjacent soil is darker and richer in humus.","exampleCN":"上覆土壤颜色更深，腐殖质更丰富。"}],"latinEntries":[{"word":"adjacere","structure":"ad- (to) + jacere (lie, be thrown)","meaning":"to lie near to, be adjacent","meaningCN":"躺在附近；毗邻（ad-“朝向”+ jacere“躺”）"},{"word":"jacere","structure":"base verb","meaning":"to throw, cast, lay down","meaningCN":"投掷；抛下；放置（英语中众多 -ject 词的词根）"},{"word":"subjacere","structure":"sub- (under) + jacere (lie)","meaning":"to lie under or beneath","meaningCN":"躺在下面；位于下方（sub-“在下”+ jacere“躺”）"}]}},{"word":"adjust","ipa_uk":"/əˈdʒʌst/","ipa_us":"/əˈdʒʌst/","definition_zh":"调整；调节；校准；适应","definition_en":"to change something slightly so that it fits, matches or works correctly","core_image":"把两样东西推到同一条线上，使它们对齐","scene":"摄影师在暗房里转动旋钮，说：Let me adjust the focus before I make the print.","sceneCN":"这里 adjust 是「校准、调节（设备）」（第 1 个义项：把器械调到标准位置）；句意：摄影师说印相之前让我先把焦距调准。可辨识物件：放大机、调焦旋钮、相纸、暗房红灯。","pos":[{"tag":"vt.","zh":"调整；调节；校准；整理"},{"tag":"vi.","zh":"适应（常与 to 连用）"}],"collocations":[{"phrase":"adjust to","zh":"适应；习惯于"},{"phrase":"adjust the volume","zh":"调节音量"},{"phrase":"adjust for inflation","zh":"按通货膨胀进行调整"},{"phrase":"adjust oneself to","zh":"使自己适应"},{"phrase":"adjust a claim","zh":"核定保险理赔"}],"forms":[{"label":"三单（he/she/it）","form":"adjusts"},{"label":"过去式（已经发生）","form":"adjusted"},{"label":"过去分词（完成／被动）","form":"adjusted"},{"label":"现在分词（进行体）","form":"adjusting"}],"derivatives":[{"word":"adjustment","pos":"n.","zh":"调整；调节；（心理）适应"},{"word":"adjustable","pos":"adj.","zh":"可调节的"},{"word":"adjuster","pos":"n.","zh":"调节器；（保险）理赔员"},{"word":"readjust","pos":"v.","zh":"重新调整；再适应"},{"word":"misadjust","pos":"v.","zh":"错误地调节；调节不当"},{"word":"adjusted","pos":"adj.","zh":"调整过的（如 adjusted income 调整后收入）"}],"senses":[{"no":"01","title":"Calibrate: set a device to a standard","titleCN":"校准：把器械调到标准","definition":"to set a device, instrument or machine so that it works correctly or matches a standard","definitionCN":"把装置、仪器或机器调到正确工作状态或与某一标准相符","example":"She adjusted the microscope before looking at the slide.","exampleCN":"她先调好显微镜，然后才看玻片。","why":"The core image is bringing something into line. An instrument is adjusted when its parts are lined up with the true measure, so technical alignment is the most literal surviving sense.","whyCN":"核心画面是“把某物推到线上”。仪器被 adjust，就是它的部件与真实刻度对齐，所以技术性校准是最贴近字面的现存义项。"},{"no":"02","title":"Alter slightly so that it fits","titleCN":"调整：稍作改动以合用途","definition":"to change something a little so that it suits a purpose, a space or a person","definitionCN":"稍微改动某物，使它适合某一用途、空间或人","example":"We adjusted the table height to fit the child.","exampleCN":"我们把桌子调低，以适合那个孩子。","why":"Once a thing can be lined up with a measure, it can also be lined up with a need. The reference point shifts from 'correct' to 'suitable', and the change may be only a small one.","whyCN":"一旦某物能与刻度对齐，它也能与需求对齐。参照点从“正确”转为“合宜”，改动往往只需很小。"},{"no":"03","title":"Adapt oneself to a new situation","titleCN":"适应：使自己融入新环境","definition":"to change one's habits or behaviour in order to fit a new place, job or set of conditions","definitionCN":"改变习惯或行为，以适应新地方、新工作或新条件","example":"It took him a month to adjust to working nights.","exampleCN":"他花了一个月才适应上夜班。","why":"The reflexive pattern turns the action inward: the person, not an object, becomes the thing brought into line with the surroundings. From 'adjust the machine' comes 'adjust oneself'.","whyCN":"反身结构把动作转向自身：被拉去与环境对齐的不再是物件，而是人自己。由“adjust the machine”就长出了“adjust oneself”。"},{"no":"04","title":"Tidy one's clothing or hair","titleCN":"整理：扶正衣着或头发","definition":"to move a piece of clothing or hair slightly so that it sits correctly","definitionCN":"略微挪动衣物或头发，使其回到端正位置","example":"He adjusted his tie in the mirror before the interview.","exampleCN":"面试前，他对着镜子整理了一下领带。","why":"A tie out of line is straightened by a small movement. The original sense of setting things in order survives in this everyday gesture, with no instrument involved at all.","whyCN":"歪了的领带靠一个小动作扶正。“把事物摆整齐”的原义就活在这个日常动作里，完全不需要仪器。"},{"no":"05","title":"Revise figures: prices, wages, accounts","titleCN":"调整数字：价格、工资、账目","definition":"to change a number, price or account so that it matches new conditions or the true amount","definitionCN":"改动数字、价格或账目，使其符合新情况或真实数额","example":"The store adjusted its prices after the new tax was introduced.","exampleCN":"新税开征后，这家店调整了价格。","why":"Numbers can be 'brought into line' with reality just as objects can. Adjusting a price means aligning the figure with cost, tax or market value.","whyCN":"数字也能像实物一样被“推到与事实同一条线上”。调整价格就是让数字与成本、税率或市值对齐。"},{"no":"06","title":"Settle a matter: arrange or resolve","titleCN":"了结：解决分歧或事务","definition":"to settle or arrange a disagreement, a debt or an affair (formal or older use)","definitionCN":"解决或安排分歧、债务或事务（正式或较旧的用法）","example":"The two families adjusted their differences without going to court.","exampleCN":"两家人没有上法庭就解决了分歧。","why":"The oldest English sense is 'settle, arrange'. Bringing conflicting claims onto one line is a social version of alignment, which is why the word can still mean 'resolve'.","whyCN":"英语最早的意思是“安排、了结”。把相互冲突的诉求排到同一条线上，是对齐的社会版本，所以这个词至今仍可表示“解决”。"},{"no":"07","title":"Assess an insurance claim","titleCN":"核定保险理赔","definition":"to examine a loss or damage and decide how much compensation should be paid","definitionCN":"审查损失或损坏，确定应赔付多少","example":"The insurer sent a man to adjust the claim after the flood.","exampleCN":"洪水过后，保险公司派人来核定理赔。","why":"A claim is a set of figures that must be made to match the real loss. The person who does this is an adjuster, and the verb keeps the 'make it match' idea.","whyCN":"理赔是一组必须与真实损失对齐的数字。做这件事的人叫 adjuster，动词保留了“使之相符”的意思。"},{"no":"08","title":"Correct for a factor: statistics","titleCN":"剔除因素影响：统计中的校正","definition":"to allow for the effect of a factor when calculating or comparing results","definitionCN":"在计算或比较结果时把某一因素的影响考虑进去并加以消除","example":"The researchers adjusted the results for age and income.","exampleCN":"研究人员对结果作了年龄和收入的校正。","why":"Here the line is a fair comparison. Before comparing two groups you remove the tilt caused by age or income, which aligns the data onto a level baseline.","whyCN":"这里的线是公平比较。比较两组之前，先把年龄或收入造成的倾斜挪走，就是把数据对齐到同一条基准线上。"},{"no":"09","title":"Eyes adjust to light","titleCN":"眼睛适应光线","definition":"of the eyes or the body, to become used to a change of light, temperature or altitude","definitionCN":"指眼睛或身体逐渐习惯光线、温度或海拔的变化","example":"It takes a few minutes for your eyes to adjust to the dark.","exampleCN":"眼睛需要几分钟才能适应黑暗。","why":"A living body also seeks alignment with its surroundings. The pupil and the retina shift until they match the new light level, so English says the eyes adjust.","whyCN":"活着的身体也在寻求与环境的对齐。瞳孔与视网膜会变动到与新光照水平相配，英语把这说成眼睛在 adjust。"},{"no":"10","title":"Emotional adjustment: fitting the mind to reality","titleCN":"心理调适：让心态与现实相符","definition":"to change one's attitude or feelings gradually so as to accept a new situation","definitionCN":"逐渐改变态度或情绪，以接受新的处境","example":"Children often need time to adjust emotionally after a move.","exampleCN":"搬家之后，孩子往往需要时间作心理上的调适。","why":"The same alignment happens inside a person: feelings that no longer fit the facts are slowly brought into line with them. This is the psychological branch of one physical image.","whyCN":"同样的对齐也发生在人心里：与事实不再相符的情绪被慢慢拉回同一条线上。这是同一物理画面在心理层面的分支。"}],"etymology":{"intro":{"en":"Adjust reached English through Old French, but its root is Latin juxta 'near, beside', not jacere. That is why adjust and adjacent look alike yet belong to different Latin families.","cn":"adjust 经由古法语进入英语，但词根是拉丁语 juxta“靠近、在旁边”，而不是 jacere。这就是 adjust 与 adjacent 形似却属于不同拉丁词族的原因。"},"items":[{"era":"LATE 14C","en":"English recorded ajusten in the late 14c. meaning 'to correct, remedy'. The idea of putting something in order is present from the start.","cn":"英语在 14 世纪后期记录 ajusten，意为“纠正、补救”。从最初起就带有“把事物理出头绪”的意念。"},{"era":"OLD FRENCH","en":"It came from Old French ajuster, ajoster 'add; assemble; calibrate, gauge, regulate', the direct source of the English word.","cn":"它来自古法语 ajuster、ajoster“添加；集合；校准、测量、调节”，这是英语词的直接来源。"},{"era":"LATE LATIN","en":"The Old French verb goes back to Late Latin adiuxtare 'to bring near', from ad- 'to' plus juxta 'next, close by'. Juxta is commonly connected with the PIE root *yeug- 'to join'.","cn":"古法语动词可上溯到晚期拉丁语 adiuxtare“使靠近”，由 ad-“向”加 juxta“近旁”构成。juxta 通常被联系到原始印欧语 *yeug-“连接”。"},{"era":"16C–17C","en":"French later corrected the form to adjuster, and English reborrowed it by c. 1600 with the sense 'arrange, settle, compose'. The sense 'make conform to a standard' is from the 1660s.","cn":"法语后来把形式修正为 adjuster，英语约 1600 年重新借入，意为“安排、整理、处理”。 “使符合某一标准”一义来自 17 世纪 60 年代。"},{"era":"1755–1924","en":"The insurance sense is from 1755. The phrase adjust to 'get used to' is attested by 1924, giving the modern intransitive usage.","cn":"保险义来自 1755 年。短语 adjust to“习惯于”记录于 1924 年，由此形成现代的不及物用法。"},{"era":"MODERN ENGLISH","en":"Modern English keeps adjustment for a change and adjustable for something that can be changed. The core remains bringing two things into line.","cn":"现代英语用 adjustment 指调整，用 adjustable 指可调节的。核心仍是把两样东西推到同一条线上。"}]},"similar":{"note":{"en":"Adjust has two common traps: words that share its ad- prefix but not its root, and words that mean 'change' but lack the idea of fitting to a line.","cn":"adjust 有两个常见陷阱：共享 ad- 前缀但词根不同的词，以及表示“改变”却没有“对齐到一条线”这一核心的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adjacent","ipa":"/əˈdʒeɪsənt/","tag":"same ad- prefix","definition":"next to something; an adjective, not a verb. Its root is jacere 'to lie', not juxta 'near'.","definitionCN":"毗邻的；是形容词而非动词。词根是 jacere“躺”，不是 juxta“靠近”。"},{"word":"adjustment","ipa":"/əˈdʒʌstmənt/","tag":"derivative","definition":"the noun from adjust: a small change made to fit or to correct something.","definitionCN":"adjust 的名词派生词：为适合或纠正而作的小改动。"},{"word":"adjutant","ipa":"/ˈædʒətənt/","tag":"near spelling","definition":"an officer who assists a commander with administrative work. It looks close to adjust but its root is adjutare 'to help'.","definitionCN":"副官；协助指挥官处理行政事务的军官。拼写与 adjust 接近，但词根是 adjutare“帮助”。"},{"word":"adjuster","ipa":"/əˈdʒʌstə/","tag":"derivative","definition":"a person who assesses insurance claims, or a device that adjusts something.","definitionCN":"理赔员；调节器。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adapt","ipa":"/əˈdæpt/","tag":"fit to a purpose","definition":"to change something so that it suits a new use or situation. It stresses a purpose more than a standard does.","definitionCN":"使适应；改编。它比 adjust 更强调“为了某个用途”。"},{"word":"modify","ipa":"/ˈmɒdɪfaɪ/","tag":"change","definition":"to change something, often in a planned or partial way. It does not require the result to be aligned with anything.","definitionCN":"修改；改动，常指有计划的局部改变。它不要求结果与某物对齐。"},{"word":"tune","ipa":"/tjuːn/","tag":"technical","definition":"to adjust an instrument or engine so that it works at its best. It is narrower and more mechanical than adjust.","definitionCN":"调音；调试，使乐器或发动机处于最佳状态。它比 adjust 更窄、更机械。"},{"word":"calibrate","ipa":"/ˈkælɪbreɪt/","tag":"precise setting","definition":"to mark or adjust an instrument against a known standard. It is the most technical word in this group.","definitionCN":"校准；标定，按已知标准调整仪器。它是这组里最技术化的词。"},{"word":"settle","ipa":"/ˈsetl/","tag":"resolve","definition":"to end a disagreement or arrange affairs finally. It matches the older sense of adjust.","definitionCN":"解决；了结，最终安排好事务。它对应 adjust 较旧的那个义项。"},{"word":"acclimate","ipa":"/ˈækləmeɪt/","tag":"become used to","definition":"to become used to a new climate or conditions; mainly used of bodies and plants.","definitionCN":"使适应新气候或新条件，主要用于身体和植物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal links use the real Latin root juxta 'near' and the genuine family adjustment, adjustable, adjuster, readjust.","cn":"正常联想只用真实的拉丁词根 juxta“靠近”，以及真实的词族 adjustment、adjustable、adjuster、readjust。"},"normal":[{"en":"adjust comes from ad- 'to' + juxta 'near': to adjust is to bring something up close to the line it should follow.","cn":"adjust 来自 ad-“朝向”+ juxta“靠近”：adjust 就是把某物推到它该遵循的那条线旁边。"},{"en":"juxta also gives juxtapose, which literally means 'place side by side'. Both words are about arranging things next to each other.","cn":"juxta 还给出 juxtapose，字面就是“并排摆放”。两个词都关于把事物安排在一起。"},{"en":"adjust the volume, adjust the seat, adjust the mirror: the object is always something that can be moved into a better position.","cn":"adjust the volume、adjust the seat、adjust the mirror：宾语总是能被移到更好位置的东西。"},{"en":"-ment makes the noun adjustment, -able makes adjustable, -er makes adjuster. The suffixes mark the word class, not a new meaning.","cn":"-ment 构成名词 adjustment，-able 构成 adjustable，-er 构成 adjuster。后缀标记词性，不增加新词义。"},{"en":"adjust to is intransitive when it means 'become used to': you adjust to a city, not 'adjust a city'.","cn":"表示“适应”时 adjust to 是不及物的：你 adjust to a city，而不是 adjust a city。"}],"abstract":[{"en":"Think of a ruler laid on a table: anything you slide until its edge matches the ruler is being adjusted.","cn":"想象一把尺子放在桌上：任何被你滑动到边缘与尺子对齐的东西，都在被 adjust。"},{"en":"Replace the ruler with a need, a budget, a new country or a set of data; the action is the same, only the standard changes.","cn":"把尺子换成一个需求、一份预算、一个新国家或一组数据；动作没变，只是标准换了。"},{"en":"Adjustment is therefore not random change: it is change with a reference point.","cn":"所以调整不是随便的改变，而是有参照点的改变。"}]},"examples":[{"en":"Could you adjust the air conditioning? It is freezing in here.","cn":"你能调一下空调吗？这里冷得要命。"},{"en":"New employees usually need a few weeks to adjust to the pace of the office.","cn":"新员工通常需要几周时间适应办公室的节奏。"},{"en":"The figures were adjusted for inflation before the two years were compared.","cn":"在比较这两年之前，数据已按通货膨胀作了调整。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿贾斯特”——阿贾（把椅子）特（地）摆正 → adjust 调整、校准","word":"adjust"},"root":"源自拉丁语 juxta“靠近、在旁边”，经俗拉丁语 *adjuxtare“使靠近”与古法语 ajouster 进入英语，核心是“把东西推到该在的那条线上”。","sensesIntro":{"en":"Ten senses of adjust. All of them perform one operation: move something until it lines up with a reference point, whether that point is a standard, a need, a fact or a new environment.","cn":"adjust 的十个义项都在做同一个动作：把某物移动，直到它与某个参照点对齐——这个参照点可以是标准、需求、事实或新环境。"},"semanticMap":{"core":{"en":"CORE IMAGE: sliding something until its edge meets the line.","cn":"核心意象：把某物滑动到它的边缘与那条线贴合。"},"chain":["TOWARD","NEAR","BRING NEAR","ALIGN WITH A STANDARD","ALIGN WITH A NEED","SETTLE INTO PLACE"],"branches":[{"senses":"S1 · S2","en":"OBJECT AND MEASURE: a device is aligned with a standard; an object is aligned with a purpose or a space.","cn":"物件与尺度：器械与标准对齐；物件与用途或空间对齐。"},{"senses":"S3 · S9 · S10","en":"THE SELF: a person, a pair of eyes or a set of feelings is brought into line with a new environment.","cn":"自身：人、眼睛或情绪被拉去与新环境对齐。"},{"senses":"S4","en":"APPEARANCE: clothing and hair are moved back into their proper position.","cn":"外表：衣物和头发被移回端正位置。"},{"senses":"S5 · S8","en":"NUMBERS AND DATA: figures are made to match tax, cost, inflation or a fair baseline.","cn":"数字与数据：让数字与税率、成本、通胀或公平基准相符。"},{"senses":"S6 · S7","en":"SETTLEMENT: conflicting claims or an insurance loss are arranged until the accounts match.","cn":"了结：把冲突的诉求或保险损失安排到账目相符为止。"}]},"affixes":{"intro":{"en":"adjust carries the Latin prefix ad- and the root juxta 'near'. Its English derivatives are built with ordinary suffixes, so the word family is easy to predict.","cn":"adjust 带有拉丁前缀 ad- 和词根 juxta“靠近”。它的英语派生词都用普通后缀构成，词族容易推断。"},"latinIntro":{"en":"The Latin base is juxta 'near, beside', related to jungere 'to join'. English borrowed it directly in juxtapose and through French in adjust and joust.","cn":"拉丁语基础是 juxta“靠近、在旁边”，与 jungere“连接”相关。英语在 juxtapose 中直接借用它，又经法语在 adjust、joust 中借用。"},"items":[{"word":"adjust","structure":"ad- (to) + just (from Latin juxta, near)","meaning":"to bring something near a line or standard; to set right","meaningCN":"把某物带到线或标准旁边；调正（ad- 表朝向，just 源自 juxta“靠近”）","example":"Please adjust the seat before you drive.","exampleCN":"开车前请把座椅调好。"},{"word":"adjustment","structure":"adjust + -ment (result or action noun)","meaning":"a small change made so that something fits or works","meaningCN":"调整；调节（-ment 构成表示行为或结果的名词）","example":"A small adjustment to the plan saved us a day.","exampleCN":"对计划作了一点调整，就为我们省下一天。"},{"word":"adjustable","structure":"adjust + -able (can be ...ed)","meaning":"able to be changed in position or size","meaningCN":"可调节的（-able 表“能被……的”）","example":"The chair has an adjustable back.","exampleCN":"这把椅子的靠背可以调节。"},{"word":"adjuster","structure":"adjust + -er (person or thing that does)","meaning":"a device that adjusts, or a person who assesses claims","meaningCN":"调节器；理赔员（-er 表做动作的人或物）","example":"The loss adjuster visited the flooded house.","exampleCN":"损失理赔员查看了被淹的房子。"},{"word":"readjust","structure":"re- (again) + adjust","meaning":"to adjust again after a change","meaningCN":"重新调整；再适应（re- 表再次）","example":"She readjusted her schedule after the flight was delayed.","exampleCN":"航班延误后，她重新调整了日程。"},{"word":"misadjust","structure":"mis- (wrongly) + adjust","meaning":"to adjust something wrongly","meaningCN":"调节不当；错误地调整（mis- 表错误）","example":"A misadjusted brake can be dangerous.","exampleCN":"调节不当的刹车可能很危险。"},{"word":"maladjusted","structure":"mal- (badly) + adjust + -ed","meaning":"unable to deal with people or situations; badly adapted","meaningCN":"适应不良的；不能正常融入环境的（mal- 表不良）","example":"The novel centres on a maladjusted young man.","exampleCN":"这部小说写的是一个适应不良的年轻人。"},{"word":"juxtapose","structure":"juxta- (near, beside) + pose (place)","meaning":"to place two things side by side for comparison","meaningCN":"把两物并置以作比较（juxta- 表在旁边，pose 表放置）","example":"The exhibition juxtaposes old photographs with new ones.","exampleCN":"展览把老照片与新照片并置。"},{"word":"juxtaposition","structure":"juxta- + position (placing)","meaning":"the act of placing things side by side","meaningCN":"并置；并列（juxta-“在旁边”+ position“放置”）","example":"The juxtaposition of wealth and poverty is the painting's subject.","exampleCN":"财富与贫穷的并置正是这幅画的主题。"}],"latinEntries":[{"word":"juxta","structure":"Latin adverb and preposition","meaning":"near, beside, close to","meaningCN":"靠近；在……旁边（adjust 与 juxtapose 的拉丁基础）"},{"word":"juxtare","structure":"verb from juxta","meaning":"to place near, put beside","meaningCN":"使靠近；放在旁边（俗拉丁语 *adjuxtare 的词根部分）"},{"word":"jungere","structure":"Latin verb","meaning":"to join, unite","meaningCN":"连接；结合（与 juxta 同族，英语 join、junction 的来源）"}]}},{"word":"administer","ipa_uk":"/əˈmɪnɪstə/","ipa_us":"/əˈmɪnɪstər/","definition_zh":"管理；掌管；执行；施用（药物、法律等）","definition_en":"to manage the running of an organization or affairs, or to put something such as a law, a drug or a test into effect","core_image":"一名侍从站在旁边，把需要的东西递到该去的地方","scene":"护士核对完腕带，拿起输液袋和药瓶。 The nurse checked the wristband and then administered the antibiotic to the patient.","sceneCN":"这里 administer 是「施用、给予（药物）」（第 4 个义项：把药物给病人用）；句意：护士核对腕带后，给病人施用了抗生素。","pos":[{"tag":"vt.","zh":"管理；掌管；执行；施用；提供"}],"collocations":[{"phrase":"administer a drug","zh":"施用药物"},{"phrase":"administer justice","zh":"执法；主持司法"},{"phrase":"administer a test","zh":"实施测试；组织考试"},{"phrase":"administer an oath","zh":"主持宣誓"},{"phrase":"administer aid","zh":"提供援助"}],"forms":[{"label":"三单（he/she/it）","form":"administers"},{"label":"过去式（已经发生）","form":"administered"},{"label":"过去分词（完成／被动）","form":"administered"},{"label":"现在分词（进行体）","form":"administering"}],"derivatives":[{"word":"administration","pos":"n.","zh":"管理；行政；政府；施行"},{"word":"administrator","pos":"n.","zh":"管理者；行政人员"},{"word":"administrative","pos":"adj.","zh":"行政的；管理的"},{"word":"administratively","pos":"adv.","zh":"在行政上；从管理角度"},{"word":"self-administered","pos":"adj.","zh":"自行实施的（如自填问卷、自行用药）"}],"senses":[{"no":"01","title":"Manage the affairs of an organization","titleCN":"管理：处理组织事务","definition":"to be in charge of the daily running of a business, fund or institution","definitionCN":"负责企业、基金或机构的日常运转","example":"She administers a fund that supports young artists.","exampleCN":"她管理一个资助年轻艺术家的基金。","why":"The Latin source means 'serve at hand'. A servant who handles the master's business ends up running it, so 'serve' slides into 'manage the affairs of'.","whyCN":"拉丁语词源意为“在旁侍奉”。侍从替主人处理事务，最终就变成掌管事务，于是“服侍”滑向“管理”。"},{"no":"02","title":"Govern a region or institution","titleCN":"治理：掌管地区或机构","definition":"to govern or direct a place, system or public body as the responsible authority","definitionCN":"作为负责机构治理或指导某地、某系统或公共团体","example":"The council administers the local schools and clinics.","exampleCN":"市政委员会管理当地的学校和诊所。","why":"Governing is management raised to the public level. The same servant figure now stands for the authority that keeps a whole region in order.","whyCN":"治理是管理被提升到公共层面。同一个侍从形象，如今代表维持整个地区秩序的权威。"},{"no":"03","title":"Carry out or enforce a law or rule","titleCN":"执行：实施法律或规则","definition":"to put a law, rule or decision into effect and see that it is obeyed","definitionCN":"使法律、规则或决定生效并确保其被遵守","example":"The agency administers the new safety rules.","exampleCN":"该机构执行新的安全规定。","why":"Once an authority manages affairs, it must also deliver the rules into real situations. Enforcing is the 'handing over' of a written rule to the people it governs.","whyCN":"权威一旦管理事务，也必须把规则送进现实情境。执行就是把纸上的规则“递交给”受其管辖的人。"},{"no":"04","title":"Give a drug or treatment","titleCN":"施用：给予药物或治疗","definition":"to give a medicine, drug or treatment to a patient","definitionCN":"把药物、药剂或治疗给病人使用","example":"The nurse administered the antibiotic through the drip.","exampleCN":"护士通过输液给病人施用了抗生素。","why":"Here the 'handing over' becomes physical: the drug is placed into the patient's body. The servant image turns into the clinical act of delivering a dose.","whyCN":"这里的“递交”变成物理动作：药物被送进病人身体。侍从的画面转化为递送一剂药的临床行为。"},{"no":"05","title":"Provide aid, relief or help","titleCN":"提供：给予援助或救济","definition":"to give help, money or relief to people who need it","definitionCN":"向需要的人提供帮助、钱款或救济","example":"A charity administered the flood relief in the villages.","exampleCN":"一家慈善机构负责向各村发放洪灾救济。","why":"Aid is something held in one pair of hands and passed to another. Providing it is the same delivery gesture as giving medicine, only the object changes.","whyCN":"援助是从一双手交到另一双手的东西。提供援助和给药是同一个递交动作，只是递的东西不同。"},{"no":"06","title":"Administer justice","titleCN":"执法：主持司法","definition":"to make the law work in practice, especially by judging and punishing fairly","definitionCN":"使法律在实际中运作，尤指公正地审判和惩处","example":"The courts administer justice, not the police alone.","exampleCN":"主持司法的是法院，而不只是警察。","why":"Justice is treated as a thing stored in the law and handed out by the court. To administer justice is to deliver that stored value to each case.","whyCN":"正义被看作存放在法律中的东西，由法庭分发。主持司法就是把这份存放的价值交付给每个案件。"},{"no":"07","title":"Administer an oath","titleCN":"主持：带领他人宣誓","definition":"to read out an oath and formally receive it from another person","definitionCN":"宣读誓词并正式接受他人宣誓","example":"The judge administered the oath to the new citizens.","exampleCN":"法官主持新公民的宣誓。","why":"An oath is a formula that must be passed from the official to the person swearing it. Administering is the formal handover of those words.","whyCN":"誓词是一套必须由官员传递给宣誓人的套语。主持宣誓就是把这些话正式交过去。"},{"no":"08","title":"Administer a test or a survey","titleCN":"实施：组织测试或问卷调查","definition":"to organize and run a test, exam or questionnaire for other people","definitionCN":"为他人组织并实施测试、考试或问卷","example":"Trained staff administer the reading test to each child.","exampleCN":"受过培训的工作人员对每个孩子实施阅读测试。","why":"The official holds the instrument of measurement and puts it in front of the candidate. Giving the test is again a delivery, this time of a task.","whyCN":"考官拿着测量工具，把它放到考生面前。发下测试同样是一次递交，这次递交的是一项任务。"},{"no":"09","title":"Administer the sacraments","titleCN":"施行：主持圣礼","definition":"of a priest, to perform a religious ceremony such as baptism or communion","definitionCN":"指神职人员施行洗礼、圣餐等宗教仪式","example":"The priest administered the sacraments to the congregation.","exampleCN":"神父为会众施行圣礼。","why":"Latin minister also meant 'attendant, priest'. The religious sense is the oldest 'serving' one: the priest serves the rite to the people on behalf of the church.","whyCN":"拉丁语 minister 也指“侍从、祭司”。宗教义是最古老的“服侍”义：神父代表教会把仪式施行给众人。"},{"no":"10","title":"Administer an estate","titleCN":"管理遗产：清理并分配财产","definition":"to manage and settle the property of a person who has died, or of a trust","definitionCN":"管理并清理死者或信托的财产","example":"A lawyer was appointed to administer the estate.","exampleCN":"一位律师被指定管理这笔遗产。","why":"An estate is a bundle of affairs left behind. Someone must take charge of them until debts are paid and property distributed, so the 'manage affairs' sense narrows to this legal duty.","whyCN":"遗产是一堆留下的待办事宜。必须有人负责到债务清偿、财产分配完毕，于是“管理事务”义收窄为这项法律职责。"}],"etymology":{"intro":{"en":"Administer came from French, but its parts are Latin: ad- 'to' plus ministrare 'to serve', from minister 'servant'. The whole history of the word is a movement from serving to managing and delivering.","cn":"administer 来自法语，但部件是拉丁语：ad-“朝向”+ ministrare“服侍”，后者来自 minister“仆人”。这个词的全部历史就是从“服侍”走向“管理”与“交付”。"},"items":[{"era":"LATE 14C","en":"English recorded aministren, later administren, in the late 14c. meaning 'to manage as a steward, control or regulate on behalf of others'.","cn":"英语在 14 世纪后期记录 aministren，后作 administren，意为“作为管家管理、代他人控制或调度”。"},{"era":"OLD FRENCH (12C)","en":"Old French aministrer meant 'help, aid, be of service to'. It already carries both the serving and the supplying idea.","cn":"古法语 aministrer 意为“帮助、援助、为……服务”，已经同时带有“服侍”和“供给”两层意思。"},{"era":"LATIN","en":"Latin administrare 'help, assist; manage, control' is ad- 'to' plus ministrare 'to serve, wait upon', from minister 'servant'. The picture is a servant standing at hand.","cn":"拉丁语 administrare“帮助、协助；管理、控制”由 ad-“朝向”加 ministrare“服侍、侍候”构成，后者来自 minister“仆人”。画面是一个侍从站在近旁待命。"},{"era":"LATIN MINISTER","en":"Minister 'servant, attendant, priest's assistant' goes back to minus 'less': the servant is the lesser member of the household. The same base gives minor, minimum and minus.","cn":"minister“仆人、侍从、祭司助手”可上溯到 minus“较少”：仆人是家中地位较低的一员。同一词基还给出 minor、minimum、minus。"},{"era":"15C–1540s","en":"The sense 'to dispense, bring into operation' (punishment, justice) is from the mid-15c. The medical sense 'to give a drug or treatment' is recorded from the 1540s.","cn":"“施行、使生效”（惩罚、司法）一义来自 15 世纪中期。“给予药物或治疗”的医学义记录于 16 世纪 40 年代。"},{"era":"MODERN ENGLISH","en":"Modern English keeps both branches: manage affairs (administer a company, an estate) and deliver something (administer a drug, a test, an oath).","cn":"现代英语保留两支：管理事务（administer a company、an estate）与交付某物（administer a drug、a test、an oath）。"}]},"similar":{"note":{"en":"The look-alike group is dominated by the administer word family, where spelling is similar but word class differs. The meaning group separates management, enforcement and physical delivery.","cn":"形近组主要是 administer 词族，拼写相近但词性不同。近义组则区分“管理”“执行”和“实物交付”三类动作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"administrate","ipa":"/ədˈmɪnɪstreɪt/","tag":"back-formation","definition":"a rare verb meaning to administer or manage. It was formed back from administration and is much less common than administer.","definitionCN":"罕用动词，意为管理、施行。它由 administration 逆构而成，远不如 administer 常用。"},{"word":"administrator","ipa":"/ədˈmɪnɪstreɪtə/","tag":"person noun","definition":"a person who manages the affairs of an organization or a computer system.","definitionCN":"管理者；行政人员；（计算机）管理员。"},{"word":"ministry","ipa":"/ˈmɪnɪstri/","tag":"shared root","definition":"a government department, or the work of a religious minister. It shares the minister root but has no ad- prefix.","definitionCN":"政府部门；牧师职务。它共享 minister 词根，但没有 ad- 前缀。"},{"word":"admonish","ipa":"/əˈmɒnɪʃ/","tag":"same ad- prefix","definition":"to warn or scold someone firmly. The root is monere 'to warn', not minister 'to serve'.","definitionCN":"告诫；严厉批评。词根是 monere“警告”，不是 minister“服侍”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manage","ipa":"/ˈmænɪdʒ/","tag":"general","definition":"to be in charge of a business, team or situation. It is the everyday word for administer in its first sense.","definitionCN":"管理；经营。它是 administer 第一义项的日常用词。"},{"word":"supervise","ipa":"/ˈsuːpəvaɪz/","tag":"oversee","definition":"to watch over people or work and make sure it is done properly. It stresses watching rather than carrying out.","definitionCN":"监督；主管。它强调“看着”，而不是亲自执行。"},{"word":"govern","ipa":"/ˈɡʌvən/","tag":"political","definition":"to control and direct a country or a region and make its laws. It is the political counterpart of administer.","definitionCN":"统治；治理。它是 administer 在政治层面的对应词。"},{"word":"dispense","ipa":"/dɪˈspens/","tag":"hand out","definition":"to give out medicine, money or justice to people. It matches the 'handing over' sense very closely.","definitionCN":"分发；配（药）；施行（正义）。它与“递交”义项非常接近。"},{"word":"enforce","ipa":"/ɪnˈfɔːs/","tag":"law","definition":"to make people obey a law or rule, using authority. It is narrower than administer and always needs an authority behind it.","definitionCN":"执行；强制实施。它比 administer 窄，且总需要有权威支撑。"},{"word":"conduct","ipa":"/kənˈdʌkt/","tag":"carry out","definition":"to organize and carry out an activity such as a test or an inquiry.","definitionCN":"组织并实施（测试、调查等活动）。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal links use the real Latin parts ad- + minister 'servant' and the genuine family administration, administrator, administrative, ministry.","cn":"正常联想只用真实的拉丁部件 ad- + minister“仆人”，以及真实词族 administration、administrator、administrative、ministry。"},"normal":[{"en":"ad- 'toward' + minister 'servant': administer literally means 'serve toward' someone — to attend and hand over what is needed.","cn":"ad-“朝向”+ minister“仆人”：administer 字面就是“朝某人服侍”——在旁边照料并把需要的东西递过去。"},{"en":"minister is the 'lesser' one (minus), the servant of the household. The same root gives ministry and ministration.","cn":"minister 是“较小者”（minus），家中的仆人。同一词根给出 ministry 和 ministration。"},{"en":"administer a drug and administer a test look different, but both are 'hand this over to the person who must receive it'.","cn":"administer a drug 和 administer a test 看似不同，其实都是“把这东西递给必须接受它的人”。"},{"en":"administration is the work, administrator the person, administrative the adjective. The suffixes -ation, -ator, -ative mark these roles.","cn":"administration 是工作，administrator 是人，administrative 是形容词。后缀 -ation、-ator、-ative 标记这些角色。"},{"en":"The verb is transitive: administer aid, administer justice. The intransitive administer to someone is formal and means 'attend to'.","cn":"这个动词通常及物：administer aid、administer justice。不及物的 administer to someone 属正式用法，意为“照料”。"}],"abstract":[{"en":"Imagine a servant standing at the side of a table, handing over whatever the master asks for.","cn":"想象一个仆人站在桌旁，把主人要的东西一一递过去。"},{"en":"Move that figure into an office: the master becomes the public or the law, and the servant becomes the official who delivers it.","cn":"把这个形象搬进办公室：主人变成公众或法律，仆人变成执行交付的官员。"},{"en":"So administering is always delivery — of order, law, medicine, aid, tests or justice.","cn":"所以 administer 的核心始终是“交付”——交付秩序、法律、药物、援助、测试或正义。"}]},"examples":[{"en":"The hospital administers the vaccine to about two hundred people a day.","cn":"这家医院每天给大约两百人接种疫苗。"},{"en":"It is the duty of the court to administer justice fairly.","cn":"公正地主持司法是法院的职责。"},{"en":"The foundation administers scholarships for rural students.","cn":"该基金会管理面向农村学生的奖学金。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿德迷你斯特”——阿德把迷你（药瓶）斯特（别）稳地递到护士手里 → administer 施用、管理","word":"administer"},"root":"源自拉丁语 administrare“服侍、照料、管理”，由 ad-“朝向”+ ministrare“服侍”构成，而 minister 为“仆人”，核心是“在旁边把该给的递过去”。","sensesIntro":{"en":"Ten senses of administer. They divide into two branches of one gesture: managing affairs on someone's behalf, and handing over a concrete thing — a law, a drug, a test, an oath or justice.","cn":"administer 的十个义项分成同一动作的两支：代替他人管理事务，以及把具体的东西——法律、药物、测试、誓词或正义——递交出去。"},"semanticMap":{"core":{"en":"CORE IMAGE: a servant at hand, passing what is needed to the one who needs it.","cn":"核心意象：一名侍从在旁，把需要的东西递到需要它的人手里。"},"chain":["TOWARD","SERVE","SERVE AT HAND","MANAGE AFFAIRS","PUT INTO EFFECT","HAND OVER WHAT IS NEEDED"],"branches":[{"senses":"S1 · S2","en":"MANAGEMENT: running a fund or a region on behalf of others.","cn":"管理：替他人管理基金或地区。"},{"senses":"S3 · S6","en":"AUTHORITY DELIVERED: a written law or an idea of justice is put into real cases.","cn":"权威的交付：把成文法律或正义观念落到具体案件里。"},{"senses":"S4 · S5","en":"PHYSICAL DELIVERY: a drug enters a body; aid passes from one hand to another.","cn":"实物交付：药物进入身体；援助从一双手交到另一双手。"},{"senses":"S7 · S8 · S9","en":"FORMAL ACTS: an oath, a test or a sacrament is performed for someone else.","cn":"正式仪式：誓词、测试或圣礼都是为他人施行的。"},{"senses":"S10","en":"PROPERTY: the legal duty of settling an estate.","cn":"财产：清理并分配遗产的法律职责。"}]},"affixes":{"intro":{"en":"administer is a prefix-root combination (ad- + minister) that has produced a large family. The suffixes -ation, -ator and -ative are all productive and easy to separate.","cn":"administer 是“前缀 + 词根”组合（ad- + minister），已衍生出庞大词族。后缀 -ation、-ator、-ative 都还有能产性，很容易拆分。"},"latinIntro":{"en":"The Latin base is minister 'servant' with the verb ministrare 'to serve'. Latin administrare adds ad- 'to'. The same base gives ministerium 'service', the source of English ministry.","cn":"拉丁语基础是 minister“仆人”及动词 ministrare“服侍”。拉丁语 administrare 加上 ad-“朝向”。同一基础还有 ministerium“服务”，即英语 ministry 的来源。"},"items":[{"word":"administer","structure":"ad- (to) + ministr- (serve) + -er (verb ending)","meaning":"to serve at hand; to manage or hand over what is needed","meaningCN":"在旁服侍；管理或递交所需之物（ad- 表朝向，ministr- 表服侍）","example":"A committee administers the relief fund.","exampleCN":"一个委员会管理这笔救济基金。"},{"word":"administration","structure":"administer + -ation (action or result noun)","meaning":"the work of managing or putting something into effect","meaningCN":"管理；行政；施行（-ation 构成行为或结果名词）","example":"She works in hospital administration.","exampleCN":"她在医院行政岗位工作。"},{"word":"administrator","structure":"administer + -ator (person who does)","meaning":"a person who manages an organization or system","meaningCN":"管理者；行政人员（-ator 表执行者）","example":"The administrator locked the shared account.","exampleCN":"管理员锁定了这个共享账户。"},{"word":"administrative","structure":"administer + -ative (relating to)","meaning":"relating to management or office work","meaningCN":"行政的；管理的（-ative 表“与……有关的”）","example":"The delay was purely administrative.","exampleCN":"这次延误纯粹是行政手续造成的。"},{"word":"administratively","structure":"administrative + -ly (in that manner)","meaning":"from the point of view of management","meaningCN":"在行政上；从管理角度（-ly 构成副词）","example":"The two schools are administratively separate.","exampleCN":"这两所学校在行政上是分开的。"},{"word":"minister","structure":"Latin minister (servant, attendant)","meaning":"a senior government official or a religious leader","meaningCN":"部长；大臣；牧师（源自拉丁语“仆人、侍从”，地位高者仍是“公仆”）","example":"The minister opened the new hospital.","exampleCN":"部长为新医院揭幕。"},{"word":"ministry","structure":"ministr- (serve) + -y (office or body)","meaning":"a government department, or the work of a religious minister","meaningCN":"政府部门；（牧师的）职务（-y 表机构或职务）","example":"The ministry of education issued the guidelines.","exampleCN":"教育部发布了这些指导方针。"},{"word":"ministration","structure":"minister + -ation (act noun)","meaning":"the act of giving help or care, often religious","meaningCN":"照料；援助；（宗教）施行（-ation 构成行为名词）","example":"The nurses' ministration calmed the old man.","exampleCN":"护士们的照料让老人平静下来。"},{"word":"maladministration","structure":"mal- (badly) + administration","meaning":"poor or dishonest management of public affairs","meaningCN":"管理不善；行政失当（mal- 表不良）","example":"The report accused the office of maladministration.","exampleCN":"报告指控该部门行政失当。"},{"word":"self-administered","structure":"self- (oneself) + administer + -ed","meaning":"given or carried out by the person himself or herself","meaningCN":"自行实施的；自己给自己用的（self- 表自身）","example":"Participants filled in a self-administered questionnaire.","exampleCN":"参与者填写了一份自填式问卷。"}],"latinEntries":[{"word":"administrare","structure":"ad- (to) + ministrare (serve)","meaning":"to serve, assist; to manage, carry out","meaningCN":"服侍、协助；管理、执行（administer 的直接来源）"},{"word":"ministrare","structure":"verb from minister","meaning":"to serve, wait upon, supply","meaningCN":"服侍；侍候；供给（minister 的动词形式）"},{"word":"minister","structure":"minus (less) + comparative ending","meaning":"servant, attendant, priest","meaningCN":"仆人；侍从；祭司（“地位较低者”，即服侍者）"},{"word":"ministerium","structure":"minister + -ium (office, function)","meaning":"service, office, ministry","meaningCN":"服务；职务；部门（英语 ministry 的来源）"}]}},{"word":"administration","ipa_uk":"/ədˌmɪnɪˈstreɪʃn/","ipa_us":"/ədˌmɪnɪˈstreɪʃn/","definition_zh":"管理；行政；政府；（药物等的）施用","definition_en":"the work of managing an organization or of putting laws, tests or medicines into effect; also the group of people who govern","core_image":"办公桌后的一整套流程：文件、印章和预算把人财物排成可执行的秩序","scene":"市政厅窗口后，工作人员核对材料、盖章、发放执照。 At the city hall counter the clerk checked the papers, stamped them, and issued the licence — that whole process is administration.","sceneCN":"这里 administration 是「行政、管理事务」（第 1 个义项：组织运转的管理工作）；句意：市政厅窗口后的工作人员核对材料、盖章、发放执照，这一整套流程就是行政管理。","pos":[{"tag":"n.","zh":"管理；行政（工作）"},{"tag":"n.","zh":"（常大写）政府；一届政府"},{"tag":"n.","zh":"施行；施用（药物、法律等）"}],"collocations":[{"phrase":"the administration of justice","zh":"司法；执法"},{"phrase":"the current administration","zh":"现任政府"},{"phrase":"hospital administration","zh":"医院管理层；医院行政"},{"phrase":"administration costs","zh":"行政开支；管理费用"},{"phrase":"the administration of a drug","zh":"药物的施用"}],"forms":[{"label":"复数（多于一个）","form":"administrations"}],"derivatives":[{"word":"administer","pos":"v.","zh":"管理；执行；施用"},{"word":"administrator","pos":"n.","zh":"管理者；行政人员"},{"word":"administrative","pos":"adj.","zh":"行政的；管理的"},{"word":"maladministration","pos":"n.","zh":"管理不善；行政失当"},{"word":"administrate","pos":"v.","zh":"管理；施行（罕用，由 administration 逆构）"}],"senses":[{"no":"01","title":"The work of managing: administration as an activity","titleCN":"管理工作：作为活动的行政","definition":"the activity of organizing and running an organization, office or system","definitionCN":"组织并运营机构、办公室或系统的活动","example":"She has ten years of experience in public administration.","exampleCN":"她有十年的公共行政经验。","why":"The suffix -ation turns the verb administer into the name of its activity. What was 'to manage affairs' becomes 'the managing of affairs' as an abstract mass noun.","whyCN":"后缀 -ation 把动词 administer 变成其活动的名称。原本“管理事务”的动作，成为一个抽象不可数的“管理工作”。"},{"no":"02","title":"The government in office","titleCN":"执政的政府","definition":"the group of people who govern a country at a particular time, often written with a capital letter","definitionCN":"在某一时期治理国家的群体，常大写","example":"The administration promised more money for rural schools.","exampleCN":"这届政府承诺为农村学校提供更多资金。","why":"A body of people who administer a country can be named by the activity itself. The abstract noun is applied to the concrete group, a common path from action to institution.","whyCN":"一群管理国家的人可以用这项活动本身来命名。抽象名词被用到具体群体上，这是“从行为到机构”的常见路径。"},{"no":"03","title":"The administrative side of an organization","titleCN":"组织中的行政部门","definition":"the department or staff within an organization that deals with records, budgets and routine decisions","definitionCN":"机构内负责记录、预算和日常事务的部门或人员","example":"Hospital administration refused to fund the new ward.","exampleCN":"医院管理层拒绝为新病房拨款。","why":"Once 'administration' names the work, it can also name the people who do that work. The abstract activity becomes a concrete office, just as 'management' can mean the managers.","whyCN":"一旦 administration 命名了这项工作，它也能命名做这项工作的人。抽象活动变成具体部门，就像 management 也可指管理层。"},{"no":"04","title":"Putting law or rules into effect","titleCN":"施行：使法律或规则生效","definition":"the act of putting a law, rule or system into practice","definitionCN":"使法律、规则或制度在实践中生效的行为","example":"The administration of justice requires independent courts.","exampleCN":"司法公正需要独立的法院。","why":"Administration keeps the 'handing over' sense of administer. Here what is handed over is a legal rule, delivered from the statute book into real cases.","whyCN":"administration 保留了 administer 的“递交”义。这里被递交的是法律规则，从法典送到真实案件里。"},{"no":"05","title":"The giving of a medicine","titleCN":"给药：药物的施用","definition":"the act of giving a drug or treatment to a patient, especially in a controlled way","definitionCN":"把药物或治疗给病人使用的行为，尤指在受控条件下","example":"The administration of the drug must be recorded in the chart.","exampleCN":"给药情况必须记录在病历上。","why":"The same abstract noun names the physical handover of a dose. The object is now a drug, but the grammatical shape is identical to 'the administration of justice'.","whyCN":"同一个抽象名词也命名一剂药的实物递交。对象换成了药物，但“the administration of justice”与“the administration of a drug”的语法形状完全一样。"},{"no":"06","title":"Administration of an estate","titleCN":"遗产管理","definition":"the legal process of collecting a dead person's assets, paying debts and distributing what remains","definitionCN":"收集死者资产、清偿债务并分配剩余财产的法律程序","example":"The administration of the estate took almost two years.","exampleCN":"遗产管理花了将近两年。","why":"An estate is a mass of unfinished business. The noun names the whole process of taking charge of that business until every account is settled.","whyCN":"遗产是一堆未了的事务。这个名词命名接管这些事务、直到每笔账都结清的全过程。"},{"no":"07","title":"Administration of the sacraments","titleCN":"圣礼的施行","definition":"the performance of religious ceremonies such as baptism and communion by a priest","definitionCN":"由神职人员施行洗礼、圣餐等宗教仪式的行为","example":"The administration of the sacraments is part of the priest's duty.","exampleCN":"施行圣礼是神父职责的一部分。","why":"Here the noun names the delivery of a rite. Because minister also meant 'priest', the religious branch has been attached to this family from the beginning.","whyCN":"这里的名词命名一项仪式的交付。因为 minister 也指“祭司”，宗教分支从一开始就附着在这个词族上。"},{"no":"08","title":"Company administration: insolvency","titleCN":"公司破产管理","definition":"a legal status in which a failing company is placed under the control of an appointed administrator","definitionCN":"破产公司被交由指定管理人接管的法律状态","example":"The chain went into administration after losing its biggest contract.","exampleCN":"这家连锁企业在失去最大合同后进入破产管理。","why":"The general sense 'management of affairs' is narrowed by law to one special procedure: an outside manager takes over a company that can no longer pay its debts.","whyCN":"一般的“事务管理”义被法律收窄为一种特殊程序：由外部管理人接管已无力偿债的公司。"},{"no":"09","title":"A term of office","titleCN":"一届任期","definition":"the period during which a particular government or president holds office","definitionCN":"某一政府或总统在任的时期","example":"Spending on health rose during the last administration.","exampleCN":"上一届任期内，卫生支出增加了。","why":"Because the word can name a government, it can also name that government's stretch of time. The institution is read along the time axis as a period.","whyCN":"因为这个词能命名一届政府，它也能命名这届政府占据的那段时间。机构被沿时间轴读成一段时期。"},{"no":"10","title":"Administration as a field of study","titleCN":"行政学：作为学科的管理","definition":"the academic subject that studies how organizations and public bodies are managed","definitionCN":"研究组织和公共机构如何被管理的学科","example":"He took a master's degree in business administration.","exampleCN":"他攻读了工商管理硕士学位。","why":"Any organized activity can become an object of study. The name of the activity becomes the name of the discipline that examines it, which is why degrees are awarded in administration.","whyCN":"任何有组织的活动都能成为研究对象。活动的名称变成研究它的学科名称，所以会有 administration 学位。"}],"etymology":{"intro":{"en":"Administration is the Latin action noun behind administer: administratio 'service, management', from administrare. English took the noun directly from Latin, which is why it keeps the full -ation ending.","cn":"administration 是 administer 背后的拉丁语行为名词：administratio“服务、管理”，来自 administrare。英语直接从拉丁语借入这个名词，所以保留了完整的 -ation 词尾。"},"items":[{"era":"MID-14C","en":"Administracioun is recorded in the mid-14c. meaning 'act of giving or dispensing'. By the late 14c. it also meant 'management of a business or property'.","cn":"administracioun 记录于 14 世纪中期，意为“给予、分配的行为”。到 14 世纪后期又表示“对事务或财产的管理”。"},{"era":"LATIN administratio","en":"Latin administratio 'aid, help, cooperation; direction, management' is the noun of action from administrare, formed with -atio much as English -ation forms nouns from verbs.","cn":"拉丁语 administratio“帮助、协作；指导、管理”是 administrare 的行为名词，用 -atio 构成，正如英语用 -ation 从动词造名词。"},{"era":"LATIN administrare","en":"The verb combines ad- 'to' with ministrare 'to serve', from minister 'servant'. The noun therefore carries the same servant image as the verb.","cn":"该动词由 ad-“朝向”加 ministrare“服侍”构成，后者来自 minister“仆人”。因此名词与动词共享同一个侍从意象。"},{"era":"EARLY 15C","en":"By the early 15c. administration also meant the management of a deceased person's estate under authority. The word spreads from household and church affairs to law and property.","cn":"到 15 世纪初，administration 还指在授权下管理死者遗产。这个词从家务与教会事务扩展到法律与财产。"},{"era":"1680s–1796","en":"The sense 'management of public affairs' is from the 1680s; 'executive power in a government' is recorded in 1731, and a U.S. president's term in office by 1796.","cn":"“公共事务的管理”一义来自 17 世纪 80 年代；“政府行政权”记录于 1731 年；美国总统的任期义到 1796 年已见记录。"},{"era":"MODERN ENGLISH","en":"Modern English uses administration for management, government, the office that manages, the act of giving a drug, and the academic subject. All are the same noun at different distances from 'serving'.","cn":"现代英语用 administration 指管理、政府、管理机构、给药行为以及行政学。它们都是同一个名词，只是离“服侍”本义远近不同。"}]},"similar":{"note":{"en":"The look-alike group is the administration word family, where the same root appears with different suffixes. The meaning group separates the activity of managing from the body that governs.","cn":"形近组是 administration 词族，同一词根配不同后缀。近义组则把“管理活动”与“治理机构”区分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"administrator","ipa":"/ədˈmɪnɪstreɪtə/","tag":"person noun","definition":"the person who carries out administration; -ator marks the doer, while -ation marks the activity.","definitionCN":"执行行政管理工作的人；-ator 标记执行者，-ation 标记活动。"},{"word":"administrative","ipa":"/ədˈmɪnɪstrətɪv/","tag":"adjective","definition":"describing something that relates to management or office work, not the work itself.","definitionCN":"形容与管理工作有关的事物，而不是工作本身。"},{"word":"administrate","ipa":"/ədˈmɪnɪstreɪt/","tag":"back-formation","definition":"the rare verb formed back from administration; administer is the normal verb.","definitionCN":"由 administration 逆构的罕用动词；常用动词是 administer。"},{"word":"ministration","ipa":"/ˌmɪnɪˈstreɪʃn/","tag":"shared root","definition":"the giving of help or care, often in a religious setting. It lacks the ad- prefix.","definitionCN":"给予帮助或照料，常用于宗教语境。它没有 ad- 前缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"management","ipa":"/ˈmænɪdʒmənt/","tag":"general","definition":"the activity of running a business or team, or the people who run it. It is the everyday equivalent of administration.","definitionCN":"经营；管理，也可指管理层。它是 administration 的日常对应词。"},{"word":"governance","ipa":"/ˈɡʌvənəns/","tag":"political","definition":"the way a country or organization is governed, especially in terms of rules and accountability.","definitionCN":"治理；治理方式，尤指规则与问责层面。"},{"word":"government","ipa":"/ˈɡʌvənmənt/","tag":"political","definition":"the group of people who govern a country; unlike administration, it is not tied to one particular term.","definitionCN":"政府；统治群体。与 administration 不同，它不限于某一届任期。"},{"word":"bureaucracy","ipa":"/bjʊəˈrɒkrəsi/","tag":"negative","definition":"the officials and rules of a large organization, often used to suggest unnecessary paperwork.","definitionCN":"官僚体系；繁文缛节，常带“手续多余”的贬义。"},{"word":"direction","ipa":"/dəˈrekʃn/","tag":"guidance","definition":"the act of guiding or controlling an activity. It stresses steering rather than day-to-day paperwork.","definitionCN":"指导；指挥。它强调“掌舵”，而不是日常文书。"},{"word":"supervision","ipa":"/ˌsuːpəˈvɪʒn/","tag":"oversight","definition":"the act of watching over work to make sure it is done correctly.","definitionCN":"监督；管理，指看着工作被正确完成。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal links use the real Latin noun administratio and the genuine family administrator, administrative, administer, maladministration.","cn":"正常联想只用真实的拉丁名词 administratio，以及真实词族 administrator、administrative、administer、maladministration。"},"normal":[{"en":"administration = administer + -ation: -ation turns the verb 'to manage' into the noun 'the managing'.","cn":"administration = administer + -ation：-ation 把动词“管理”变成名词“管理工作”。"},{"en":"A government is called an administration because it is the group that does the administering for a term.","cn":"政府被称为 an administration，因为它是那一届任期内做行政管理的一群人。"},{"en":"the administration of justice, the administration of a drug: the same 'of' pattern marks whatever is being handed out.","cn":"the administration of justice、the administration of a drug：同样的 of 结构标记出被分发交付的东西。"},{"en":"administrator is the person (-ator), administrative is the adjective (-ative), administration is the activity (-ation).","cn":"administrator 是人（-ator），administrative 是形容词（-ative），administration 是活动（-ation）。"},{"en":"In British company law, 'in administration' is a fixed phrase for a failing firm under an appointed manager.","cn":"在英国公司法里，in administration 是固定说法，指陷入困境的公司由指定管理人接管。"}],"abstract":[{"en":"Picture a desk with trays, stamps and a budget sheet: the whole repeated routine is administration.","cn":"想象一张桌子，上面有文件格、印章和预算表：这一整套反复进行的流程就是 administration。"},{"en":"The routine has three faces: the work itself, the office that does it, and the government that owns the office.","cn":"这套流程有三张面孔：工作本身、做工作的部门，以及拥有该部门的政府。"},{"en":"Anything that must be delivered by rule — justice, medicine, a test, an estate — can sit after 'the administration of'.","cn":"任何需要按规则交付的东西——正义、药物、测试、遗产——都能放在 the administration of 后面。"}]},"examples":[{"en":"The administration of the new law will cost local councils millions.","cn":"实施这项新法律将让地方议会花费数百万。"},{"en":"She works in administration at a small language school.","cn":"她在一所小型语言学校做行政工作。"},{"en":"The previous administration had raised taxes twice.","cn":"上一届政府曾两次加税。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿德迷你斯吹神”——阿德把迷你（文件）吹（到）神（气的）办公桌上 → administration 行政、管理","word":"administration"},"root":"源自拉丁语 administratio“服务、管理”，为 administrare“服侍、管理”的行为名词；词根 minister 为“仆人”，核心是“替他人把事务与规则办妥”。","sensesIntro":{"en":"Ten senses of administration. They run from the abstract activity of managing, through the office and the government that perform it, to the concrete things delivered — law, medicine, sacraments and estates.","cn":"administration 的十个义项，从抽象的管理活动，经过执行它的部门与政府，一直到被交付的具体事物——法律、药物、圣礼与遗产。"},"semanticMap":{"core":{"en":"CORE IMAGE: a desk routine that turns papers, money and people into an ordered system.","cn":"核心意象：一套案头流程，把文件、钱和人排成有序的系统。"},"chain":["SERVE","MANAGE","ORGANIZE A BODY","GOVERN","PUT INTO EFFECT","THE ADMINISTERED THING"],"branches":[{"senses":"S1 · S3 · S10","en":"THE WORK: management as an activity, the office that performs it, and the subject that studies it.","cn":"工作：作为活动的管理、执行它的部门，以及研究它的学科。"},{"senses":"S2 · S9","en":"THE GOVERNMENT: the governing body and the term it holds.","cn":"政府：执政的群体及其任期。"},{"senses":"S4","en":"LAW: putting legal rules into real cases.","cn":"法律：把法律规则落到真实案件里。"},{"senses":"S5 · S7","en":"DELIVERY: a drug given to a body; a sacrament given to a congregation.","cn":"交付：药物给到身体；圣礼给到会众。"},{"senses":"S6 · S8","en":"PROPERTY AND FAILURE: settling an estate; placing a failing company under a manager.","cn":"财产与失败：清理遗产；把濒临破产的公司交给管理人。"}]},"affixes":{"intro":{"en":"administration is one of the clearest -ation nouns in English: a verb stem plus a productive suffix, with a family that fills every word class.","cn":"administration 是英语中最清楚的 -ation 名词之一：动词词干加能产后缀，其词族填满各个词性。"},"latinIntro":{"en":"Latin administratio and administrare come from minister 'servant'. Latin ministerium 'service' gives English ministry, and the same base also yields minister and ministration.","cn":"拉丁语 administratio 与 administrare 来自 minister“仆人”。拉丁语 ministerium“服务”给出英语 ministry，同一基础还产生 minister 与 ministration。"},"items":[{"word":"administration","structure":"administer + -ation (action or result noun)","meaning":"the activity or result of managing and putting things into effect","meaningCN":"管理并施行事物的活动或结果（-ation 构成行为名词）","example":"Public administration is taught in most universities.","exampleCN":"多数大学都教授公共行政。"},{"word":"administrator","structure":"administer + -ator (person who acts)","meaning":"a person who manages an organization","meaningCN":"管理者；行政人员（-ator 表执行者）","example":"The administrator approved the budget.","exampleCN":"管理者批准了预算。"},{"word":"administrative","structure":"administer + -ative (relating to)","meaning":"relating to management or paperwork","meaningCN":"行政的；管理事务的（-ative 表“与……有关”）","example":"The problem is administrative, not technical.","exampleCN":"这个问题是行政层面的，不是技术层面的。"},{"word":"administratively","structure":"administrative + -ly (in that manner)","meaning":"in terms of management","meaningCN":"在行政上；从管理角度（-ly 构成副词）","example":"The regions are administratively independent.","exampleCN":"这些地区在行政上是独立的。"},{"word":"maladministration","structure":"mal- (badly) + administration","meaning":"bad or dishonest management of public affairs","meaningCN":"行政失当；管理不善（mal- 表不良）","example":"The ombudsman investigates maladministration.","exampleCN":"监察专员调查行政失当问题。"},{"word":"minister","structure":"Latin minister (servant, attendant)","meaning":"a senior official or a religious leader","meaningCN":"部长；大臣；牧师（原义“仆人”，高位者亦是“公仆”）","example":"The minister answered questions in parliament.","exampleCN":"部长在议会回答了提问。"},{"word":"ministry","structure":"ministr- (serve) + -y (office or body)","meaning":"a government department or the office of a minister","meaningCN":"政府部门；部长职务（-y 表机构或职务）","example":"The ministry of health issued a warning.","exampleCN":"卫生部发布了警告。"},{"word":"ministration","structure":"minister + -ation (act noun)","meaning":"the act of giving help, care or a religious rite","meaningCN":"照料；援助；宗教仪式的施行（-ation 构成行为名词）","example":"The ministration of the sick is part of the order's work.","exampleCN":"照料病人是该修会工作的一部分。"},{"word":"ministerial","structure":"minister + -ial (relating to)","meaning":"relating to a government minister or a religious minister","meaningCN":"部长的；内阁的；牧师的（-ial 表“与……有关”）","example":"The decision was taken at a ministerial meeting.","exampleCN":"这个决定是在部长级会议上作出的。"}],"latinEntries":[{"word":"administratio","structure":"administrare + -atio (action noun)","meaning":"service, management, direction","meaningCN":"服务；管理；指导（administration 的直接来源）"},{"word":"administrare","structure":"ad- (to) + ministrare (serve)","meaning":"to serve, assist; to manage","meaningCN":"服侍、协助；管理（administration 的动词基础）"},{"word":"ministerium","structure":"minister + -ium (office, function)","meaning":"service, office, ministry","meaningCN":"服务；职务；部门（英语 ministry 的来源）"}]}},{"word":"admire","ipa_uk":"/əˈmaɪə/","ipa_us":"/əˈmaɪər/","definition_zh":"钦佩；赞赏；欣赏；惊叹（古义）","definition_en":"to look at someone or something with wonder and approval","core_image":"抬头望着，惊得说不出话，随后心生敬意","scene":"美术馆里，一个学生站在画前低声说：I could admire this painting for hours.","sceneCN":"这里 admire 是「欣赏、观赏（艺术品）」（第 3 个义项：对美的欣赏）；句意：学生说这幅画他可以欣赏几个小时。可辨识物件：画框、展厅长椅、导览牌、学生的速写本。","pos":[{"tag":"vt.","zh":"钦佩；赞赏；欣赏；观赏"}],"collocations":[{"phrase":"admire someone for something","zh":"因某事钦佩某人"},{"phrase":"greatly admire","zh":"非常钦佩"},{"phrase":"admire the view","zh":"欣赏景色"},{"phrase":"admire someone's courage","zh":"钦佩某人的勇气"},{"phrase":"admire from afar","zh":"远远地仰慕"}],"forms":[{"label":"三单（he/she/it）","form":"admires"},{"label":"过去式（已经发生）","form":"admired"},{"label":"过去分词（完成／被动）","form":"admired"},{"label":"现在分词（进行体）","form":"admiring"}],"derivatives":[{"word":"admiration","pos":"n.","zh":"钦佩；赞赏"},{"word":"admirer","pos":"n.","zh":"钦佩者；爱慕者"},{"word":"admiring","pos":"adj.","zh":"赞赏的；钦佩的"},{"word":"admiringly","pos":"adv.","zh":"钦佩地；赞赏地"},{"word":"admirable","pos":"adj.","zh":"值得钦佩的；令人赞叹的"},{"word":"admirably","pos":"adv.","zh":"令人钦佩地；极好地"}],"senses":[{"no":"01","title":"Wonder: the original sense","titleCN":"惊叹：最初的意义","definition":"to feel wonder or astonishment at something (archaic or literary)","definitionCN":"对某物感到惊奇或震惊（古义或书面语）","example":"The travellers admired at the size of the ancient stones.","exampleCN":"旅人们对那些古老巨石的规模惊叹不已。","why":"Latin admirari means 'to wonder at'. The earliest English sense is pure astonishment, before any judgement of value enters; the modern 'approve' meaning grew out of this look of amazement.","whyCN":"拉丁语 admirari 意为“对……感到惊奇”。英语最早的意义是纯粹的惊讶，尚未加入价值判断；现代“赞赏”义正是从这种惊叹的目光里长出来的。"},{"no":"02","title":"Esteem a person's qualities","titleCN":"钦佩：敬重一个人的品质","definition":"to have a high opinion of someone because of their abilities, honesty or character","definitionCN":"因某人的能力、诚实或品格而对其评价很高","example":"I admire her for the way she treats her students.","exampleCN":"我钦佩她对待学生的方式。","why":"When wonder settles on a person, it becomes esteem. The upward look remains, but the object is now a character rather than an astonishing sight.","whyCN":"当惊叹落在一个人身上，它就变成敬重。向上仰望的姿态还在，但对象已从惊人的景象变成一个人的品格。"},{"no":"03","title":"Aesthetic appreciation: admire a view or a painting","titleCN":"欣赏：观赏景色或艺术品","definition":"to look at something beautiful with pleasure and approval","definitionCN":"带着愉悦与赞许观看美的事物","example":"We stood on the bridge to admire the sunset over the river.","exampleCN":"我们站在桥上欣赏河上的落日。","why":"The object of wonder can be a sight rather than a person. Beauty keeps the eyes raised and the mind pleased, so the same verb serves landscapes, paintings and buildings.","whyCN":"惊叹的对象可以是一片景象而非一个人。美让眼睛抬起、心情愉悦，于是同一个动词也用于风景、绘画和建筑。"},{"no":"04","title":"Approve of an action","titleCN":"赞赏：认可某种做法","definition":"to think that an action was done well or rightly","definitionCN":"认为某件事做得好或做得对","example":"I admire the way she handled the complaint.","exampleCN":"我赞赏她处理这起投诉的方式。","why":"Esteem can attach to a single deed, not only to a whole person. What is admired here is the handling of a situation, so the verb moves from character to conduct.","whyCN":"敬重可以附着在单件事上，而不只附着于整个的人。这里被 admire 的是处理事情的方式，于是动词从“人品”移向“行为”。"},{"no":"05","title":"Respect courage or achievement","titleCN":"敬重：佩服勇气与成就","definition":"to regard someone's courage, skill or achievement with respect","definitionCN":"对某人的勇气、技能或成就怀有敬意","example":"The whole team admired the climber's determination.","exampleCN":"全队都佩服那位登山者的决心。","why":"Courage and achievement are qualities shown under difficulty. They raise the person above the ordinary, which is exactly the 'upward' geometry of admiration.","whyCN":"勇气与成就是在困难中显现的品质。它们把人抬到常人之上，这正好就是“仰望”的几何关系。"},{"no":"06","title":"Admire oneself in the mirror","titleCN":"自我欣赏：照镜自赏","definition":"to look at oneself with pleasure and approval","definitionCN":"带着愉悦与赞许看着自己","example":"He admired himself in the mirror before the party.","exampleCN":"聚会前，他对着镜子自我欣赏了一番。","why":"The admiring gaze can be turned around: the viewer and the viewed become the same person. English allows this reflexive use, and it often carries a light tone of vanity.","whyCN":"赞赏的目光可以掉转方向：看的人与被看的人成了同一个。英语允许这种反身用法，且常带一点爱虚荣的轻松口气。"},{"no":"07","title":"Admire an object you would like to have","titleCN":"观赏：看中想要的东西","definition":"to look at an object with pleasure, often one you are thinking of buying","definitionCN":"愉悦地观看某物，常指正在考虑购买的东西","example":"She was admiring a blue coat in the shop window.","exampleCN":"她正在观赏橱窗里的一件蓝色外套。","why":"The gaze of approval can fall on possessions. Looking with pleasure at a coat or a car is still admiration, but the eye now includes a wish to own.","whyCN":"赞许的目光可以落在物品上。愉快地看一件外套或一辆车仍是 admiration，只是这目光里多了想拥有的愿望。"},{"no":"08","title":"Romantic admiration from afar","titleCN":"爱慕：远远地倾心","definition":"to be attracted to someone and think of them with warmth, often without telling them","definitionCN":"被某人吸引并怀着温情想念对方，通常不告知对方","example":"He has admired her from afar for years without saying a word.","exampleCN":"多年来他一直默默爱慕着她，从未说出口。","why":"Esteem plus distance produces romantic admiration. The person is placed above the viewer, which keeps the feeling respectful rather than possessive.","whyCN":"敬重加上距离，就产生爱慕。被爱的人被放在观看者之上，这使感情保持敬意，而不是占有。"},{"no":"09","title":"Ironic admiration: 'I admire your nerve'","titleCN":"反讽式佩服：“我真佩服你的胆量”","definition":"used ironically to express disapproval of someone's boldness or rudeness","definitionCN":"反讽用法，表达对某人冒失或无礼的不认可","example":"I admire your nerve, walking in without knocking.","exampleCN":"我真佩服你的胆量，门都不敲就进来了。","why":"Praise can be turned upside down by tone. The words stay positive while the situation makes them a criticism, so admiration becomes a polite weapon.","whyCN":"赞美可以被语调翻转。字面仍是正面词，情境却让它变成批评，于是“钦佩”成了一件礼貌的武器。"},{"no":"10","title":"Being admired: public recognition","titleCN":"受敬仰：获得公众赞誉","definition":"to be regarded with approval by many people, often over a long period","definitionCN":"被许多人长期认可与赞许","example":"The bridge is admired for its simple, clean design.","exampleCN":"这座桥因简洁干净的设计而广受赞誉。","why":"In the passive, admiration becomes a public fact rather than one person's look. A thing or a person is placed on display before many eyes, and the verb records the judgement of the crowd.","whyCN":"在被动语态里，钦佩从一个人的目光变成公共事实。某人或某物被摆到众人眼前，动词记录的是群体的判断。"}],"etymology":{"intro":{"en":"Admire is built from ad- 'to' and mirari 'to wonder'. Its history is a slow cooling of meaning: from astonished wonder in the 15th century to calm esteem and approval today.","cn":"admire 由 ad-“朝向”与 mirari“惊奇”构成。它的历史是一个缓慢降温的过程：从 15 世纪惊讶的惊叹，走到今天平静的敬重与赞赏。"},"items":[{"era":"EARLY 15C.","en":"First recorded in English with the sense 'regard with wonder or astonishment'. At this stage the word describes amazement, not approval.","cn":"最早见于英语时意为“带着惊奇或震惊地看”。在这一阶段，这个词描述的是惊讶，而不是赞赏。"},{"era":"OLD FRENCH","en":"Borrowed from Old French admirer 'to look at with wonder' (14c.), which had already narrowed the Latin verb towards the act of looking.","cn":"借自古法语 admirer“惊奇地看”（14 世纪），古法语已把拉丁动词的意义收窄到“看”这个动作上。"},{"era":"LATIN","en":"From Latin admirari 'to wonder at, be astonished at', built on ad- 'to' + mirari 'to wonder', from mirus 'wonderful'. The image is a mind turned toward something strange and great.","cn":"来自拉丁语 admirari“对……感到惊奇、震惊”，由 ad-“朝向”+ mirari“惊奇”构成，而 mirus 为“奇妙的”。画面是一颗心转向某种奇异而伟大的东西。"},{"era":"LATIN mirus FAMILY","en":"mirus 'wonderful' also gives mirabilis 'wondrous', the source of miracle and marvel, and the verb mirari underlies mirror, originally 'to look at'. All of them keep the idea of a wondering gaze.","cn":"mirus“奇妙的”还给出 mirabilis“奇异的”，即 miracle 与 marvel 的来源；动词 mirari 又是 mirror 的底层词，原意为“看”。它们都保留“惊奇注视”的意思。"},{"era":"MID-15C.","en":"The sense weakens to 'regard with esteem, approve of'. Astonishment fades as the word is used more often for people one respects than for things that shock.","cn":"词义弱化为“敬重、赞许”。当这个词更多用于自己敬重的人、而非令人震惊的事物时，惊讶的成分就淡去了。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the approving sense and adds the ironic use, as in 'I admire your nerve'. The exact date when the ironic pattern became established is source uncertain.","cn":"现代英语保留赞赏义，并增加反讽用法，如 I admire your nerve。这一反讽格式确立的确切年代「来源不确定」。"}]},"similar":{"note":{"en":"The look-alike group is built on spelling and sound; the meaning group separates respect for people from pleasure in beautiful things.","cn":"形近组依据拼写与读音；近义组则把“对人的敬重”与“对美的事物感到愉悦”分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"admiral","ipa":"/ˈædmərəl/","tag":"spelling trap","definition":"a high-ranking naval officer. It begins with the same letters but comes from Arabic amir 'commander', not from mirari.","definitionCN":"海军上将。开头字母相同，但来自阿拉伯语 amir“指挥官”，与 mirari 无关。"},{"word":"admit","ipa":"/ədˈmɪt/","tag":"same ad- prefix","definition":"to allow someone to enter, or to agree that something is true. The root is mittere 'to send', not mirari.","definitionCN":"准许进入；承认。词根是 mittere“送”，不是 mirari。"},{"word":"admonish","ipa":"/əˈmɒnɪʃ/","tag":"same ad- prefix","definition":"to warn or scold someone. The root is monere 'to warn'.","definitionCN":"告诫；责备。词根是 monere“警告”。"},{"word":"advice","ipa":"/ədˈvaɪs/","tag":"near spelling","definition":"a noun meaning an opinion about what someone should do. It looks close to admire but ends in -ice and has no root in mirari.","definitionCN":"名词，意为“建议”。拼写与 admire 接近，但以 -ice 结尾，词根与 mirari 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"respect","ipa":"/rɪˈspekt/","tag":"esteem","definition":"to think highly of someone because of their qualities or position. It is cooler and more social than admire.","definitionCN":"尊重；敬重。它比 admire 更冷静，也更社会化。"},{"word":"esteem","ipa":"/ɪˈstiːm/","tag":"formal","definition":"to value someone highly, especially for character. It is formal and slightly old-fashioned.","definitionCN":"敬重；推崇，尤指因品格。它属正式且略旧的用法。"},{"word":"revere","ipa":"/rɪˈvɪə/","tag":"strong","definition":"to respect someone or something deeply, almost religiously. It is much stronger than admire.","definitionCN":"崇敬；敬畏，几乎带宗教意味。它比 admire 强烈得多。"},{"word":"appreciate","ipa":"/əˈpriːʃieɪt/","tag":"enjoy","definition":"to enjoy something and recognize its value, especially art, music or kindness.","definitionCN":"欣赏；感激，尤指艺术、音乐或善意。"},{"word":"praise","ipa":"/preɪz/","tag":"speak well of","definition":"to say good things about someone or something, usually aloud. Admiring can stay silent; praising is spoken.","definitionCN":"赞扬；称赞，通常说出口。admire 可以默默进行，praise 必须说出来。"},{"word":"marvel","ipa":"/ˈmɑːvl/","tag":"wonder","definition":"to be filled with wonder at something. It keeps the original 'astonishment' sense that admire has mostly lost.","definitionCN":"惊叹；感到惊奇。它保留了 admire 已基本失去的那个“惊讶”原义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal links use the real Latin parts ad- + mirari 'to wonder' and the genuine family admiration, admirer, admirable, mirari relatives miracle and marvel.","cn":"正常联想只用真实的拉丁部件 ad- + mirari“惊奇”，以及真实词族 admiration、admirer、admirable，还有 mirari 的同族词 miracle、marvel。"},"normal":[{"en":"ad- 'to' + mirari 'to wonder': admire literally means 'to wonder at' something.","cn":"ad-“朝向”+ mirari“惊奇”：admire 字面就是“对某物感到惊奇”。"},{"en":"mirus 'wonderful' is the same root as miracle and marvel — all three are about an astonishing sight.","cn":"mirus“奇妙的”与 miracle、marvel 同根——三者都关于一个令人惊奇的景象。"},{"en":"admire the view and admire her courage use one verb for eyes and character, because both raise the viewer's gaze.","cn":"admire the view 与 admire her courage 用同一个动词，分别指向景物与品格，因为两者都让观看者抬起目光。"},{"en":"admiration is the noun, admirable means 'worth admiring', admirer is the person who admires.","cn":"admiration 是名词，admirable 意为“值得钦佩的”，admirer 是钦佩者。"},{"en":"admire is not envy: envy wants to take something away, admiration is content to look up.","cn":"admire 不是羡慕：羡慕想拿走什么，钦佩则满足于仰望。"}],"abstract":[{"en":"Picture a head tilted up and eyes wide: admiration begins as wonder.","cn":"想象一个头微微仰起、眼睛睁大的样子：钦佩从惊奇开始。"},{"en":"Wonder then settles into judgement: what astonishes you also seems good, so the word moves from 'be amazed' to 'think highly of'.","cn":"惊奇随后沉淀为判断：让你惊叹的东西也显得好，于是词义从“感到惊讶”转向“高度评价”。"},{"en":"The same upward look can be aimed at a view, a person or a deed — beauty, character and action all sit above the viewer.","cn":"同一种仰望可以指向景物、人或行为——美、品格与行动都位于观看者之上。"}]},"examples":[{"en":"I admire her for finishing the marathon despite her injury.","cn":"我钦佩她尽管受伤仍跑完了马拉松。"},{"en":"From the top of the hill you can admire the whole valley.","cn":"从山顶上可以欣赏整个山谷。"},{"en":"The little boy admired the fire engine for a long time.","cn":"小男孩盯着消防车看了很久。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿德买呀”——阿德看了直说“买呀”，因为实在太美了 → admire 欣赏、钦佩","word":"admire"},"root":"源自拉丁语 admirari“对……感到惊奇”，由 ad-“朝向”+ mirari“惊奇”构成，词根 mirus 意为“奇妙的”，核心是“抬头仰望、心生敬意”。","sensesIntro":{"en":"Ten senses of admire. They all keep one upward gaze, moving from astonished wonder to esteem, aesthetic pleasure, approval, romantic longing and finally public recognition.","cn":"admire 的十个义项都保留同一种仰望姿态，从惊讶的惊叹，移向敬重、审美愉悦、赞赏、爱慕，最后到公众赞誉。"},"semanticMap":{"core":{"en":"CORE IMAGE: eyes raised toward something that seems above the viewer.","cn":"核心意象：目光向上，投向某个似乎高于观看者的事物。"},"chain":["TOWARD","WONDER","LOOK UP AT","SEE SOMETHING GOOD","HOLD IN HIGH ESTEEM","PUBLIC RECOGNITION"],"branches":[{"senses":"S1","en":"WONDER: the oldest sense, amazement without judgement.","cn":"惊叹：最古老的意义，尚未加入判断的惊讶。"},{"senses":"S2 · S5","en":"ESTEEM FOR PEOPLE: character, courage and achievement raise a person above the ordinary.","cn":"对人的敬重：品格、勇气与成就是把一个人抬到常人之上。"},{"senses":"S3 · S7","en":"BEAUTY IN THINGS: a view, a painting or an object worth looking at.","cn":"事物的美：一片景色、一幅画或一件值得注视的物品。"},{"senses":"S4 · S6","en":"JUDGEMENT: a single action is approved; the same gaze can be turned on oneself.","cn":"判断：认可某一件行为；同一目光也可以转向自己。"},{"senses":"S8 · S9 · S10","en":"SOCIETY: admiration becomes longing from afar, irony in speech, or a public verdict.","cn":"社会层面：钦佩变为远远的爱慕、言语中的反讽，或公众的评判。"}]},"affixes":{"intro":{"en":"admire is a transparent Latin borrowing: ad- plus the wonder-root mir-. Its derivatives divide neatly between -ation, -er, -ing, -able and -ly.","cn":"admire 是透明的拉丁借词：ad- 加“惊奇”词根 mir-。其派生词清楚地分属 -ation、-er、-ing、-able 与 -ly。"},"latinIntro":{"en":"Latin mirari 'to wonder' comes from mirus 'wonderful'. Its family includes mirabilis 'wondrous', which gives English miracle and marvel, and the verb mirari also underlies mirror.","cn":"拉丁语 mirari“惊奇”来自 mirus“奇妙的”。同族包括 mirabilis“奇异的”，它给出英语 miracle 与 marvel；动词 mirari 也是 mirror 的底层词。"},"items":[{"word":"admire","structure":"ad- (to) + mir- (wonder) + -e (verb ending)","meaning":"to wonder at; to look up to with approval","meaningCN":"对……感到惊奇；仰望并赞许（ad- 表朝向，mir- 表惊奇）","example":"Visitors admire the old temple.","exampleCN":"游客们对这座古庙赞叹不已。"},{"word":"admiration","structure":"admir- + -ation (noun of action or feeling)","meaning":"the feeling of wonder and esteem","meaningCN":"钦佩；赞赏（-ation 构成表示行为或情感的名词）","example":"She looked at the painting with admiration.","exampleCN":"她满怀赞赏地看着那幅画。"},{"word":"admirer","structure":"admire + -er (person who does)","meaning":"a person who admires someone or something","meaningCN":"钦佩者；爱慕者（-er 表人）","example":"The singer has admirers all over the world.","exampleCN":"这位歌手在世界各地都有仰慕者。"},{"word":"admiring","structure":"admire + -ing (participial adjective)","meaning":"showing admiration","meaningCN":"赞赏的；钦佩的（-ing 构成现在分词式形容词）","example":"He gave the garden an admiring look.","exampleCN":"他赞赏地看了一眼花园。"},{"word":"admiringly","structure":"admiring + -ly (in that manner)","meaning":"in a way that shows admiration","meaningCN":"钦佩地；赞赏地（-ly 构成副词）","example":"She spoke admiringly of her mentor.","exampleCN":"她钦佩地谈起自己的导师。"},{"word":"admirable","structure":"admire + -able (worthy of being ...ed)","meaning":"deserving admiration","meaningCN":"值得钦佩的；令人赞叹的（-able 表“值得被……”）","example":"His patience was admirable.","exampleCN":"他的耐心令人钦佩。"},{"word":"admirably","structure":"admirable + -ly (in that manner)","meaning":"in a way that deserves admiration","meaningCN":"令人钦佩地；极好地（-ly 构成副词）","example":"She handled the crisis admirably.","exampleCN":"她非常出色地处理了这场危机。"},{"word":"unadmired","structure":"un- (not) + admired","meaning":"not admired; without admirers (rare)","meaningCN":"不受钦佩的；无人赞赏的（un- 表否定，罕用）","example":"The building stood unadmired for decades.","exampleCN":"这栋楼几十年来无人赞赏。"},{"word":"marvel","structure":"mir- (wonder) → mirabilia → Old French merveille","meaning":"to be filled with wonder; a wonderful thing","meaningCN":"惊叹；奇迹（同一“惊奇”词根的另一个英语分支）","example":"We marvelled at the size of the canyon.","exampleCN":"我们惊叹于峡谷的规模。"},{"word":"miracle","structure":"mir- (wonder) + -acle (result noun)","meaning":"an astonishing event that seems beyond natural explanation","meaningCN":"奇迹；不可思议的事（mir- 表惊奇，-acle 构成结果名词）","example":"It was a miracle that no one was hurt.","exampleCN":"没有人受伤真是个奇迹。"}],"latinEntries":[{"word":"admirari","structure":"ad- (to) + mirari (wonder)","meaning":"to wonder at, be astonished at","meaningCN":"对……感到惊奇；震惊（admire 的直接来源）"},{"word":"mirari","structure":"deponent verb from mirus","meaning":"to wonder, be surprised","meaningCN":"惊奇；感到惊讶（mirus 的动词形式）"},{"word":"mirus","structure":"Latin adjective","meaning":"wonderful, astonishing","meaningCN":"奇妙的；令人惊讶的（同族词 miracle、marvel 的词根）"},{"word":"mirabilis","structure":"mirari + -bilis (able to be ...ed)","meaning":"wondrous, marvellous","meaningCN":"奇异的；奇妙的（英语 marvel 的拉丁来源）"}]}}]);
